VRT_L("1re-c-physique-r18",{"duree":20,"titre":"Les générateurs électriques","accroche":"La pile ne délivre pas toute sa f.é.m.","intro":"Un générateur réel a une force électromotrice et une résistance interne.","objectifs":["schématiser un générateur","appliquer U = E − rI","associer des générateurs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un générateur linéaire a pour caractéristique <strong>U = E − rI</strong>, E étant sa force électromotrice (V) et r sa résistance interne (Ω).</div>"},{"t":"Associations","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":18,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un réparateur de radios de Bafang associe 4 piles de 1,5 V en série pour un poste.","tache":"Calcule la f.é.m. obtenue."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r19",{"duree":20,"titre":"Les récepteurs électriques","accroche":"Moteurs et électrolyseurs ont une f.c.é.m.","intro":"Un récepteur actif convertit l'énergie électrique en une autre forme que la chaleur.","objectifs":["schématiser un récepteur","appliquer U = E' + r'I","distinguer récepteurs passifs et actifs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un récepteur actif linéaire (moteur, électrolyseur) vérifie <strong>U = E' + r'I</strong>, E' étant sa force contre-électromotrice.</div>"},{"t":"Récepteurs passifs","verrou":true,"illus":{"legende":"Caractéristiques U = f(I) et point de fonctionnement.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Caractéristiques intensité-tension : générateur U = E − r·I, récepteur (électrolyseur, moteur) U = E&#39; + r&#39;·I, résistor U = R·I ; point de fonctionnement à l&#39;intersection.' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Caractéristiques U = f(I) et point de fonctionnement</text><path d='M60 270V40M60 270H300' fill='none' stroke='#142554' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M60 270L60 38' stroke='#142554' stroke-width='1' fill='none'/><path d='M60 38L62.4 43.5L57.6 43.5Z' fill='#142554'/><path d='M60 270L302 270' stroke='#142554' stroke-width='1' fill='none'/><path d='M302 270L296.5 272.4L296.5 267.6Z' fill='#142554'/><text x='56' y='44' font-size='9' font-weight='700' text-anchor='end' fill='#142554'>U (V)</text><text x='300' y='284' font-size='9' text-anchor='end' fill='#142554'>I (A)</text><path d='M60 70L290 230' fill='none' stroke='#C0392B' stroke-width='2.4' stroke-linejoin='round' stroke-linecap='round'/><path d='M60 160L290 80' fill='none' stroke='#1F6FB2' stroke-width='2.4' stroke-linejoin='round' stroke-linecap='round'/><path d='M60 270L250 50' fill='none' stroke='#2E8B57' stroke-width='1.6' stroke-dasharray='5 3' stroke-linejoin='round' stroke-linecap='round'/><circle cx='177' cy='119' r='5' fill='#7A4FB3'/><path d='M177 119V270M60 119H177' fill='none' stroke='#7A4FB3' stroke-width='0.8' stroke-dasharray='3 3' stroke-linejoin='round' stroke-linecap='round'/><text x='186' y='142' font-size='9' font-weight='700' text-anchor='start' fill='#7A4FB3'>P (point de<tspan x='186' dy='10.35'>fonctionnement)</tspan></text><text x='54' y='74' font-size='10' font-weight='700' text-anchor='end' fill='#C0392B'>E</text><text x='54' y='164' font-size='10' font-weight='700' text-anchor='end' fill='#1F6FB2'>E&#39;</text><text x='250' y='238' font-size='9' font-weight='700' text-anchor='start' fill='#C0392B'>générateur</text><text x='250' y='76' font-size='9' font-weight='700' text-anchor='start' fill='#1F6FB2'>récepteur</text><text x='196' y='52' font-size='9' font-weight='700' text-anchor='start' fill='#2E8B57'>résistor</text><rect x='320' y='40' width='152' height='250' rx='6' fill='#fff' stroke='#9AA5B8' stroke-width='1'/><text x='330' y='60' font-size='10' font-weight='700' text-anchor='start' fill='#142554'>Lois d&#39;Ohm</text><text x='330' y='82' font-size='9.5' font-weight='600' text-anchor='start' fill='#C0392B'>générateur :<tspan x='330' dy='10.924999999999999'>U = E − r·I</tspan></text><text x='330' y='122' font-size='9.5' font-weight='600' text-anchor='start' fill='#1F6FB2'>récepteur actif :<tspan x='330' dy='10.924999999999999'>U = E&#39; + r&#39;·I</tspan></text><text x='330' y='162' font-size='9.5' font-weight='600' text-anchor='start' fill='#2E8B57'>résistor : U = R·I</text><text x='330' y='192' font-size='9' text-anchor='start' fill='#142554'>Bilan de puissance<tspan x='330' dy='10.35'>(générateur) :</tspan><tspan x='330' dy='10.35'>E·I = U·I + r·I²</tspan><tspan x='330' dy='10.35'>rendement η = U / E</tspan></text><text x='330' y='262' font-size='9' font-weight='600' text-anchor='start' fill='#142554'>Effet Joule :<tspan x='330' dy='10.35'>𝒫 = R·I²</tspan></text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":19,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un ventilateur alimenté par un panneau solaire à Maroua a une f.c.é.m. de 6 V et une résistance interne de 2 Ω.","tache":"Calcule la tension à ses bornes pour 0,5 A."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r20",{"duree":20,"titre":"Point de fonctionnement d'un circuit","accroche":"Là où générateur et récepteur s'accordent.","intro":"Le point de fonctionnement est l'intersection des caractéristiques du générateur et du récepteur.","objectifs":["trouver graphiquement le point","appliquer la loi de Pouillet","exploiter la caractéristique d'une diode"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>point de fonctionnement</strong> d'un circuit est le point (I ; U) commun aux caractéristiques du générateur et du récepteur.</div>"},{"t":"Loi de Pouillet","verrou":true},{"t":"Diode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":20,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de chantier à Edéa, de résistance 10 Ω, est branchée sur une batterie de 12 V et 2 Ω.","tache":"Détermine le point de fonctionnement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r21",{"duree":20,"titre":"Champ magnétique et flux magnétique","accroche":"Compter les lignes de champ qui traversent une bobine.","intro":"Le flux magnétique mesure la quantité de champ qui traverse une surface.","objectifs":["décrire un champ magnétique","calculer le champ d'un solénoïde","calculer un flux"],"parties":[{"t":"Champ magnétique","html":"<div class='def'><b>Définition</b>Le <strong>champ magnétique</strong> B⃗ se mesure en teslas (T) au teslamètre. Dans un solénoïde long : B = μ₀NI/L, μ₀ = 4π × 10⁻⁷ SI.</div>"},{"t":"Flux","html":"<p class='formule'>Φ = N × B × S × cos θ (en webers, Wb)</p><p>θ est l'angle entre B⃗ et la normale à la spire.</p>","labo":{"type":"calcul","f":"filb","vals":{"I":10,"d":2}},"illus":{"legende":"Lignes de champ magnétique : aimant et solénoïde.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Champ magnétique : lignes de champ d&#39;un aimant droit (du nord vers le sud à l&#39;extérieur) et d&#39;un solénoïde parcouru par un courant ; B = μ₀·N·I / L.' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Lignes de champ magnétique</text><rect x='60' y='130' width='60' height='30' fill='#C0392B'/><rect x='120' y='130' width='60' height='30' fill='#1F6FB2'/><text x='90' y='150' font-size='12' font-weight='800' text-anchor='middle' fill='#fff'>N</text><text x='150' y='150' font-size='12' font-weight='800' text-anchor='middle' fill='#fff'>S</text><path d='M60 140C28 106 212 106 180 140M60 150C28 184 212 184 180 150' fill='none' stroke='#636A80' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M60 140C16 82 224 82 180 140M60 150C16 208 224 208 180 150' fill='none' stroke='#636A80' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M60 140C4 58 236 58 180 140M60 150C4 232 236 232 180 150' fill='none' stroke='#636A80' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M118 116L126 116' stroke='#636A80' stroke-width='1.6' fill='none'/><path d='M126 116L120.5 118.4L120.5 113.6Z' fill='#636A80'/><path d='M118 174L126 174' stroke='#636A80' stroke-width='1.6' fill='none'/><path d='M126 174L120.5 176.4L120.5 171.6Z' fill='#636A80'/><path d='M118 92L126 92' stroke='#636A80' stroke-width='1.6' fill='none'/><path d='M126 92L120.5 94.4L120.5 89.6Z' fill='#636A80'/><path d='M118 198L126 198' stroke='#636A80' stroke-width='1.6' fill='none'/><path d='M126 198L120.5 200.4L120.5 195.6Z' fill='#636A80'/><text x='120' y='250' font-size='9' text-anchor='middle' fill='#142554'>aimant droit : les lignes sortent<tspan x='120' dy='10.35'>par le nord et entrent par le sud</tspan></text><ellipse cx='270' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='286' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='302' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='318' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='334' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='350' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='366' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='382' cy='145' rx='6' ry='26' fill='none' stroke='#C77D0A' stroke-width='2'/><path d='M240 125H410M240 145H410M240 165H410' fill='none' stroke='#1F6FB2' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M380 125L400 125' stroke='#1F6FB2' stroke-width='1.6' fill='none'/><path d='M400 125L394.5 127.4L394.5 122.6Z' fill='#1F6FB2'/><path d='M380 145L400 145' stroke='#1F6FB2' stroke-width='1.6' fill='none'/><path d='M400 145L394.5 147.4L394.5 142.6Z' fill='#1F6FB2'/><path d='M380 165L400 165' stroke='#1F6FB2' stroke-width='1.6' fill='none'/><path d='M400 165L394.5 167.4L394.5 162.6Z' fill='#1F6FB2'/><path d='M410 125C460 100 460 60 330 60C200 60 200 100 240 125' fill='none' stroke='#1F6FB2' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><path d='M410 165C460 190 460 230 330 230C200 230 200 190 240 165' fill='none' stroke='#1F6FB2' stroke-width='1' stroke-linejoin='round' stroke-linecap='round'/><text x='424' y='150' font-size='12' font-weight='800' text-anchor='start' fill='#C0392B'>N</text><text x='226' y='150' font-size='12' font-weight='800' text-anchor='end' fill='#1F6FB2'>S</text><path d='M260 196L260 176' stroke='#C0392B' stroke-width='1.6' fill='none'/><path d='M260 176L262.9 182.4L257.1 182.4Z' fill='#C0392B'/><text x='262' y='208' font-size='10' font-weight='700' text-anchor='start' fill='#C0392B'>I</text><text x='330' y='258' font-size='9' text-anchor='middle' fill='#142554'>solénoïde : champ uniforme à l&#39;intérieur</text><text x='330' y='276' font-size='9.5' font-weight='700' text-anchor='middle' fill='#7A4FB3'>B = μ₀ · N · I / L  (μ₀ = 4π·10⁻⁷ SI)</text><text x='240' y='298' font-size='8.8' text-anchor='middle' fill='#636A80'>Flux à travers une bobine de N spires de surface S : Φ = N · B · S · cos θ (en webers).</text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Exemple","html":"<p>100 spires de 50 cm² dans B = 0,2 T, normale parallèle à B⃗ : Φ = 100 × 0,2 × 0,005 = 0,1 Wb.</p>","retenir":"Flux maximal pour θ = 0."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le champ magnétique s'exprime en :</p><ol type='a'><li>webers</li><li>teslas</li><li>volts</li><li>ampères</li></ol><details><summary>Voir la réponse</summary><p><strong>teslas</strong>. L'unité du champ magnétique est le tesla, de symbole T.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Flux pour θ = 90° ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Une bobine de 200 spires de rayon 3 cm est placée dans un champ magnétique uniforme de 0,05 T, sa normale parallèle au champ.</p><p><strong>Consigne 1.</strong> Calcule le flux magnétique maximal.</p><p><strong>Consigne 2.</strong> Calcule le flux quand la bobine a tourné de 60°.</p><details><summary>Voir une réponse attendue</summary><p>S = π × 0,03² ≈ 2,83 × 10⁻³ m² ; Φ = 200 × 0,05 × 2,83 × 10⁻³ ≈ 2,8 × 10⁻² Wb. À 60° : Φ ≈ 1,4 × 10⁻² Wb.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Tesla.","Solénoïde.","Φ = NBS cos θ."],"exo":"<p>Flux pour θ = 90° ? <em>(Réponse : 0.)</em></p>","quiz":[{"q":"Le champ magnétique s'exprime en :","r":["webers","teslas","volts","ampères"],"b":1,"e":"L'unité du champ magnétique est le tesla, de symbole T."},{"q":"Le flux magnétique à travers une surface vaut :","r":["Φ = B / S","Φ = B + S","Φ = B S cos θ","Φ = S / B"],"b":2,"e":"θ angle entre B et la normale."},{"q":"Le flux s'exprime en :","r":["teslas","henrys","ohms","webers"],"b":3,"e":"Le flux s'exprime en webers : 1 Wb = 1 T·m²."},{"q":"Le flux est maximal quand le champ est :","r":["perpendiculaire à la surface","parallèle à la surface du circuit","nul","variable"],"b":0,"e":"θ = 0 entre B et la normale."},{"q":"Le flux est nul quand le champ est :","r":["perpendiculaire à la surface","parallèle à la surface","très intense","uniforme"],"b":1,"e":"Aucune ligne ne traverse la surface."},{"q":"Une bobine de 100 spires de 10 cm² dans un champ de 0,2 T normal : flux total :","r":["2 Wb","0,2 Wb","0,02 Wb","200 Wb"],"b":2,"e":"N B S = 100 × 0,2 × 10⁻³."},{"q":"Les lignes de champ d'un aimant droit sortent :","r":["par le pôle sud","par le milieu","de nulle part","par le pôle nord"],"b":3,"e":"Elles rentrent par le pôle sud."},{"q":"Un solénoïde parcouru par un courant crée à l'intérieur :","r":["un champ uniforme","aucun champ","un champ très variable","un champ électrique seulement"],"b":0,"e":"Parallèle à son axe."},{"q":"Le champ dans un solénoïde vaut :","r":["μ₀ / (n I)","μ₀ n I","n / I","I / n"],"b":1,"e":"n est le nombre de spires par mètre."},{"q":"Une boussole s'oriente selon :","r":["la lumière et la température ambiantes","le vent","le champ magnétique local","la température"],"b":2,"e":"Son aiguille est un petit aimant."}],"c":"1re C","m":"physique","rang":21,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un électricien de Douala étudie une bobine de 100 spires de 50 cm² placée dans un champ de 0,2 T.","tache":"Calcule le flux maximal."},"gratuit":true});
VRT_L("1re-c-physique-r22",{"duree":20,"titre":"Induction et auto-induction","accroche":"Un flux qui varie crée une tension.","intro":"Toute variation de flux à travers un circuit y fait naître une force électromotrice induite.","objectifs":["énoncer la loi de Faraday","appliquer la loi de Lenz","décrire l'auto-induction"],"parties":[{"t":"Loi de Faraday","html":"<div class='def'><b>Définition</b>Une variation de flux crée une <strong>f.é.m. induite</strong> e = −ΔΦ/Δt. Le courant induit s'oppose, par ses effets, à la cause qui lui donne naissance (<strong>loi de Lenz</strong>).</div>"},{"t":"Exemple","verrou":true},{"t":"Auto-induction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":22,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de vélo d'un élève de Bamenda s'allume grâce à une dynamo.","tache":"Explique l'origine du courant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r23",{"duree":20,"titre":"Les générateurs électromagnétiques","accroche":"De Song Loulou à la dynamo de vélo.","intro":"L'alternateur transforme une énergie mécanique de rotation en énergie électrique alternative.","objectifs":["décrire un alternateur","relier fréquence et vitesse de rotation","citer des exemples"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Un <strong>alternateur</strong> comprend un rotor (aimant ou électroaimant) qui tourne devant un stator (bobines). La variation de flux crée une tension alternative.</div>"},{"t":"Fréquence","verrou":true,"illus":{"legende":"Induction électromagnétique et alternateur.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Induction électromagnétique : un aimant qui s&#39;approche d&#39;une bobine crée un courant induit (loi de Lenz) ; principe de l&#39;alternateur ; e = −dΦ/dt.' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>L&#39;induction électromagnétique et l&#39;alternateur</text><rect x='30' y='100' width='44' height='26' fill='#C0392B'/><rect x='74' y='100' width='44' height='26' fill='#1F6FB2'/><text x='52' y='118' font-size='11' font-weight='800' text-anchor='middle' fill='#fff'>S</text><text x='96' y='118' font-size='11' font-weight='800' text-anchor='middle' fill='#fff'>N</text><path d='M130 92L170 92' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M170 92L163.6 94.9L163.6 89.1Z' fill='#142554'/><text x='150' y='84' font-size='8.6' text-anchor='middle' fill='#142554'>on approche</text><ellipse cx='190' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='202' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='214' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='226' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='238' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><ellipse cx='250' cy='113' rx='5' ry='22' fill='none' stroke='#C77D0A' stroke-width='2'/><path d='M190 135V180H240M250 180H270V135' fill='none' stroke='#142554' stroke-width='1.4' stroke-linejoin='round' stroke-linecap='round'/><circle cx='245' cy='180' r='12' fill='#fff' stroke='#142554'/><text x='245' y='184' font-size='10' font-weight='800' text-anchor='middle' fill='#142554'>G</text><text x='150' y='214' font-size='9' text-anchor='middle' fill='#142554'>Courant induit tant que le flux varie ;<tspan x='150' dy='10.35'>il s&#39;oppose à la cause qui le crée (Lenz) :</tspan><tspan x='150' dy='10.35'>la face de la bobine devient un pôle N.</tspan></text><text x='150' y='272' font-size='12' font-weight='800' text-anchor='middle' fill='#7A4FB3'>e = − dΦ / dt</text><circle cx='390' cy='130' r='60' fill='none' stroke='#636A80' stroke-width='1' stroke-dasharray='4 3'/><g transform='rotate(-30 390 130)'><rect x='350' y='120' width='40' height='20' fill='#C0392B'/><rect x='390' y='120' width='40' height='20' fill='#1F6FB2'/></g><path d='M380 70C380 50 410 50 410 70' fill='none' stroke='#2E8B57' stroke-width='2' stroke-linejoin='round' stroke-linecap='round'/><rect x='370' y='56' width='40' height='16' rx='4' fill='none' stroke='#C77D0A' stroke-width='3'/><rect x='370' y='188' width='40' height='16' rx='4' fill='none' stroke='#C77D0A' stroke-width='3'/><path d='M350 130A40 40 0 0 1 380 92' fill='none' stroke='#142554' stroke-width='1.2' stroke-linejoin='round' stroke-linecap='round'/><path d='M372 94L380 92' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M380 92L375.3 95.7L374.1 91.0Z' fill='#142554'/><text x='390' y='226' font-size='9' text-anchor='middle' fill='#142554'>ALTERNATEUR : aimant<tspan x='390' dy='10.35'>(rotor) qui tourne devant</tspan><tspan x='390' dy='10.35'>des bobines (stator)</tspan></text><text x='390' y='274' font-size='8.6' text-anchor='middle' fill='#636A80'>→ tension alternative ;<tspan x='390' dy='9.889999999999999'>barrage d&#39;Edéa, Song Loulou</tspan></text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":23,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un groupe électrogène d'un quartier de Bertoua doit fournir du 50 Hz avec un alternateur à 2 paires de pôles.","tache":"À quelle vitesse le moteur doit-il tourner ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r24",{"duree":20,"titre":"Énergie, puissance et rendement électriques","accroche":"Toute l'énergie n'arrive pas à destination.","intro":"Dans une chaîne énergétique, chaque convertisseur perd une partie de l'énergie, surtout en chaleur.","objectifs":["faire le bilan d'un générateur","faire le bilan d'un récepteur","calculer le rendement d'une chaîne"],"parties":[{"t":"Générateur","html":"<div class='def'><b>Définition</b>Un générateur fournit la puissance totale EI, en perd rI² par effet Joule et délivre UI. Son <strong>rendement</strong> vaut ρ = UI/EI = U/E.</div>"},{"t":"Récepteur","verrou":true},{"t":"Chaîne énergétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":24,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un kit solaire d'une école de Kousseri alimente une pompe : batterie de rendement 83 %, moteur de rendement 86 %.","tache":"Calcule le rendement global et propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r01",{"duree":20,"titre":"Présentation du programme et évaluation diagnostique","accroche":"Ce que tu vas apprendre cette année en SVT.","intro":"La première séance présente le programme de Première et vérifie les acquis de Seconde.","objectifs":["connaître les grands modules","repérer ses acquis","s'organiser"],"parties":[{"t":"Le programme","html":"<div class='def'><b>Définition</b>Le <strong>programme de SVTEEHB de Première</strong> traite de l'énergie dans les organismes, de la santé (immunité, nutrition, santé reproductive) et de la Terre et de l'environnement.</div>"},{"t":"Les acquis à vérifier","html":"<ul><li>La cellule et ses organites.</li><li>La digestion et la circulation.</li><li>Les roches et les paysages.</li></ul>","labo":{"type":"etapes","items":[["Énergie","respiration, fermentation."],["Santé","immunité, nutrition."],["Terre","roches, plaques, climat."]]}},{"t":"Méthode de travail","html":"<p>Réviser chaque séance, schématiser, s'entraîner aux situations d'intégration.</p>","retenir":"Un schéma vaut mieux qu'un long texte."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Le programme de SVTEEHB de 1re C aborde notamment :</p><ol type='a'><li>l'énergétique, l'immunité, la santé et la géologie externe et interne</li><li>la botanique, la zoologie et la classification des plantes à fleurs</li><li>la génétique des populations et l'évolution des espèces</li><li>la chimie organique et les réactions d'oxydoréduction</li></ol><details><summary>Voir la réponse</summary><p><strong>l'énergétique, l'immunité, la santé et la géologie externe et interne</strong>. Il couvre biologie, santé, environnement et sciences de la Terre.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Cite un organite et sa fonction.</p><details><summary>Voir la réponse</summary><p>(Exemple : la mitochondrie, respiration.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Améliorer la production d'énergie par l'organisme.</p><p><strong>Situation.</strong> En début d'année, un élève de 1re C de Bertoua doit montrer qu'il maîtrise les acquis de Seconde : la cellule, la digestion, les roches.</p><p><strong>Consigne 1.</strong> Schématise une cellule animale légendée.</p><p><strong>Consigne 2.</strong> Cite le rôle d'un organite, d'une enzyme digestive et donne un exemple de roche sédimentaire.</p><details><summary>Voir une réponse attendue</summary><p>Schéma : membrane, cytoplasme, noyau, mitochondries. Mitochondrie : respiration ; amylase : hydrolyse de l'amidon ; calcaire ou grès.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Trois grands domaines.","Acquis.","Méthode."],"exo":"<p>Cite un organite et sa fonction. <em>(Exemple : la mitochondrie, respiration.)</em></p>","quiz":[{"q":"Le programme de SVTEEHB de 1re C aborde notamment :","r":["l'énergétique, l'immunité, la santé et la géologie externe et interne","la botanique, la zoologie et la classification des plantes à fleurs","la génétique des populations et l'évolution des espèces","la chimie organique et les réactions d'oxydoréduction"],"b":0,"e":"Il couvre biologie, santé, environnement et sciences de la Terre."},{"q":"L'évaluation diagnostique sert à :","r":["donner la note du premier trimestre aux élèves","repérer les acquis et les lacunes au début de l'année","remplacer les premières leçons du programme de l'année","choisir la série de chaque élève pour l'année suivante"],"b":1,"e":"Elle oriente les révisions nécessaires."},{"q":"L'épreuve de SVT au Probatoire comporte :","r":["un QCM de quarante questions et une dictée scientifique notée sur vingt","une dissertation et un commentaire de texte scientifique","une évaluation des ressources et une évaluation des compétences","un travail pratique et un exposé oral devant le jury"],"b":2,"e":"C'est le format de l'approche par compétences."},{"q":"Une compétence est :","r":["une définition apprise par cœur puis récitée sans erreur","la note obtenue à un devoir surveillé ou à un examen","un chapitre du programme officiel enseigné dans la classe pendant un trimestre","la capacité à mobiliser des savoirs pour résoudre une situation"],"b":3,"e":"Elle s'évalue à partir de situations de vie."},{"q":"Une situation-problème présente :","r":["un contexte réel, des documents et une tâche","seulement une question de cours à réciter","une liste de mots-clés sans contexte","un dessin libre sans consigne précise"],"b":0,"e":"Elle demande d'utiliser les connaissances pour agir."},{"q":"Dans une démarche scientifique, l'hypothèse est suivie :","r":["de la conclusion directe","d'une expérience pour la tester","d'une affiche de synthèse","d'un slogan de sensibilisation"],"b":1,"e":"L'expérience confirme ou infirme l'hypothèse."},{"q":"La dépense énergétique est étudiée dans la partie :","r":["immunologie et santé","géologie externe","énergétique biologique","santé de la reproduction"],"b":2,"e":"Elle relie respiration, alimentation et activité."},{"q":"Les séismes sont étudiés dans la partie :","r":["énergétique biologique","immunologie et santé","alimentation humaine","géologie interne"],"b":3,"e":"On y étudie les ondes sismiques et la structure du globe."},{"q":"Le VIH est étudié dans la partie :","r":["immunologie et santé","géologie externe","écosystèmes et énergie","climat et atmosphère"],"b":0,"e":"On y étudie le soi, le non-soi et les cellules immunitaires."},{"q":"Une bonne méthode de travail en SVT consiste à :","r":["apprendre le cours par cœur sans chercher à comprendre","relier chaque notion à un document et à une situation","ignorer les schémas et ne retenir que les définitions","réviser seulement la veille de chaque devoir surveillé"],"b":1,"e":"Les épreuves exploitent des documents."}],"c":"1re C","m":"svt","rang":1,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève arrivant en 1re C au lycée de Bertoua veut s'organiser pour l'année.","tache":"Propose-lui trois conseils."},"gratuit":true});
VRT_L("1re-c-svt-r02",{"duree":20,"titre":"Rappels : rôles des aliments et digestion","accroche":"Du plat de ndolé aux nutriments.","intro":"La digestion transforme les aliments en nutriments assimilables.","objectifs":["citer les rôles des aliments","décrire la digestion","nommer les enzymes"],"parties":[{"t":"Rôles des aliments","html":"<div class='def'><b>Définition</b>Les aliments ont un rôle <strong>énergétique</strong> (glucides, lipides), <strong>bâtisseur</strong> (protides, calcium) et <strong>fonctionnel</strong> (vitamines, sels minéraux).</div>"},{"t":"Digestion","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":2,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une mère de Douala prépare du ndolé avec plantain et viande.","tache":"Indique les nutriments obtenus après digestion de ce repas."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r03",{"duree":20,"titre":"Rappels : absorption intestinale et circulation","accroche":"Des villosités au sang.","intro":"Les nutriments passent dans le sang et la lymphe, qui les distribuent aux cellules.","objectifs":["décrire l'absorption","distinguer sang et lymphe","expliquer la distribution"],"parties":[{"t":"Absorption","html":"<div class='def'><b>Définition</b>L'<strong>absorption intestinale</strong> est le passage des nutriments de l'intestin grêle vers le sang et la lymphe, à travers les <strong>villosités</strong>.</div>"},{"t":"Deux voies","verrou":true,"illus":{"legende":"Artère, veine, capillaire et double circulation.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Coupes d&#39;une artère, d&#39;une veine et d&#39;un capillaire sanguin ; schéma de la double circulation.' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Les vaisseaux sanguins et la double circulation</text><ellipse cx='60' cy='90' rx='38' ry='38' fill='#F3B8B8' stroke='#C0392B' stroke-width='8'/><ellipse cx='60' cy='90' rx='16' ry='16' fill='#fff' stroke='#C0392B' stroke-width='1.2'/><text x='60' y='148' font-size='9' text-anchor='middle' fill='#142554'>artère<tspan x='60' dy='10.35'>paroi épaisse,</tspan><tspan x='60' dy='10.35'>élastique</tspan></text><path d='M128 70C150 56 186 60 194 80C204 104 190 126 160 128C134 130 116 96 128 70Z' fill='#DCEBF7' stroke='#1F6FB2' stroke-width='3' stroke-linejoin='round' stroke-linecap='round'/><path d='M150 86L160 100L170 86' fill='none' stroke='#1F6FB2' stroke-width='1.5' stroke-linejoin='round' stroke-linecap='round'/><text x='162' y='148' font-size='9' text-anchor='middle' fill='#142554'>veine<tspan x='162' dy='10.35'>paroi mince,</tspan><tspan x='162' dy='10.35'>valvules</tspan></text><ellipse cx='244' cy='92' rx='8' ry='8' fill='#fff' stroke='#7A4FB3' stroke-width='1.5'/><text x='244' y='148' font-size='9' text-anchor='middle' fill='#142554'>capillaire<tspan x='244' dy='10.35'>une seule couche</tspan><tspan x='244' dy='10.35'>de cellules :</tspan><tspan x='244' dy='10.35'>lieu des échanges</tspan></text><rect x='330' y='34' width='120' height='28' rx='6' fill='#DCEBF7' stroke='#9AA5B8' stroke-width='1'/><text x='390' y='51.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>poumons</text><rect x='330' y='238' width='120' height='28' rx='6' fill='#FBE7C2' stroke='#9AA5B8' stroke-width='1'/><text x='390' y='255.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>organes</text><rect x='350' y='112' width='36' height='70' rx='4' fill='#C9D9F0' stroke='#1F6FB2' stroke-width='1'/><rect x='394' y='112' width='36' height='70' rx='4' fill='#F3B8B8' stroke='#C0392B' stroke-width='1'/><text x='390' y='105' font-size='9.5' font-weight='700' text-anchor='middle' fill='#142554'>cœur</text><text x='368' y='150' font-size='10.5' font-weight='700' text-anchor='middle' fill='#142554'>D</text><text x='412' y='150' font-size='10.5' font-weight='700' text-anchor='middle' fill='#142554'>G</text><path d='M360 112L360 64' stroke='#1F6FB2' stroke-width='1.6' fill='none'/><path d='M360 64L362.9 70.4L357.1 70.4Z' fill='#1F6FB2'/><path d='M420 64L420 112' stroke='#C0392B' stroke-width='1.6' fill='none'/><path d='M420 112L417.1 105.6L422.9 105.6Z' fill='#C0392B'/><path d='M420 182L420 236' stroke='#C0392B' stroke-width='1.6' fill='none'/><path d='M420 236L417.1 229.6L422.9 229.6Z' fill='#C0392B'/><path d='M360 236L360 182' stroke='#1F6FB2' stroke-width='1.6' fill='none'/><path d='M360 182L362.9 188.4L357.1 188.4Z' fill='#1F6FB2'/><text x='470' y='90' font-size='8.5' text-anchor='end' fill='#636A80'>petite<tspan x='470' dy='9.774999999999999'>circulation</tspan></text><text x='470' y='205' font-size='8.5' text-anchor='end' fill='#636A80'>grande<tspan x='470' dy='9.774999999999999'>circulation</tspan></text><text x='300' y='150' font-size='10.5' text-anchor='start' fill='#142554'></text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Distribution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":3,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Kribi se demande comment le sucre de son jus arrive jusqu'à ses muscles.","tache":"Décris le trajet."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r09",{"duree":20,"titre":"Évaluer la dépense énergétique","accroche":"Combien d'énergie dépense ton corps ?","intro":"La dépense énergétique se mesure par la chaleur produite ou par le dioxygène consommé.","objectifs":["définir la dépense énergétique","utiliser le coefficient thermique de l'O₂","calculer le quotient respiratoire"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> est la quantité d'énergie utilisée par l'organisme par unité de temps. On l'évalue par <strong>calorimétrie directe</strong> (chaleur) ou <strong>indirecte</strong> (dioxygène consommé).</div>"},{"t":"Calcul","verrou":true},{"t":"Quotient respiratoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":9,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un entraîneur de Garoua mesure qu'un athlète consomme 120 L de dioxygène en une heure d'effort.","tache":"Calcule sa dépense énergétique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r47",{"duree":20,"titre":"Dépense énergétique : entraînement","accroche":"Calculer QR et dépense.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Dépense = V(O₂) × 20,1 kJ/L ; QR = V(CO₂)/V(O₂).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":47,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Au club santé d'un lycée de Bafia, on mesure les échanges gazeux d'un élève avant et après une course.","tache":"Comment comparer ses dépenses ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r10",{"duree":20,"titre":"Facteurs de variation de la dépense énergétique et métabolisme basal","accroche":"Effort, froid, croissance.","intro":"La dépense énergétique varie selon l'activité et l'état de l'organisme.","objectifs":["citer les facteurs","interpréter un tableau","adapter la ration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> totale comprend le métabolisme de base et les dépenses liées à l'activité, à la thermorégulation, à la croissance et à la digestion.</div>"},{"t":"Facteurs","verrou":true},{"t":"Définition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":10,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un docker du port de Douala et un employé de bureau mangent la même ration.","tache":"Lequel risque un déficit énergétique ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r48",{"duree":20,"titre":"Facteurs et métabolisme basal : entraînement","accroche":"Lire un tableau de dépenses.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le métabolisme de base est la dépense minimale ; l'activité s'y ajoute.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":48,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un coach de Bafoussam veut adapter la ration d'un footballeur.","tache":"Comment utiliser un tableau de dépenses ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r11",{"duree":20,"titre":"Les apports énergétiques des repas","accroche":"17, 38, 17 : les nombres de l'énergie.","intro":"L'énergie des aliments se calcule à partir de leur composition en nutriments.","objectifs":["connaître les valeurs énergétiques","calculer l'apport d'un repas","comparer apport et dépense"],"parties":[{"t":"Valeurs","html":"<div class='def'><b>Définition</b>La <strong>valeur énergétique</strong> d'un nutriment est l'énergie libérée par 1 g : glucides 17 kJ/g, lipides 38 kJ/g, protides 17 kJ/g.</div>"},{"t":"Calcul","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":11,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Limbé mange au déjeuner 150 g de riz cuit (40 g de glucides), 20 g d'huile et 30 g de poisson (protides).","tache":"Calcule l'énergie apportée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r49",{"duree":20,"titre":"Apports énergétiques : entraînement","accroche":"Le piège du QCM 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Glucides et protides : 17 kJ/g ; lipides : 38 kJ/g.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":49,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une vendeuse de beignets de Mbouda affirme que ses beignets « ne font pas grossir » parce qu'ils contiennent peu de sucre. Un beignet de 80 g contient 40 g de glucides, 15 g de lipides et 5 g de protides. On donne : 17 kJ/g pour les glucides et les protides, 38 kJ/g pour les lipides.","tache":"Calcule l'énergie apportée par un beignet et corrige la vendeuse."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r04",{"duree":20,"titre":"Mécanisme et localisation de la respiration","accroche":"Du cytoplasme à la mitochondrie.","intro":"La respiration se déroule en trois grandes étapes dans deux compartiments de la cellule.","objectifs":["décrire la glycolyse","décrire le cycle de Krebs","localiser la chaîne respiratoire"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La respiration comprend la <strong>glycolyse</strong> (cytoplasme : glucose → 2 pyruvates + 2 ATP), le <strong>cycle de Krebs</strong> (matrice mitochondriale : CO₂ libéré) et la <strong>chaîne respiratoire</strong> (membrane interne : O₂ consommé, ATP produit).</div>"},{"t":"Localisation","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":4,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Au laboratoire, on isole des mitochondries de foie de bœuf et on mesure le dioxygène consommé en 10 minutes : sans substrat, 0 µmol ; avec du glucose, 0 µmol ; avec du pyruvate, 12 µmol. Un élève pense que les mitochondries « brûlent » directement le glucose.","tache":"Analyse ces résultats et réponds à l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r05",{"duree":20,"titre":"Transporteurs et rendement de la respiration","accroche":"Des navettes d'électrons.","intro":"Les transporteurs d'hydrogène relient les étapes de la respiration à la production d'ATP.","objectifs":["nommer les transporteurs","expliquer leur rôle","calculer le rendement"],"parties":[{"t":"Transporteurs","html":"<div class='def'><b>Définition</b>Les <strong>transporteurs</strong> NAD⁺ et FAD captent les électrons et protons libérés lors de l'oxydation du glucose (formant NADH,H⁺ et FADH₂) et les apportent à la chaîne respiratoire.</div>"},{"t":"Production d'ATP","verrou":true,"illus":{"legende":"Respiration et fermentation : localisation et bilan énergétique.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Respiration et fermentation : la glycolyse dans le cytoplasme, puis soit la respiration dans la mitochondrie (cycle de Krebs, chaîne respiratoire, 36 à 38 ATP), soit la fermentation (2 ATP, éthanol ou acide lactique).' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Respiration et fermentation : bilan énergétique</text><rect x='170' y='34' width='140' height='30' rx='6' fill='#FBE7C2' stroke='#9AA5B8' stroke-width='1'/><text x='240' y='52.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>glucose C₆H₁₂O₆</text><path d='M240 64L240 88' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M240 88L237.1 81.6L242.9 81.6Z' fill='#142554'/><text x='250' y='80' font-size='9' font-weight='600' text-anchor='start' fill='#142554'>glycolyse (cytoplasme) : 2 ATP</text><rect x='170' y='90' width='140' height='30' rx='6' fill='#fff' stroke='#9AA5B8' stroke-width='1'/><text x='240' y='108.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>2 pyruvates</text><path d='M200 120L110 160' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M110 160L114.7 154.8L117.0 160.0Z' fill='#142554'/><path d='M280 120L370 160' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M370 160L363.0 160.0L365.3 154.8Z' fill='#142554'/><text x='140' y='140' font-size='9' font-weight='700' text-anchor='end' fill='#C0392B'>sans O₂</text><text x='340' y='140' font-size='9' font-weight='700' text-anchor='start' fill='#1F6FB2'>avec O₂</text><rect x='14' y='162' width='200' height='60' rx='6' fill='#F9DDE3' stroke='#9AA5B8' stroke-width='1'/><text x='114' y='183.6' font-size='9' font-weight='600' text-anchor='middle' fill='#142554'>FERMENTATION (cytoplasme)<tspan x='114' dy='10.35'>éthanol + CO₂ (levure)</tspan><tspan x='114' dy='10.35'>ou acide lactique (muscle)</tspan></text><rect x='266' y='162' width='200' height='60' rx='6' fill='#DCEBF7' stroke='#9AA5B8' stroke-width='1'/><text x='366' y='183.6' font-size='9' font-weight='600' text-anchor='middle' fill='#142554'>RESPIRATION (mitochondrie)<tspan x='366' dy='10.35'>cycle de Krebs (matrice) +</tspan><tspan x='366' dy='10.35'>chaîne respiratoire (crêtes)</tspan></text><text x='114' y='244' font-size='9.5' font-weight='700' text-anchor='middle' fill='#C0392B'>bilan : 2 ATP par glucose<tspan x='114' dy='10.924999999999999'>(oxydation incomplète)</tspan></text><text x='366' y='244' font-size='9.5' font-weight='700' text-anchor='middle' fill='#1F6FB2'>bilan : 36 à 38 ATP par glucose<tspan x='366' dy='10.924999999999999'>(oxydation complète)</tspan></text><text x='240' y='290' font-size='10' font-weight='700' text-anchor='middle' fill='#142554'>C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O + énergie</text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Rendement","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":5,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Kumba se demande pourquoi il a chaud après une course.","tache":"Explique avec le rendement de la respiration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r06",{"duree":20,"titre":"Quelques exemples de fermentation","accroche":"Tout se passe dans le cytoplasme.","intro":"La fermentation commence comme la respiration, par la glycolyse, mais s'arrête dans le cytoplasme.","objectifs":["décrire les étapes","localiser la fermentation","comparer les types de fermentation"],"parties":[{"t":"Mécanisme","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> comprend la glycolyse (glucose → 2 pyruvates + 2 ATP), puis la transformation du pyruvate en éthanol et CO₂ (alcoolique) ou en lactate (lactique), dans le <strong>cytoplasme</strong>.</div>"},{"t":"Rôle de la seconde étape","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":6,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une fabricante de yaourts de Ngaoundéré ensemence le lait avec des bactéries lactiques.","tache":"Explique la transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r07",{"duree":20,"titre":"Comparer respiration et fermentation","accroche":"38 contre 2.","intro":"Respiration et fermentation diffèrent par leurs conditions, leurs produits et leur rendement.","objectifs":["comparer les deux voies","calculer les rendements","expliquer la différence"],"parties":[{"t":"Comparaison","html":"<div class='def'><b>Définition</b>La <strong>respiration</strong> est une oxydation complète en présence d'O₂ (38 ATP, rendement environ 40 %) ; la <strong>fermentation</strong> est une dégradation incomplète sans O₂ (2 ATP, rendement environ 2 %).</div>"},{"t":"Explication","verrou":true,"illus":{"legende":"Respiration et fermentation : localisation et bilan énergétique.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Respiration et fermentation : la glycolyse dans le cytoplasme, puis soit la respiration dans la mitochondrie (cycle de Krebs, chaîne respiratoire, 36 à 38 ATP), soit la fermentation (2 ATP, éthanol ou acide lactique).' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Respiration et fermentation : bilan énergétique</text><rect x='170' y='34' width='140' height='30' rx='6' fill='#FBE7C2' stroke='#9AA5B8' stroke-width='1'/><text x='240' y='52.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>glucose C₆H₁₂O₆</text><path d='M240 64L240 88' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M240 88L237.1 81.6L242.9 81.6Z' fill='#142554'/><text x='250' y='80' font-size='9' font-weight='600' text-anchor='start' fill='#142554'>glycolyse (cytoplasme) : 2 ATP</text><rect x='170' y='90' width='140' height='30' rx='6' fill='#fff' stroke='#9AA5B8' stroke-width='1'/><text x='240' y='108.6' font-size='10' font-weight='600' text-anchor='middle' fill='#142554'>2 pyruvates</text><path d='M200 120L110 160' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M110 160L114.7 154.8L117.0 160.0Z' fill='#142554'/><path d='M280 120L370 160' stroke='#142554' stroke-width='1.6' fill='none'/><path d='M370 160L363.0 160.0L365.3 154.8Z' fill='#142554'/><text x='140' y='140' font-size='9' font-weight='700' text-anchor='end' fill='#C0392B'>sans O₂</text><text x='340' y='140' font-size='9' font-weight='700' text-anchor='start' fill='#1F6FB2'>avec O₂</text><rect x='14' y='162' width='200' height='60' rx='6' fill='#F9DDE3' stroke='#9AA5B8' stroke-width='1'/><text x='114' y='183.6' font-size='9' font-weight='600' text-anchor='middle' fill='#142554'>FERMENTATION (cytoplasme)<tspan x='114' dy='10.35'>éthanol + CO₂ (levure)</tspan><tspan x='114' dy='10.35'>ou acide lactique (muscle)</tspan></text><rect x='266' y='162' width='200' height='60' rx='6' fill='#DCEBF7' stroke='#9AA5B8' stroke-width='1'/><text x='366' y='183.6' font-size='9' font-weight='600' text-anchor='middle' fill='#142554'>RESPIRATION (mitochondrie)<tspan x='366' dy='10.35'>cycle de Krebs (matrice) +</tspan><tspan x='366' dy='10.35'>chaîne respiratoire (crêtes)</tspan></text><text x='114' y='244' font-size='9.5' font-weight='700' text-anchor='middle' fill='#C0392B'>bilan : 2 ATP par glucose<tspan x='114' dy='10.924999999999999'>(oxydation incomplète)</tspan></text><text x='366' y='244' font-size='9.5' font-weight='700' text-anchor='middle' fill='#1F6FB2'>bilan : 36 à 38 ATP par glucose<tspan x='366' dy='10.924999999999999'>(oxydation complète)</tspan></text><text x='240' y='290' font-size='10' font-weight='700' text-anchor='middle' fill='#142554'>C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O + énergie</text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":7,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un boulanger de Yaoundé laisse sa pâte lever dans un récipient fermé.","tache":"Explique pourquoi la pâte gonfle et pourquoi elle ne s'arrête pas aussitôt."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r08",{"duree":20,"titre":"Intégration : de l'énergie pour l'effort","accroche":"Préparer une compétition.","intro":"Un athlète doit gérer sa production d'énergie selon le type d'effort.","objectifs":["mobiliser respiration et fermentation","conseiller un athlète","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un effort prolongé est couvert surtout par la <strong>respiration</strong> ; un effort intense et bref fait aussi appel à la <strong>fermentation lactique</strong>.</div>"},{"t":"Conseils","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":8,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un coureur de la course de l'Espoir au mont Cameroun ressent des crampes dès la première montée.","tache":"Rédige des conseils argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r39",{"duree":20,"titre":"Flux et dissipation de l'énergie dans un écosystème","accroche":"Seuls 10 % passent au niveau suivant.","intro":"L'énergie traverse l'écosystème en sens unique et se dissipe à chaque niveau.","objectifs":["décrire le flux d'énergie","calculer un rendement écologique","construire une pyramide"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>flux d'énergie</strong> part de la lumière captée par les producteurs et passe d'un niveau trophique à l'autre ; à chaque niveau, une grande partie est <strong>dissipée</strong> en chaleur par la respiration.</div>"},{"t":"Rendement","verrou":true,"illus":{"legende":"Chaîne alimentaire et pyramide des énergies.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Chaîne alimentaire et pyramide des énergies : producteurs, consommateurs primaires, secondaires, tertiaires, décomposeurs ; environ 10 % de l&#39;énergie passe d&#39;un niveau au suivant.' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Chaîne alimentaire et flux d&#39;énergie</text><rect x='14' y='40' width='96' height='40' rx='6' fill='#D8EFD9' stroke='#9AA5B8' stroke-width='1'/><text x='62' y='57.6' font-size='9.5' font-weight='600' text-anchor='middle' fill='#142554'>herbe<tspan x='62' dy='10.924999999999999'>(producteur)</tspan></text><path d='M110 60L124 60' stroke='#C77D0A' stroke-width='2' fill='none'/><path d='M124 60L117.6 62.9L117.6 57.1Z' fill='#C77D0A'/><rect x='126' y='40' width='96' height='40' rx='6' fill='#FBE7C2' stroke='#9AA5B8' stroke-width='1'/><text x='174' y='57.6' font-size='9.5' font-weight='600' text-anchor='middle' fill='#142554'>sauterelle<tspan x='174' dy='10.924999999999999'>(C1)</tspan></text><path d='M222 60L236 60' stroke='#C77D0A' stroke-width='2' fill='none'/><path d='M236 60L229.6 62.9L229.6 57.1Z' fill='#C77D0A'/><rect x='238' y='40' width='96' height='40' rx='6' fill='#F9DDE3' stroke='#9AA5B8' stroke-width='1'/><text x='286' y='57.6' font-size='9.5' font-weight='600' text-anchor='middle' fill='#142554'>poulet<tspan x='286' dy='10.924999999999999'>(C2)</tspan></text><path d='M334 60L348 60' stroke='#C77D0A' stroke-width='2' fill='none'/><path d='M348 60L341.6 62.9L341.6 57.1Z' fill='#C77D0A'/><rect x='350' y='40' width='96' height='40' rx='6' fill='#E9DFF5' stroke='#9AA5B8' stroke-width='1'/><text x='398' y='57.6' font-size='9.5' font-weight='600' text-anchor='middle' fill='#142554'>serpent<tspan x='398' dy='10.924999999999999'>(C3)</tspan></text><text x='240' y='98' font-size='8.6' text-anchor='middle' fill='#636A80'>La flèche signifie « est mangé par ». Les décomposeurs (bactéries, champignons) recyclent la matière.</text><rect x='20' y='262' width='300' height='32' fill='#2E8B57' fill-opacity='0.25' stroke='#2E8B57'/><text x='170' y='282' font-size='9.5' font-weight='700' text-anchor='middle' fill='#142554'>producteurs : 10 000 kJ</text><rect x='60' y='224' width='220' height='32' fill='#C77D0A' fill-opacity='0.25' stroke='#C77D0A'/><text x='170' y='244' font-size='9.5' font-weight='700' text-anchor='middle' fill='#142554'>C1 : 1 000 kJ</text><rect x='100' y='186' width='140' height='32' fill='#C0392B' fill-opacity='0.25' stroke='#C0392B'/><text x='170' y='206' font-size='9.5' font-weight='700' text-anchor='middle' fill='#142554'>C2 : 100 kJ</text><rect x='135' y='148' width='70' height='32' fill='#7A4FB3' fill-opacity='0.25' stroke='#7A4FB3'/><text x='170' y='168' font-size='9.5' font-weight='700' text-anchor='middle' fill='#142554'>C3 : 10 kJ</text><text x='330' y='150' font-size='9' text-anchor='start' fill='#142554'>Pyramide des énergies (exemple) :<tspan x='330' dy='10.35'>≈ 90 % de l&#39;énergie est perdue</tspan><tspan x='330' dy='10.35'>à chaque niveau (respiration,</tspan><tspan x='330' dy='10.35'>chaleur, déchets) : le</tspan><tspan x='330' dy='10.35'>rendement est d&#39;environ 10 %.</tspan></text><text x='330' y='236' font-size='9' font-weight='600' text-anchor='start' fill='#142554'>Conséquence : les chaînes<tspan x='330' dy='10.35'>sont courtes (4 à 5 maillons).</tspan></text><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Pyramide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":39,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un éleveur de l'Adamaoua se demande pourquoi produire de la viande demande beaucoup plus de surface que produire des céréales.","tache":"Explique avec le flux d'énergie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r77",{"duree":20,"titre":"Dissipation de l'énergie : entraînement","accroche":"Calculer un rendement écologique.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Rendement = énergie du niveau supérieur / énergie du niveau inférieur × 100.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":77,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un éleveur de poulets de Bafoussam nourrit ses volailles avec des insectes.","tache":"Évalue la perte d'énergie et son intérêt économique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r40",{"duree":20,"titre":"Réservoirs de carbone, cycle du carbone et flux d'énergie","accroche":"Trop de CO₂ dans l'air.","intro":"Les activités humaines libèrent du carbone stocké depuis des millions d'années.","objectifs":["citer les activités en cause","interpréter l'augmentation du CO₂","proposer des solutions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les activités humaines modifient le <strong>cycle du carbone</strong> en transférant le carbone des réservoirs fossiles et forestiers vers l'atmosphère.</div>"},{"t":"Causes","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":40,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans l'Adamaoua, les feux de brousse brûlent chaque année de grandes surfaces.","tache":"Explique leur effet sur le cycle du carbone et propose des mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r78",{"duree":20,"titre":"Cycle du carbone : entraînement","accroche":"Lire une courbe de CO₂.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La teneur en CO₂ de l'air augmente depuis l'ère industrielle.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":78,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un professeur de Garoua présente une courbe de CO₂ à sa classe de 1re C.","tache":"Rédige une interprétation en trois phrases."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r41",{"duree":20,"titre":"Intégration : préserver la fertilité et le carbone","accroche":"Jachère, légumineuses, reboisement.","intro":"Une communauté rurale veut nourrir sa population sans épuiser le sol ni détruire la forêt.","objectifs":["mobiliser les cycles du carbone et de l'azote","proposer des pratiques","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>agriculture durable</strong> maintient la fertilité du sol et le stock de carbone : rotations avec légumineuses, compost, limitation des feux, reboisement.</div>"},{"t":"Arguments","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":41,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans un village de l'Est, les rendements baissent et la forêt recule à cause des feux et de l'agriculture itinérante.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r79",{"duree":20,"titre":"Intégration : un bilan carbone pour le lycée","accroche":"Mesurer pour réduire.","intro":"Un club environnement veut évaluer et réduire les émissions de CO₂ de son établissement.","objectifs":["identifier les sources de CO₂","proposer des réductions","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>bilan carbone</strong> estime les émissions de CO₂ d'une activité : énergie, transport, déchets.</div>"},{"t":"Sources","verrou":true},{"t":"Actions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":79,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le club environnement d'un lycée de Yaoundé veut réduire les émissions de CO₂ de l'établissement.","tache":"Propose un plan d'action en trois points."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r15",{"duree":20,"titre":"Le soi et le non-soi","accroche":"Une carte d'identité moléculaire.","intro":"Chaque individu porte à la surface de ses cellules des molécules qui le caractérisent.","objectifs":["définir le soi","citer les marqueurs du soi","expliquer la compatibilité"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>soi</strong> est l'ensemble des molécules propres à un individu, déterminées par ses gènes, et tolérées par son système immunitaire.</div>"},{"t":"Marqueurs","verrou":true},{"t":"Définition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":15,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"À l'hôpital de district de Mbalmayo, un patient du groupe A a besoin d'une transfusion.","tache":"Quels groupes de donneurs conviennent ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r53",{"duree":20,"titre":"Soi et non-soi : entraînement","accroche":"Interpréter une expérience de greffe.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Une greffe entre individus de CMH différents est rejetée.</div>"},{"t":"Exercice résolu","html":"<p><strong>Document.</strong> Une souris A reçoit une greffe de peau d'une souris A (même lignée) et une greffe d'une souris B (autre lignée). Seule la seconde est rejetée en dix jours.</p><p><strong>Réponse.</strong> La peau de la lignée B porte un CMH différent : elle est reconnue comme non-soi et rejetée.</p>","labo":{"type":"abo"}},{"t":"Le piège à éviter","html":"<div class='attention'><b>Attention</b>Penser que le rejet est dû à la taille du greffon.</div>","retenir":"Penser que le rejet est dû à la taille du greffon."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Un receveur A+ peut recevoir sans risque des hématies :</p><ol type='a'><li>B+ ou AB+, s'il est rhésus positif</li><li>A+, A−, O+ ou O−</li><li>AB+, AB− ou B+</li><li>B−, O+ ou AB−</li></ol><details><summary>Voir la réponse</summary><p><strong>A+, A−, O+ ou O−</strong>. Il tolère A et O, et Rh+ comme Rh−.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Une autogreffe est-elle rejetée ?</p><details><summary>Voir la réponse</summary><p>(Réponse : non, elle appartient au soi.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Lutter contre les problèmes liés à la santé reproductive des jeunes.</p><p><strong>Situation.</strong> On greffe à une souris A de la peau d'une souris B : rejet en 10 jours. Une seconde greffe B sur la même souris est rejetée en 4 jours ; une greffe C, en 10 jours.</p><p><strong>Consigne 1.</strong> Pourquoi la seconde greffe B est-elle rejetée plus vite ?</p><p><strong>Consigne 2.</strong> Que montre le rejet de la greffe C en 10 jours ?</p><details><summary>Voir une réponse attendue</summary><p>La première greffe a créé une mémoire immunitaire spécifique du non-soi B. La réponse est spécifique : face au non-soi C, nouveau, le rejet est aussi lent qu'une première fois.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Une greffe entre individus de CMH différents est rejetée.","Penser que le rejet est dû à la taille du greffon."],"exo":"<p>Une autogreffe est-elle rejetée ? <em>(Réponse : non, elle appartient au soi.)</em></p>","quiz":[{"q":"Un receveur A+ peut recevoir sans risque des hématies :","r":["B+ ou AB+, s'il est rhésus positif","A+, A−, O+ ou O−","AB+, AB− ou B+","B−, O+ ou AB−"],"b":1,"e":"Il tolère A et O, et Rh+ comme Rh−."},{"q":"Un receveur O− peut recevoir des hématies :","r":["O+ et O−","A− et O−","O− seulement","de tous les groupes"],"b":2,"e":"Il possède anti-A et anti-B et ne doit pas recevoir l'antigène D."},{"q":"Un mélange de sang B et de sérum anti-B :","r":["reste homogène","devient bleu","coagule toujours sans lien avec le groupe","s'agglutine"],"b":3,"e":"Les anticorps anti-B se fixent sur les hématies B."},{"q":"Si le sang s'agglutine avec les sérums anti-A et anti-B, le groupe est :","r":["AB","O, car aucun sérum ne réagit seul","A, car le sérum anti-A agglutine","B, car le sérum anti-B agglutine"],"b":0,"e":"Les hématies portent les deux antigènes."},{"q":"Si le sang ne s'agglutine avec aucun sérum, le groupe est :","r":["AB","O","A","B"],"b":1,"e":"Les hématies ne portent ni A ni B."},{"q":"Si le sang s'agglutine avec le seul sérum anti-A, le groupe est :","r":["B","AB","A","O"],"b":2,"e":"Les hématies portent l'antigène A."},{"q":"Une mère Rh− qui porte un enfant Rh+ risque :","r":["aucun problème particulier pour les grossesses suivantes","de changer de groupe sanguin après l'accouchement","de devenir elle-même Rh+ pendant la grossesse suivante, à cause du fœtus","de produire des anticorps anti-D dangereux pour une grossesse suivante"],"b":3,"e":"Une injection d'anti-D après l'accouchement prévient ce risque."},{"q":"Les frères et sœurs ont une probabilité d'être HLA identiques de :","r":["1/4","1/2","1","0"],"b":0,"e":"Chacun hérite d'un des deux haplotypes de chaque parent."},{"q":"Une greffe de peau prise sur soi-même (autogreffe) :","r":["est toujours rejetée","n'est pas rejetée","provoque une allergie","demande des immunosuppresseurs à vie"],"b":1,"e":"Le greffon porte les marqueurs du soi."},{"q":"Le test de groupage se lit :","r":["par l'odeur du mélange entre le sang et le sérum test","par la couleur du sérum test","par la présence ou l'absence d'agglutination","par la température du mélange"],"b":2,"e":"L'agglutination montre la présence de l'antigène."}],"c":"1re C","m":"svt","rang":53,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un chirurgien de Yaoundé prépare une greffe de rein entre deux cousins.","tache":"Pourquoi teste-t-il leur compatibilité ?"},"gratuit":true});
VRT_L("1re-c-svt-r16",{"duree":20,"titre":"Les principales cellules immunitaires","accroche":"Une armée aux rôles variés.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et coopèrent pour défendre l'organisme.","objectifs":["citer les cellules","préciser leur rôle","situer leur origine"],"parties":[{"t":"Les cellules","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> (globules blancs) assurent l'immunité : phagocytes (macrophages, granulocytes), lymphocytes B, lymphocytes T4 et T8.</div>"},{"t":"Rôles","verrou":true},{"t":"Origine","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":16,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un laborantin de Limbé observe un frottis sanguin coloré.","tache":"Comment reconnaître un lymphocyte d'un granulocyte ?"},"verrou":true,"nq":10,"labo":true});
