VRT_L("1re-c-svt-r17",{"duree":20,"titre":"Le VIH : contamination et mode d'action","accroche":"Un virus qui détruit les défenseurs.","intro":"Le VIH infecte les lymphocytes T4 et affaiblit progressivement les défenses.","objectifs":["citer les voies de transmission","décrire le cycle du virus","décrire le dépistage"],"parties":[{"t":"Le virus","html":"<div class='def'><b>Définition</b>Le <strong>VIH</strong> est un rétrovirus : son information génétique est un ARN, copié en ADN par la <strong>transcriptase inverse</strong>. Sa protéine gp120 se fixe sur le récepteur CD4 des LT4.</div>"},{"t":"Transmission","verrou":true,"illus":{"legende":"Le VIH et les étapes de sa multiplication dans un lymphocyte T4.","svg":"<svg viewBox='0 0 480 312' role='img' aria-label='Le VIH : structure du virus et étapes de sa multiplication dans un lymphocyte T4 (fixation, injection, transcription inverse, intégration, synthèse, bourgeonnement).' font-family='Inter,Arial,sans-serif'><rect width='480' height='312' fill='#FBFAF7'/><text x='240' y='17' font-size='12' font-weight='700' text-anchor='middle' fill='#142554'>Le VIH et sa multiplication dans un lymphocyte T4</text><ellipse cx='70' cy='100' rx='34' ry='34' fill='#E9DFF5' stroke='#7A4FB3' stroke-width='2'/><path d='M58 84L82 84L76 116L64 116Z' fill='#fff' stroke='#7A4FB3' stroke-width='1.2' stroke-linejoin='round' stroke-linecap='round'/><path d='M64 92C70 88 72 98 76 94M64 104C70 100 72 110 76 106' fill='none' stroke='#C0392B' stroke-width='1.5' stroke-linejoin='round' stroke-linecap='round'/><circle cx='108.0' cy='100.0' r='3.5' fill='#C77D0A'/><circle cx='96.9' cy='126.9' r='3.5' fill='#C77D0A'/><circle cx='70.0' cy='138.0' r='3.5' fill='#C77D0A'/><circle cx='43.1' cy='126.9' r='3.5' fill='#C77D0A'/><circle cx='32.0' cy='100.0' r='3.5' fill='#C77D0A'/><circle cx='43.1' cy='73.1' r='3.5' fill='#C77D0A'/><circle cx='70.0' cy='62.0' r='3.5' fill='#C77D0A'/><circle cx='96.9' cy='73.1' r='3.5' fill='#C77D0A'/><path d='M105 85L117 40.5' stroke='#636A80' stroke-width='0.8' fill='none'/><circle cx='105' cy='85' r='1.6' fill='#142554'/><text x='120' y='44' font-size='9' text-anchor='start' fill='#142554'>gp120 (se fixe au CD4)</text><path d='M70 88L17 42.5' stroke='#636A80' stroke-width='0.8' fill='none'/><circle cx='70' cy='88' r='1.6' fill='#142554'/><text x='20' y='46' font-size='9' text-anchor='start' fill='#142554'>ARN viral</text><path d='M60 130L17 156.5' stroke='#636A80' stroke-width='0.8' fill='none'/><circle cx='60' cy='130' r='1.6' fill='#142554'/><text x='20' y='160' font-size='9' text-anchor='start' fill='#142554'>enveloppe</text><path d='M80 110L107 166.5' stroke='#636A80' stroke-width='0.8' fill='none'/><circle cx='80' cy='110' r='1.6' fill='#142554'/><text x='110' y='170' font-size='9' text-anchor='start' fill='#142554'>transcriptase<tspan x='110' dy='10.35'>inverse</tspan></text><path d='M180 280C176 200 190 70 300 64C420 58 470 140 462 220C458 260 440 282 420 282Z' fill='#F4FAEC' stroke='#2E8B57' stroke-width='2' stroke-linejoin='round' stroke-linecap='round'/><text x='445' y='274' font-size='11' font-weight='800' text-anchor='end' fill='#2E8B57'>LT4</text><ellipse cx='330' cy='200' rx='48' ry='34' fill='#E9DFF5' stroke='#7A4FB3' stroke-width='1.2' stroke-dasharray='4 3'/><text x='330' y='228' font-size='9' text-anchor='middle' fill='#7A4FB3'>noyau</text><circle cx='205' cy='110' r='8' fill='#C0392B'/><text x='205' y='113.5' font-size='9' font-weight='800' text-anchor='middle' fill='#fff'>1</text><circle cx='250' cy='140' r='8' fill='#C0392B'/><text x='250' y='143.5' font-size='9' font-weight='800' text-anchor='middle' fill='#fff'>2</text><circle cx='300' cy='190' r='8' fill='#C0392B'/><text x='300' y='193.5' font-size='9' font-weight='800' text-anchor='middle' fill='#fff'>3</text><circle cx='380' cy='120' r='8' fill='#C0392B'/><text x='380' y='123.5' font-size='9' font-weight='800' text-anchor='middle' fill='#fff'>4</text><circle cx='440' cy='80' r='8' fill='#C0392B'/><text x='440' y='83.5' font-size='9' font-weight='800' text-anchor='middle' fill='#fff'>5</text><text x='12' y='196' font-size='8.6' font-weight='600' text-anchor='start' fill='#142554'>1 fixation et pénétration<tspan x='12' dy='9.889999999999999'>2 ARN → ADN viral</tspan><tspan x='12' dy='9.889999999999999'>   (transcriptase inverse)</tspan><tspan x='12' dy='9.889999999999999'>3 intégration à l&#39;ADN</tspan><tspan x='12' dy='9.889999999999999'>4 synthèse de virus</tspan><tspan x='12' dy='9.889999999999999'>5 bourgeonnement</tspan></text><circle cx='466' cy='62' r='9' fill='#E9DFF5' stroke='#7A4FB3'/><path d='M450 76L462 66' stroke='#7A4FB3' stroke-width='1.6' fill='none'/><path d='M462 66L458.9 72.3L455.3 67.9Z' fill='#7A4FB3'/><text x='474' y='308' font-size='7' text-anchor='end' fill='#636A80'>Schéma VÉRITAS</text></svg>"}},{"t":"Cycle et dépistage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":17,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un jeune de Kousseri craint d'avoir été contaminé en partageant le repas d'une personne séropositive.","tache":"Rassure-le avec des arguments scientifiques."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r55",{"duree":20,"titre":"VIH : entraînement","accroche":"Ordonner les étapes, comme au Probatoire 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Fixation, fusion, transcription inverse, intégration, traduction, bourgeonnement.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":55,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"À une causerie au lycée de Bafang, un élève demande comment les antirétroviraux agissent. L'infirmière précise qu'un patient sous traitement est passé de 100 000 à moins de 50 copies de virus par mL en six mois.","tache":"Explique simplement l'action des antirétroviraux et interprète la baisse de la charge virale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r18",{"duree":20,"titre":"Les phases de l'infection par le VIH","accroche":"Des années sans symptôme.","intro":"L'infection évolue en plusieurs phases, de la primo-infection au sida.","objectifs":["décrire les phases","interpréter les courbes","expliquer les maladies opportunistes"],"parties":[{"t":"Les phases","html":"<div class='def'><b>Définition</b>L'infection comprend la <strong>primo-infection</strong> (quelques semaines), la <strong>phase asymptomatique</strong> (plusieurs années) et le <strong>sida</strong>, stade de déficit immunitaire grave.</div>"},{"t":"Les courbes","verrou":true},{"t":"Maladies opportunistes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":18,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un jeune de Kumba pense qu'il n'est pas infecté parce qu'il se sent en bonne santé.","tache":"Explique pourquoi seul un test peut répondre."},"verrou":true,"nq":10,"labo":true});
