VRT_L("1re-c-svt-r19",{"duree":20,"titre":"Prévention et traitement du VIH/sida","accroche":"Se protéger, se dépister, se soigner.","intro":"La prévention et les antirétroviraux permettent de freiner l'épidémie.","objectifs":["citer les moyens de prévention","expliquer le traitement","lutter contre la stigmatisation"],"parties":[{"t":"Prévention","html":"<div class='def'><b>Définition</b>La <strong>prévention</strong> du VIH repose sur le préservatif, l'abstinence ou la fidélité, le matériel stérile et la prévention de la transmission de la mère à l'enfant.</div>"},{"t":"Traitement","verrou":true},{"t":"Stigmatisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":19,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Dans un quartier de Douala, une femme enceinte séropositive craint de contaminer son bébé.","tache":"Donne-lui des informations rassurantes."},"verrou":true,"nq":10,"labo":true});
