VRT_L("1re-c-svt-r20",{"duree":20,"titre":"Santé reproductive des jeunes : causes et conséquences","accroche":"IVG, alcool, drogues, mutilations, mariage précoce.","intro":"Certains comportements et pratiques mettent en danger la santé reproductive des jeunes.","objectifs":["identifier les problèmes","en expliquer les causes","en décrire les conséquences"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>santé reproductive</strong> est un état de bien-être physique, mental et social pour tout ce qui concerne l'appareil reproducteur et ses fonctions.</div>"},{"t":"Problèmes et causes","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":20,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un tableau montre qu'en Afrique centrale, les IVG sont passées de 45 à 32 pour 1 000 naissances entre 2015 et 2025.","tache":"Interprète cette évolution pour la santé des jeunes filles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r60",{"duree":20,"titre":"Santé reproductive : entraînement","accroche":"Exploiter un tableau d'indicateurs.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La baisse d'un indicateur de risque traduit des progrès de prévention.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":60,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Dans le département de la Manyu, un rapport de santé indique que, sur 200 femmes interrogées, 30 ont subi une mutilation génitale ; 12 d'entre elles ont eu des complications à l'accouchement. Le club santé prépare une affiche.","tache":"Calcule les pourcentages utiles et cite trois conséquences à faire figurer sur l'affiche."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r21",{"duree":20,"titre":"Santé reproductive : les moyens de lutte","accroche":"Éduquer, protéger, punir.","intro":"La lutte contre les problèmes de santé reproductive associe éducation, services de santé et lois.","objectifs":["citer les moyens de lutte","proposer des actions","concevoir un message"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>lutte</strong> repose sur l'éducation sexuelle, l'accès à la contraception et aux soins, la protection légale des enfants et l'accompagnement des victimes.</div>"},{"t":"Actions","verrou":true},{"t":"Message","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":21,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un chef de village de l'Extrême-Nord veut réduire les mariages précoces dans sa communauté.","tache":"Propose trois actions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r61",{"duree":20,"titre":"Moyens de lutte : entraînement","accroche":"Rédiger un slogan, comme au Probatoire 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Un slogan efficace est court, positif et contient un conseil.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":61,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un club santé de Mokolo veut un slogan pour une marche contre les grossesses précoces.","tache":"Propose un slogan et justifie-le."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r22",{"duree":20,"titre":"Groupes d'aliments, alimentation équilibrée et conséquences d'un déséquilibre","accroche":"Manger de tout, en bonnes proportions.","intro":"Une alimentation équilibrée couvre les besoins en énergie et en nutriments.","objectifs":["définir l'alimentation équilibrée","citer les groupes d'aliments","répartir les apports"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>alimentation équilibrée</strong> apporte, en quantité et en qualité, l'énergie et les nutriments nécessaires : environ 50 à 55 % de glucides, 30 à 35 % de lipides et 12 à 15 % de protides.</div>"},{"t":"Groupes d'aliments","verrou":true},{"t":"Carences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":22,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Une mère de Bafia sert à ses enfants du manioc matin, midi et soir.","tache":"Explique pourquoi ce régime est déséquilibré et propose des compléments."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r58",{"duree":20,"titre":"Alimentation équilibrée : entraînement","accroche":"Analyser un menu.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Glucides 50 à 55 %, lipides 30 à 35 %, protides 12 à 15 % de l'énergie.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":58,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Une vendeuse de repas de Kribi veut proposer un plat plus équilibré.","tache":"Comment vérifier l'équilibre de son plat ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r23",{"duree":20,"titre":"Intégration : une cantine équilibrée","accroche":"Bien nourrir sans trop dépenser.","intro":"Le responsable d'une cantine doit proposer des repas équilibrés avec un budget limité.","objectifs":["mobiliser les règles de l'équilibre","composer des menus locaux","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>repas équilibré</strong> associe féculent, protides, légumes ou fruits, et apporte une énergie adaptée.</div>"},{"t":"Ressources locales","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":23,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"L'intendant d'un internat de Bafang dispose d'un budget limité pour 200 élèves.","tache":"Propose un menu équilibré pour un déjeuner et justifie-le."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r59",{"duree":20,"titre":"Intégration : lutter contre la malnutrition au village","accroche":"Prévenir le kwashiorkor.","intro":"Une communauté rurale voit des enfants souffrir de malnutrition.","objectifs":["identifier la carence","proposer des aliments locaux","rédiger un message"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>malnutrition</strong> résulte d'une alimentation insuffisante ou déséquilibrée ; chez l'enfant, la carence en protides provoque le kwashiorkor.</div>"},{"t":"Solutions locales","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":59,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Dans un village de l'Extrême-Nord, plusieurs enfants présentent des œdèmes et une peau dépigmentée.","tache":"Rédige des conseils pour les mères."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r12",{"duree":20,"titre":"Crise cardiaque et accident vasculaire cérébral","accroche":"Quand le sang ne passe plus.","intro":"Les accidents cardiovasculaires sont dus à l'interruption de la circulation dans le cœur ou le cerveau.","objectifs":["distinguer infarctus et AVC","expliquer les causes","reconnaître les signes d'alerte"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>crise cardiaque</strong> (infarctus du myocarde) est la mort d'une partie du muscle cardiaque privée de sang par l'obstruction d'une artère coronaire. L'<strong>AVC</strong> est l'interruption de la circulation dans une partie du cerveau, par un caillot ou une hémorragie.</div>"},{"t":"Causes et facteurs de risque","verrou":true},{"t":"Signes d'alerte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":12,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un commerçant de Douala, fumeur et hypertendu, ressent une douleur serrée dans la poitrine.","tache":"Que faut-il suspecter et faire ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r50",{"duree":20,"titre":"Accidents cardiovasculaires : entraînement","accroche":"Lire un tableau de facteurs de risque.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Les facteurs de risque se cumulent.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":50,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un médecin de Garoua classe ses patients selon leurs facteurs de risque.","tache":"Comment conseiller le patient le plus exposé ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r13",{"duree":20,"titre":"Lutter contre l'AVC et la crise cardiaque","accroche":"Prévenir vaut mieux que guérir.","intro":"La plupart des facteurs de risque cardiovasculaires peuvent être réduits.","objectifs":["citer les moyens de prévention","expliquer leur intérêt","réagir en urgence"],"parties":[{"t":"Prévention","html":"<div class='def'><b>Définition</b>La <strong>prévention cardiovasculaire</strong> consiste à réduire les facteurs de risque : arrêt du tabac, alimentation peu salée et peu grasse, activité physique, contrôle de la tension et de la glycémie.</div>"},{"t":"Dépistage","verrou":true},{"t":"Urgence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":13,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une association de quartier à Bafoussam veut réduire les AVC chez les adultes.","tache":"Propose trois actions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r51",{"duree":20,"titre":"Lutte contre les accidents cardiovasculaires : entraînement","accroche":"Comparer deux modes de vie.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Une hygiène de vie saine réduit fortement le risque cardiovasculaire.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":51,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un enseignant de Kumba prépare un débat sur le mode de vie et le cœur.","tache":"Rédige un argument scientifique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r14",{"duree":20,"titre":"Intégration : prévenir les AVC dans la famille","accroche":"Agir avant l'accident.","intro":"Une famille dont plusieurs membres sont hypertendus veut prévenir les AVC.","objectifs":["mobiliser causes et prévention","proposer un plan","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>L'<strong>hypertension</strong> est le principal facteur de risque d'AVC ; elle est souvent silencieuse.</div>"},{"t":"Plan","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":14,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Dans une famille de Dschang, le grand-père a fait un AVC et deux enfants sont hypertendus.","tache":"Propose un plan de prévention et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r52",{"duree":20,"titre":"Intégration : une journée cœur au lycée","accroche":"Mesurer, informer, bouger.","intro":"Le club santé organise une journée de prévention cardiovasculaire.","objectifs":["organiser une action de prévention","informer le public","évaluer l'action"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>action de prévention</strong> combine dépistage, information et pratique d'activités saines.</div>"},{"t":"Programme","verrou":true},{"t":"Évaluation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":52,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Le club santé d'un lycée de Bamenda organise une journée « Cœur en forme ».","tache":"Propose le programme de la journée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r42",{"duree":20,"titre":"L'effet de serre","accroche":"Sans lui, il ferait −18 °C.","intro":"Certains gaz de l'atmosphère retiennent une partie de l'infrarouge émis par la Terre.","objectifs":["définir l'effet de serre","citer les gaz à effet de serre","distinguer effet naturel et renforcé"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet de serre</strong> est le réchauffement de la surface dû à des gaz atmosphériques (vapeur d'eau, CO₂, méthane) qui absorbent l'infrarouge émis par la Terre et en renvoient une partie vers le sol.</div>"},{"t":"Importance","verrou":true},{"t":"Effet renforcé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":42,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Les pêcheurs de Kribi observent que la mer gagne sur la plage d'année en année.","tache":"Relie cette observation à l'effet de serre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r80",{"duree":20,"titre":"Effet de serre : entraînement","accroche":"Interpréter un bilan.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Plus il y a de gaz à effet de serre, plus la surface reçoit d'infrarouge renvoyé.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":80,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans un exposé à Bertoua, un élève affirme que l'effet de serre est toujours nuisible.","tache":"Nuance son affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r24",{"duree":20,"titre":"Les mouvements atmosphériques","accroche":"Harmattan et mousson.","intro":"Les différences de température créent des différences de pression qui mettent l'air en mouvement.","objectifs":["expliquer la naissance des vents","décrire la circulation générale","relier aux saisons du Cameroun"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>L'air chauffé s'élève et crée une zone de <strong>basse pression</strong> ; l'air froid descend et crée une <strong>haute pression</strong>. Le <strong>vent</strong> souffle des hautes vers les basses pressions.</div>"},{"t":"Circulation générale","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":24,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le long de la côte de Limbé, les pirogues rentrent facilement à la plage en fin de journée.","tache":"Explique ce phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r62",{"duree":20,"titre":"Mouvements atmosphériques : entraînement","accroche":"L'exploitation de document du Probatoire 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La terre se réchauffe plus vite que l'océan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":62,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Les pêcheurs de Tiko partent tôt le matin et rentrent l'après-midi.","tache":"Explique ce choix grâce aux brises."},"verrou":true,"nq":10,"labo":true});
