VRT_L("1re-c-svt-r45",{"duree":20,"titre":"Définition et applications de la biotechnologie","accroche":"Le vivant au service de l'Homme.","intro":"La biotechnologie utilise des êtres vivants ou leurs molécules pour produire des biens et des services.","objectifs":["définir la biotechnologie","citer des applications","discuter de leurs limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>biotechnologie</strong> est l'utilisation d'êtres vivants (micro-organismes, cellules, enzymes) pour fabriquer des produits ou rendre des services.</div>"},{"t":"Applications","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":45,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une coopérative de femmes de Bafia veut se lancer dans la production de yaourts.","tache":"Explique le principe et une condition de réussite."},"verrou":true,"nq":10,"labo":true});
