VRT_L("1re-c-svt-r46",{"duree":20,"titre":"Intégration : une petite unité de biotechnologie","accroche":"Transformer le manioc et les déchets.","intro":"Une coopérative veut transformer le manioc et valoriser ses déchets grâce aux micro-organismes.","objectifs":["mobiliser fermentation et biotechnologie","concevoir un protocole","rédiger une affiche"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>unité de biotechnologie</strong> utilise des micro-organismes dans des conditions contrôlées pour produire des aliments ou de l'énergie.</div>"},{"t":"Protocole du bâton de manioc","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":46,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une coopérative de femmes de l'Est produit du bâton de manioc et jette ses épluchures.","tache":"Conçois une affiche présentant le protocole de production et la valorisation des déchets."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r84",{"duree":20,"titre":"Intégration : une petite unité de biotechnologie","accroche":"Transformer le manioc et les déchets.","intro":"Une coopérative veut transformer le manioc et valoriser ses déchets grâce aux micro-organismes.","objectifs":["mobiliser fermentation et biotechnologie","concevoir un protocole","rédiger une affiche"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>unité de biotechnologie</strong> utilise des micro-organismes dans des conditions contrôlées pour produire des aliments ou de l'énergie.</div>"},{"t":"Protocole du bâton de manioc","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":84,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une coopérative de femmes de l'Est produit du bâton de manioc et jette ses épluchures.","tache":"Conçois une affiche présentant le protocole de production et la valorisation des déchets."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-definitions",{"c":"1re C","m":"philo","rang":1,"titre":"Définir la philosophie","duree":25,"accroche":"Une seule discipline commence par se demander ce qu'elle est : la philosophie.","intro":"En série scientifique, tu découvres la philosophie cette année. Elle ne donne pas de formules, mais elle apprend à interroger les formules elles-mêmes : qu'est-ce que savoir ? Qu'est-ce qui est juste ? Pour commencer, il faut savoir ce que les philosophes entendent par « philosophie ».","objectifs":["donner l'étymologie et plusieurs définitions de la philosophie","distinguer la conception spontanée et la conception savante","reconnaître les grandes questions de la philosophie"],"parties":[{"t":"La conception spontanée et l'étymologie","html":"<p>Dans le langage courant, « avoir une philosophie », c'est avoir une <strong>manière de vivre</strong> (« ma philosophie : ne jamais abandonner ») ou rester calme dans l'épreuve (« prendre les choses avec philosophie »). C'est la <strong>conception spontanée</strong>.</p><div class='def'><b>Étymologie</b>Du grec <strong>philein</strong> (aimer) et <strong>sophia</strong> (sagesse, savoir) : <strong>amour de la sagesse</strong>. Pythagore aurait refusé le titre de « sage » (sophos) pour se dire « ami de la sagesse » (philosophos) : le philosophe <strong>cherche</strong> le savoir, il ne le possède pas.</div>","retenir":"Conception spontanée : une manière de vivre. Étymologie : amour, recherche de la sagesse."},{"t":"Quelques définitions savantes","html":"<ul><li><strong>Platon</strong> : l'étonnement est le commencement de la philosophie ; elle conduit des apparences à la vérité (allégorie de la caverne).</li><li><strong>Aristote</strong> : la philosophie est la <strong>science des premiers principes et des premières causes</strong>.</li><li><strong>Descartes</strong> : elle est comme un <strong>arbre</strong> dont les racines sont la métaphysique, le tronc la physique et les branches la médecine, la mécanique et la morale.</li><li><strong>Kant</strong> la ramène à quatre questions : <strong>Que puis-je savoir ? Que dois-je faire ? Que m'est-il permis d'espérer ? Qu'est-ce que l'homme ?</strong></li><li><strong>Marcien Towa</strong> : philosopher, c'est examiner de façon critique, y compris ses propres traditions, pour se libérer.</li></ul><div class='astuce'><b>Astuce</b>Retiens les quatre questions de Kant : elles reviennent sans cesse dans les sujets (connaissance, morale, religion, homme).</div>","retenir":"Platon : l'étonnement ; Aristote : premières causes ; Descartes : l'arbre ; Kant : quatre questions ; Towa : la critique libératrice.","labo":{"type":"trier","invite":"Choisis une notion de la leçon.","items":[["Conception spontanée","Conception spontanée : manière de vivre ; savante : réflexion rigoureuse."],["Philein","Philein + sophia : amour de la sagesse (Pythagore)."],["Aristote","Aristote : premiers principes ; Descartes : l'arbre ; Kant : quatre questions."],["rationnelle","Réflexion rationnelle, critique, totalisante."],["La science mesure","La science mesure ; la philosophie interroge le sens et la valeur."]]}},{"t":"Ce qui définit l'attitude philosophique","html":"<div class='def'><b>Trois caractères</b>La philosophie est une réflexion <strong>rationnelle</strong> (elle argumente), <strong>critique</strong> (elle ne reçoit aucune idée sans examen) et <strong>totalisante</strong> (elle cherche le sens d'ensemble : l'homme, le monde, la valeur des choses).</div><div class='ex'><b>Philosophie et sciences</b>Le physicien mesure la chute d'un corps ; le philosophe demande ce que vaut une loi scientifique, si la science peut tout expliquer, si tout ce qui est techniquement possible est moralement permis (clonage, armes, intelligence artificielle).</div><div class='savais'><b>Le savais-tu ?</b>Jusqu'au XVIIIᵉ siècle, la physique s'appelait « philosophie naturelle » : le grand livre de Newton (1687) s'intitule <em>Principes mathématiques de la philosophie naturelle</em>.</div>","retenir":"Rationnelle, critique, totalisante : la philosophie interroge le sens et la valeur, là où la science mesure."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans le langage courant, « prendre les choses avec philosophie » signifie :</p><ol type='a'><li>rester calme et serein</li><li>étudier Platon</li><li>refuser de penser</li><li>faire de la science</li></ol><details><summary>Voir la réponse</summary><p><strong>rester calme et serein</strong>. C'est la conception spontanée.</p></details><p><strong>Exercice.</strong></p><p>Définis les concepts « philosophie » et « opinion » et donne pour chacun une citation avec son auteur.</p><details><summary>Voir la réponse</summary><p>(Réponse : Philosophie : réflexion rationnelle, critique et totalisante sur les questions fondamentales ; « On n'apprend pas la philosophie, on apprend à philosopher » (Kant). Opinion (doxa) : avis reçu sans examen ; « Ce que je sais, c'est que je ne sais rien » (Socrate), qui oppose la conscience de son ignorance aux fausses certitudes.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Sujet.</strong> En 1re C à Bertoua, un camarade déclare : « Nous sommes des scientifiques : la philosophie, c'est du bavardage. La science répond à tout. »</p><p><strong>Consigne.</strong> Rédige une réponse argumentée (12 à 15 lignes) qui montre ce que la philosophie apporte à un futur scientifique, avec au moins une définition étudiée et un exemple actuel.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>La science explique comment les phénomènes se produisent, mais elle ne dit pas ce qu'il faut faire de ses découvertes. Kant rappelle que la question « Que dois-je faire ? » est distincte de « Que puis-je savoir ? ». Exemple : l'intelligence artificielle permet de produire de fausses vidéos très réalistes ; la technique le permet, mais est-ce juste de les diffuser ? De plus, Descartes faisait de la physique une branche de la philosophie : les grands savants (Newton, Einstein) ont réfléchi aux fondements de leur science. La philosophie n'est donc pas un bavardage : elle apprend à examiner les principes et les usages du savoir.</p></details></div>","retenir":"Savoir-être mobilisé : ouverture d'esprit et sens de la responsabilité."}],"revision":["Conception spontanée : manière de vivre ; savante : réflexion rigoureuse.","<strong>Philein</strong> + <strong>sophia</strong> : amour de la sagesse (Pythagore).","Aristote : premiers principes ; Descartes : l'arbre ; Kant : quatre questions.","Réflexion <strong>rationnelle</strong>, <strong>critique</strong>, <strong>totalisante</strong>.","La science mesure ; la philosophie interroge le sens et la valeur."],"exo":"<p>Définis les concepts « philosophie » et « opinion » et donne pour chacun une citation avec son auteur. <em>(Réponse : Philosophie : réflexion rationnelle, critique et totalisante sur les questions fondamentales ; « On n'apprend pas la philosophie, on apprend à philosopher » (Kant). Opinion (doxa) : avis reçu sans examen ; « Ce que je sais, c'est que je ne sais rien » (Socrate), qui oppose la conscience de son ignorance aux fausses certitudes.)</em></p>","quiz":[{"q":"Dans le langage courant, « prendre les choses avec philosophie » signifie :","r":["rester calme et serein","étudier Platon","refuser de penser","faire de la science"],"b":0,"e":"C'est la conception spontanée."},{"q":"Le philosophe, selon Pythagore, est celui qui :","r":["possède la sagesse","aime et cherche la sagesse","enseigne la géométrie","dirige la cité"],"b":1,"e":"Philosophos : ami de la sagesse."},{"q":"Pour Platon, la philosophie commence par :","r":["la peur","la richesse","l'étonnement","la guerre"],"b":2,"e":"S'étonner, c'est voir que l'évidence pose question."},{"q":"L'image de l'arbre est de :","r":["Kant","Aristote","Towa","Descartes"],"b":3,"e":"Racines : métaphysique ; tronc : physique ; branches : médecine, mécanique, morale."},{"q":"« Que dois-je faire ? » relève de :","r":["la morale","la physique","la religion","la logique"],"b":0,"e":"C'est la deuxième question de Kant."},{"q":"Une réflexion critique :","r":["accepte toutes les opinions","examine les idées avant de les admettre","refuse la raison","récite les traditions"],"b":1,"e":"Aucune idée n'est reçue sans examen."},{"q":"Le caractère « totalisant » de la philosophie signifie qu'elle :","r":["étudie un seul objet","fait des calculs","cherche un sens d'ensemble","dure longtemps"],"b":2,"e":"Elle interroge l'homme, le monde et les valeurs."},{"q":"Newton parlait de « philosophie naturelle » pour désigner :","r":["la morale","la religion","la poésie","la physique"],"b":3,"e":"Ses Principia de 1687."},{"q":"Marcien Towa voit dans la philosophie :","r":["une critique libératrice","une récitation des ancêtres","une science exacte","un loisir"],"b":0,"e":"Examiner même ses propres traditions pour se libérer."},{"q":"Aristote définit la philosophie comme :","r":["l'art de bien parler","la science des premiers principes et des premières causes","l'amour des richesses","l'étude des étoiles"],"b":1,"e":"Définition de la Métaphysique."}],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Montrer l'utilité de la réflexion philosophique pour un futur scientifique","situation":"En 1re C à Bertoua, un camarade déclare : « Nous sommes des scientifiques : la philosophie, c'est du bavardage. La science répond à tout. »","tache":"Lui répondre de manière argumentée avec des définitions et un exemple actuel."},"gratuit":true});
VRT_L("1re-c-francais-communication",{"c":"1re C","m":"francais","rang":2,"titre":"Communication : les conditions de la communication","duree":55,"accroche":"« Allô ? Tu m'entends ? » : même une conversation banale obéit à des règles.","intro":"Leçon de langue (rubrique Communication). On observe un échange réel de la vie scolaire, on y identifie les facteurs de la communication et ce qui la fait réussir ou échouer, puis on formule la règle et on s'entraîne au format de l'épreuve de langue : repérage, analyse, interprétation.","objectifs":["identifier les six facteurs de la communication","associer à chaque facteur sa fonction du langage","expliquer les causes d'échec d'une communication"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (échange composé pour la leçon) :</p><blockquote>Message du délégué, envoyé à 23 h dans le groupe WhatsApp de la 1re C : « Dvr de maths reporté à jeudi, svp passez l'info. »<br>Réponse d'un élève venu de Bamenda : « Sorry, what is Dvr? »<br>Réponse d'une élève, le lendemain à 7 h : « Je n'avais plus de forfait hier… Quel devoir ? »<br>Le délégué, en classe : « Écoutez tous : le devoir de mathématiques est reporté à jeudi, à 10 heures. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui parle (émetteur) ? À qui (récepteur) ? Pour dire quoi (message) ? De quoi parle-t-on (référent) ?</li><li>Par quels moyens le message passe-t-il (canal) ? Dans quelle langue et sous quelle forme (code) ?</li><li>Pourquoi l'élève de Bamenda ne comprend-il pas ? Pourquoi l'élève du matin n'a-t-elle rien reçu ?</li><li>Compare le premier et le dernier message : qu'a changé le délégué ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Émetteur : le délégué ; récepteurs : les élèves de la classe ; message : le report du devoir ; référent : le devoir de mathématiques. 2. Canal : messagerie écrite puis voix en classe ; code : français abrégé (« Dvr », « svp »), puis français courant. 3. L'élève anglophone ne partage pas le <strong>code</strong> (abréviation, langue) ; l'autre n'a pas eu accès au <strong>canal</strong> (plus de forfait) : ce sont des <strong>bruits</strong>. 4. Il a changé de canal (oral, en présence de tous) et de code (mots entiers, précisions), et ajouté l'heure : la communication réussit.</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>communication</strong> est la transmission d'un <strong>message</strong> d'un <strong>émetteur</strong> à un <strong>récepteur</strong>, à propos d'un <strong>référent</strong>, par un <strong>canal</strong>, au moyen d'un <strong>code</strong> commun. Elle échoue quand un de ces facteurs fait défaut : on parle de <strong>bruit</strong>.</div>","retenir":"Six facteurs : émetteur, récepteur, message, référent, canal, code ; le bruit fait échouer la communication."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Analyser une situation de communication pour transmettre un message compris de tous","situation":"Le délégué de ta classe à Garoua envoie dans le groupe WhatsApp : « Dvr de maths reporté à jeudi, svp passez l'info ». Plusieurs élèves anglophones et un nouvel élève venu de Maroua n'ont rien compris ; d'autres n'avaient plus de connexion.","tache":"Analyser les facteurs et les causes de l'échec, puis réécrire le message."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-renaissance",{"c":"1re C","m":"histoire","rang":1,"titre":"L'Europe de la Renaissance (XVᵉ-XVIᵉ siècles)","duree":25,"accroche":"Une imprimerie, des caravelles et une nouvelle idée de l'homme : l'Europe change de visage.","intro":"Entre le milieu du XVᵉ et la fin du XVIᵉ siècle, l'Europe connaît un renouveau des arts, des sciences et des idées, et part à la découverte du monde. C'est aussi le moment où des navigateurs portugais atteignent les côtes du Cameroun, auquel ils donnent son nom.","objectifs":["définir la Renaissance et l'humanisme","présenter les transformations artistiques, scientifiques et religieuses","expliquer les grandes découvertes et leurs conséquences pour l'Afrique"],"parties":[{"t":"La Renaissance et l'humanisme","html":"<div class='def'><b>Définitions</b>La <strong>Renaissance</strong> est le renouveau culturel européen des XVᵉ et XVIᵉ siècles, né en <strong>Italie</strong> (Florence, Rome, Venise), qui s'inspire de l'Antiquité grecque et romaine. L'<strong>humanisme</strong> est le mouvement intellectuel qui place l'<strong>homme</strong>, sa dignité et sa raison au centre de la réflexion.</div><ul><li><strong>L'imprimerie</strong> : Gutenberg met au point les caractères mobiles à Mayence (Bible vers 1455) ; les livres se diffusent rapidement.</li><li><strong>Les humanistes</strong> : Érasme (<em>Éloge de la folie</em>, 1511), Thomas More (<em>Utopie</em>, 1516), Rabelais, Montaigne.</li><li><strong>Les mécènes</strong> : les Médicis à Florence, les papes à Rome financent artistes et savants.</li></ul>","retenir":"Renaissance : renouveau inspiré de l'Antiquité, né en Italie ; humanisme : l'homme au centre ; diffusion par l'imprimerie."},{"t":"Arts, sciences et religion","html":"<ul><li><strong>Arts</strong> : perspective, étude du corps humain. Léonard de Vinci (<em>La Joconde</em>), Michel-Ange (plafond de la chapelle Sixtine), Raphaël.</li><li><strong>Sciences</strong> : <strong>Copernic</strong> (1543) affirme que la Terre tourne autour du Soleil (héliocentrisme) ; Vésale décrit l'anatomie humaine.</li><li><strong>Religion</strong> : en <strong>1517</strong>, <strong>Martin Luther</strong> critique la vente des indulgences : c'est la <strong>Réforme protestante</strong> ; Calvin la prolonge. L'Église catholique répond par la <strong>Contre-Réforme</strong> (concile de Trente, 1545-1563).</li></ul><div class='attention'><b>Attention</b>La Renaissance n'est pas une rupture totale avec le Moyen Âge, et elle reste réservée à une élite urbaine et instruite.</div>","retenir":"Vinci, Michel-Ange ; Copernic (1543) ; Luther (1517) : Réforme et Contre-Réforme.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["Renaissance","Renaissance (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité."],["Humanisme","Humanisme : l'homme au centre ; imprimerie de Gutenberg (vers 1455)."],["Copernic","Vinci, Michel-Ange ; Copernic 1543 ; Luther 1517."],["1492","Découvertes : 1488 Dias, 1492 Colomb, 1498 Vasco de Gama."],["Rio dos Camarões","Vers 1472 : Fernando Póo, Rio dos Camarões."]]}},{"t":"Les grandes découvertes et l'Afrique","html":"<ul><li>Causes : recherche de l'or et des épices, contournement de l'Empire ottoman (prise de Constantinople en <strong>1453</strong>), progrès techniques (caravelle, boussole, astrolabe).</li><li>Étapes : Bartolomeu Dias passe le cap de Bonne-Espérance (1488) ; <strong>Christophe Colomb</strong> atteint l'Amérique (1492) ; Vasco de Gama arrive en Inde (1498) ; Magellan et Elcano font le tour du monde (1519-1522).</li></ul><div class='ex'><b>Le Cameroun</b>Vers <strong>1472</strong>, le Portugais <strong>Fernando Póo</strong> entre dans l'estuaire du Wouri ; les marins, frappés par l'abondance des crevettes, le nomment <strong>Rio dos Camarões</strong>, la « rivière des crevettes » : c'est l'origine du nom <strong>Cameroun</strong>.</div><div class='attention'><b>Conséquences</b>Premiers contacts commerciaux avec l'Afrique, puis développement de la <strong>traite atlantique</strong> pour fournir des esclaves aux plantations d'Amérique ; destruction des sociétés amérindiennes.</div>","retenir":"1453, 1488, 1492, 1498 ; vers 1472, Rio dos Camarões ; le revers des découvertes : traite et conquêtes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux facteurs qui expliquent la Renaissance en Europe aux XVe et XVIe siècles. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« La Renaissance commence en Allemagne au XVe siècle. Gutenberg y invente la boussole vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Galilée publie un ouvrage qui place la Terre au centre de l'univers. Les princes deviennent mécènes des artistes. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : aux XVe-XVIe siècles, l'Europe connaît un renouveau des arts, des lettres et des sciences appelé Renaissance. Éléments : l'invention de l'imprimerie par Gutenberg vers 1450, qui diffuse rapidement les livres et les idées ; la redécouverte des auteurs grecs et latins par les humanistes, favorisée par l'arrivée de savants byzantins en Italie après 1453 ; on peut aussi citer le mécénat des princes et des riches marchands. Explications : ces facteurs permettent la circulation du savoir et financent les artistes. Bilan : la Renaissance naît de la conjonction d'innovations techniques, intellectuelles et économiques.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) en Allemagne → en Italie ; 2) la boussole → l'imprimerie à caractères mobiles ; 3) Galilée → Copernic ; 4) la Terre au centre → le Soleil au centre (héliocentrisme). Texte corrigé : « La Renaissance commence en Italie au XVe siècle. Gutenberg invente l'imprimerie à caractères mobiles vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Copernic publie un ouvrage qui place le Soleil au centre de l'univers. Les princes deviennent mécènes des artistes. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Promotion de la culture et de l'esprit critique</strong></p><p><strong>Document 1 : Un idéal humaniste</strong></p><blockquote>« Science sans conscience n'est que ruine de l'âme. »</blockquote><p><em>Source : François Rabelais, <i>Pantagruel</i>, 1532, chapitre VIII (lettre de Gargantua à son fils).</em></p><p><strong>Document 2 : Quelques repères de la Renaissance</strong></p><table><tr><th>Date</th><th>Événement</th></tr><tr><td>vers 1450</td><td>Imprimerie à caractères mobiles de Gutenberg (Mayence)</td></tr><tr><td>1492</td><td>Christophe Colomb atteint l'Amérique</td></tr><tr><td>1503-1506</td><td>Léonard de Vinci peint <i>La Joconde</i></td></tr><tr><td>1543</td><td>Copernic publie sa théorie héliocentrique</td></tr></table><p><em>Source : Réalisation VÉRITAS, d'après le programme d'histoire de Première.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique le sens de la phrase de Rabelais et montre qu'elle résume l'idéal humaniste. (3 pts)</li><li>Montre, à partir du document 2 et de tes connaissances, que la Renaissance est un renouveau à la fois artistique, scientifique et géographique. (3 pts)</li><li>Propose deux actions pour que les jeunes Camerounais développent aujourd'hui leur esprit critique face aux informations qu'ils reçoivent. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : pour Rabelais, le savoir doit s'accompagner de morale et de jugement ; l'humanisme place l'homme au centre, valorise l'éducation complète, le retour aux textes anciens et l'esprit critique. Tâche 2 : renouveau artistique (Léonard de Vinci), scientifique (Copernic, héliocentrisme), technique (imprimerie) et géographique (voyage de Colomb, 1492). Tâche 3 : créer des clubs de lecture et de débat dans les établissements ; apprendre à vérifier les sources des informations reçues sur les réseaux sociaux.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : esprit critique et devoir de mémoire."}],"revision":["<strong>Renaissance</strong> (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité.","<strong>Humanisme</strong> : l'homme au centre ; imprimerie de Gutenberg (vers 1455).","Vinci, Michel-Ange ; <strong>Copernic</strong> 1543 ; <strong>Luther</strong> 1517.","Découvertes : 1488 Dias, <strong>1492</strong> Colomb, 1498 Vasco de Gama.","Vers 1472 : Fernando Póo, <strong>Rio dos Camarões</strong>."],"exo":"<p>Associe chaque date à son événement : 1455, 1492, 1517, 1543. <em>(Réponse : 1455 : Bible de Gutenberg ; 1492 : Colomb en Amérique ; 1517 : thèses de Luther ; 1543 : Copernic, héliocentrisme.)</em></p>","quiz":[{"q":"La Renaissance est née en :","r":["Italie","Angleterre","Espagne","Allemagne"],"b":0,"e":"Florence, Rome et Venise en sont les grands foyers."},{"q":"L'imprimerie à caractères mobiles est mise au point par :","r":["Copernic","Gutenberg","Érasme","Luther"],"b":1,"e":"À Mayence, Bible vers 1455."},{"q":"<em>Éloge de la folie</em> est d'un humaniste :","r":["Rabelais","Montaigne","Érasme","Thomas More"],"b":2,"e":"Érasme, 1511."},{"q":"Copernic affirme que :","r":["la Terre est plate","le Soleil tourne autour de la Terre","la Lune est une planète","la Terre tourne autour du Soleil"],"b":3,"e":"L'héliocentrisme, 1543."},{"q":"La Réforme protestante commence en :","r":["1517","1492","1453","1545"],"b":0,"e":"Martin Luther et les 95 thèses."},{"q":"Christophe Colomb atteint l'Amérique en :","r":["1488","1492","1498","1522"],"b":1,"e":"Au service des rois d'Espagne."},{"q":"Le nom « Cameroun » vient de :","r":["un roi douala","un fleuve du Nord","Rio dos Camarões, la rivière des crevettes","un mot allemand"],"b":2,"e":"Nom donné par les Portugais à l'estuaire du Wouri."},{"q":"La prise de Constantinople par les Ottomans date de :","r":["1517","1492","1498","1453"],"b":3,"e":"Elle pousse les Européens à chercher d'autres routes vers l'Asie."},{"q":"Une conséquence dramatique des grandes découvertes pour l'Afrique est :","r":["la traite atlantique","l'imprimerie","l'humanisme","la Contre-Réforme"],"b":0,"e":"Déportation de millions d'Africains vers l'Amérique."},{"q":"La caravelle, la boussole et l'astrolabe sont :","r":["des œuvres d'art","des progrès techniques de navigation","des livres humanistes","des religions"],"b":1,"e":"Ils rendent possibles les voyages au long cours."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les transformations de l'Europe et leurs effets sur l'Afrique","situation":"Un guide du musée maritime de Douala prépare une visite pour des collégiens. Il veut leur expliquer d'où vient le nom « Cameroun » et pourquoi l'arrivée des Portugais au XVᵉ siècle a eu des effets à la fois positifs et dramatiques.","tache":"Rédiger un texte qui explique le nom et les deux faces des contacts avec les Portugais."},"gratuit":true});
VRT_L("1re-c-philo-origine-objet",{"c":"1re C","m":"philo","rang":2,"titre":"Origine et objet de la philosophie","duree":25,"accroche":"La philosophie est-elle née en Grèce, ou y a-t-elle seulement pris son nom ?","intro":"On enseigne souvent que la philosophie est née en Grèce au VIᵉ siècle avant notre ère, comme par « miracle ». Des historiens africains ont contesté ce récit en rappelant la dette des Grecs envers l'Égypte. Après l'origine, il faut aussi se demander de quoi s'occupe la philosophie.","objectifs":["expliquer les conditions de naissance de la philosophie en Grèce","présenter la thèse du « miracle grec » et sa critique","définir l'objet de la philosophie"],"parties":[{"t":"La naissance de la philosophie en Grèce","html":"<p>Au VIᵉ siècle av. J.-C., en Ionie (côte de l'actuelle Turquie), à <strong>Milet</strong>, des penseurs cherchent à expliquer la nature par des causes naturelles et non par les dieux : on passe du <strong>mythos</strong> (récit mythique) au <strong>logos</strong> (discours rationnel).</p><ul><li><strong>Thalès</strong> : le principe (arkhè) de toutes choses est l'eau.</li><li><strong>Anaximène</strong> : l'air ; <strong>Héraclite</strong> : le feu et le changement perpétuel ; <strong>Pythagore</strong> : le nombre.</li></ul><div class='def'><b>Les conditions</b>La <strong>cité</strong> (polis) où l'on débat sur l'agora ; l'<strong>écriture alphabétique</strong> ; le <strong>loisir</strong> (scholè) des citoyens ; le commerce et les voyages, qui mettent en contact avec d'autres savoirs.</div>","retenir":"Milet, VIᵉ s. av. J.-C. : du mythos au logos ; Thalès, l'eau principe de toute chose."},{"t":"« Miracle grec » ou héritage égyptien ?","verrou":true},{"t":"L'objet de la philosophie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Montrer l'universalité de la démarche philosophique","situation":"En 1re D à Kribi, un élève déclare pendant l'exposé : « La philosophie, c'est un truc d'Européens ; nous, Africains, nous n'avons rien à y faire. »","tache":"Lui répondre en s'appuyant sur l'origine et l'objet de la philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-ponctuation",{"c":"1re C","m":"francais","rang":4,"titre":"Morphosyntaxe : la ponctuation, rôles et emplois","duree":55,"accroche":"« Mangeons, les enfants ! » ou « Mangeons les enfants ! » : une virgule sauve des vies.","intro":"Leçon de langue (rubrique Morphosyntaxe). On observe un même communiqué ponctué de deux façons, on découvre comment la ponctuation organise la phrase et change le sens, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["identifier les signes de ponctuation et leurs rôles","employer correctement la virgule, le point-virgule et les deux-points","analyser les effets de la ponctuation dans un texte littéraire"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>1. « Le proviseur dit : “Le délégué est absent.” »<br>2. « Le proviseur, dit le délégué, est absent. »<br>3. « Attention ! Les élèves qui n'ont pas leur tenue ne composeront pas. »<br>4. « Attention ! Les élèves, qui n'ont pas leur tenue, ne composeront pas. »<br>5. « Ils avaient tout préparé : les chaises, les tables, les micros… Personne ne vint. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Dans les phrases 1 et 2, qui est absent ? Quels signes changent le sens ?</li><li>Dans les phrases 3 et 4, tous les élèves sont-ils concernés ? Explique le rôle des virgules.</li><li>Dans la phrase 5, à quoi servent les deux-points ? et les points de suspension ?</li><li>Quels signes terminent une phrase ? Lesquels sont à l'intérieur de la phrase ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Phrase 1 : le délégué est absent (paroles rapportées entre guillemets après les deux-points) ; phrase 2 : le proviseur est absent (« dit le délégué » est une incise entre virgules). 2. Phrase 3 : seuls ceux qui n'ont pas leur tenue (relative <strong>déterminative</strong>, sans virgules) ; phrase 4 : tous les élèves, car la relative entre virgules est <strong>explicative</strong> (tous n'ont pas leur tenue). 3. Les deux-points annoncent une <strong>énumération</strong> ; les points de suspension marquent une <strong>énumération inachevée</strong> et préparent la chute. 4. Point, point d'interrogation, point d'exclamation, points de suspension terminent la phrase ; virgule, point-virgule, deux-points, guillemets, tirets, parenthèses sont à l'intérieur.</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>ponctuation</strong> est l'ensemble des signes qui organisent l'écrit : elle délimite les phrases, structure leurs éléments, rapporte les paroles, et peut <strong>changer le sens</strong> d'un énoncé.</div>","retenir":"La ponctuation délimite, organise, rapporte les paroles et peut changer le sens."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Ponctuer correctement un écrit pour qu'il soit compris sans ambiguïté","situation":"Le communiqué suivant doit être affiché au lycée bilingue de Buea : « attention les élèves de 1re C et D qui n'ont pas payé l'APEE ne composeront pas lundi le proviseur recevra les parents mardi à 9 heures »","tache":"Rétablir la ponctuation et justifier trois signes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-industrialisation",{"c":"1re C","m":"histoire","rang":2,"titre":"L'industrialisation de l'Europe (XVIIIᵉ-XIXᵉ siècles)","duree":25,"accroche":"La machine à vapeur a changé l'Europe… puis le destin de l'Afrique.","intro":"À partir de la fin du XVIIIᵉ siècle, l'Europe passe d'une économie agricole et artisanale à une économie industrielle fondée sur les machines, le charbon et les usines. Cette révolution transforme les sociétés européennes et pousse les puissances industrielles à conquérir de nouveaux territoires, notamment en Afrique.","objectifs":["expliquer les causes et les étapes de la révolution industrielle","décrire ses conséquences économiques et sociales","établir le lien entre industrialisation et impérialisme en Afrique"],"parties":[{"t":"La première révolution industrielle","html":"<p>Elle commence en <strong>Grande-Bretagne</strong> vers <strong>1760-1780</strong>, puis gagne la France, la Belgique et l'Allemagne au XIXᵉ siècle.</p><div class='def'><b>Les causes</b>Une <strong>révolution agricole</strong> qui nourrit plus d'habitants et libère de la main-d'œuvre ; une <strong>croissance démographique</strong> ; des <strong>capitaux</strong> issus du commerce, y compris le commerce triangulaire ; du <strong>charbon</strong> et du <strong>fer</strong> en abondance ; des inventions.</div><ul><li><strong>Textile</strong> : navette volante (Kay, 1733), machines à filer.</li><li><strong>Machine à vapeur</strong> perfectionnée par <strong>James Watt</strong> (1769).</li><li><strong>Chemin de fer</strong> : locomotive de Stephenson ; ligne Liverpool-Manchester (1830) ; bateaux à vapeur.</li></ul>","retenir":"Grande-Bretagne, fin du XVIIIᵉ siècle : charbon, fer, textile, machine à vapeur (Watt), chemin de fer."},{"t":"La deuxième révolution industrielle","verrou":true},{"t":"Conséquences : sociétés nouvelles et expansion coloniale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine historique de la place de l'Afrique dans les échanges mondiaux","situation":"Lors d'une sortie au port de Douala, tu observes des grumes de bois et des fèves de cacao chargées vers l'Europe, et des voitures et des machines déchargées. Ton camarade demande : « Pourquoi exportons-nous des produits bruts et importons-nous des produits finis ? »","tache":"Expliquer l'origine de cette situation et proposer une piste de changement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-methode",{"c":"1re C","m":"philo","rang":3,"titre":"La méthode de la philosophie","duree":25,"accroche":"Le physicien a son laboratoire ; le philosophe a sa méthode.","intro":"La philosophie n'utilise ni microscope ni expérience de laboratoire. Elle avance pourtant avec méthode : elle questionne, définit, problématise, argumente. Des philosophes ont même décrit leur méthode, de Socrate à Descartes. Ces outils te serviront dans toutes les disciplines.","objectifs":["identifier les étapes de la démarche philosophique","présenter la méthode socratique et la méthode cartésienne","appliquer la démarche à une question de la vie courante"],"parties":[{"t":"Les quatre gestes du philosophe","html":"<div class='def'><b>Définition</b>Une <strong>méthode</strong> (du grec <em>methodos</em>, « chemin vers ») est une démarche ordonnée pour parvenir à la vérité. En philosophie, elle consiste à questionner, définir, problématiser et argumenter.</div><ol><li><strong>Questionner</strong> : transformer une évidence en question (« Est-il toujours juste d'obéir à la loi ? »).</li><li><strong>Conceptualiser</strong> : définir précisément les notions, distinguer les sens (loi juridique, loi morale, loi scientifique).</li><li><strong>Problématiser</strong> : montrer pourquoi la question fait difficulté, en opposant des réponses possibles.</li><li><strong>Argumenter</strong> : justifier chaque affirmation par des raisons, des exemples, des références, et examiner les objections.</li></ol><div class='astuce'><b>Astuce</b>Ces quatre gestes sont exactement ceux de la dissertation : introduction (questionner, définir, problématiser), développement (argumenter).</div>","retenir":"Questionner, conceptualiser, problématiser, argumenter."},{"t":"La méthode socratique","verrou":true},{"t":"La méthode cartésienne et la dialectique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Appliquer une méthode rigoureuse pour examiner une information","situation":"Un message circule dans le groupe WhatsApp de ta classe à Bafia : « Boire de l'eau chaude avec du citron guérit le paludisme. Partagez ! »","tache":"Examiner le message avec la méthode cartésienne et la démarche philosophique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-narratif",{"c":"1re C","m":"francais","rang":5,"titre":"Stylistique : le texte narratif","duree":55,"accroche":"Un narrateur, des personnages, une intrigue : tout récit obéit à une architecture.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe un court récit, on découvre ses marques (temps, narrateur, structure), puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier le narrateur et les points de vue","appliquer le schéma narratif et le schéma actantiel","dégager les fonctions d'un récit"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (récit composé pour la leçon) :</p><blockquote>« Ce matin-là, le vieux pêcheur Ebénézer poussa sa pirogue vers le large. La mer était calme et le ciel, d'un bleu parfait. Soudain, le vent se leva ; les vagues grossirent et l'embarcation se mit à tanguer. Ebénézer rama de toutes ses forces. Après une heure de lutte, il aperçut enfin la plage de Kribi. Depuis ce jour, il ne sort plus sans regarder le ciel. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui raconte l'histoire ? Le narrateur participe-t-il à l'action ?</li><li>Relève les verbes au passé simple et à l'imparfait. Lesquels font avancer l'action ? Lesquels décrivent le décor ?</li><li>Découpe le récit en cinq moments.</li><li>Relève les indicateurs de temps. Quel rôle jouent-ils ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Un narrateur extérieur à l'histoire (3e personne) : <strong>narrateur hétérodiégétique</strong>. 2. Passé simple (poussa, se leva, rama, aperçut) : actions de premier plan ; imparfait (était) : arrière-plan, description. 3. <strong>Situation initiale</strong> (la mer calme), <strong>élément perturbateur</strong> (le vent se leva), <strong>péripéties</strong> (vagues, lutte), <strong>dénouement</strong> (la plage), <strong>situation finale</strong> (il regarde le ciel). 4. Ce matin-là, soudain, après une heure, enfin, depuis ce jour : ils organisent la chronologie et marquent les étapes.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte narratif</strong> raconte une suite d'événements organisés dans le temps, par un <strong>narrateur</strong>, selon un <strong>schéma narratif</strong>, avec une alternance de temps (passé simple et imparfait, ou présent de narration).</div>","retenir":"Narrateur, schéma narratif, temps du récit, indicateurs chronologiques."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Analyser et construire un récit à l'aide des outils de la narratologie","situation":"Pour le concours de nouvelles du club de lecture de ton lycée à Edéa, tu dois écrire un récit court sur un jeune qui quitte son village pour chercher du travail à Douala.","tache":"Établir les schémas narratif et actantiel, le narrateur, la focalisation et la fonction du récit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-recherche-idees",{"c":"1re C","m":"francais","rang":6,"titre":"La dissertation : rechercher les idées et les exemples","duree":25,"accroche":"Une page blanche n'est pas un manque d'idées : c'est un manque de méthode.","intro":"Une fois le sujet analysé et la problématique posée, beaucoup d'élèves restent bloqués : « je n'ai pas d'idées ». La recherche des idées est pourtant une technique, qui s'apprend : questionner le sujet, puiser dans ses lectures, classer ce que l'on trouve. C'est l'étape qui prépare le plan.","objectifs":["utiliser des techniques pour trouver des arguments","choisir des exemples littéraires précis et pertinents","classer les idées pour préparer un plan"],"parties":[{"t":"Trouver des arguments","html":"<ol><li><strong>Le remue-méninges</strong> : noter au brouillon, sans trier, tout ce que le sujet évoque (idées, œuvres, auteurs, souvenirs de lecture).</li><li><strong>Les questions clés</strong> : Pourquoi ? Comment ? Dans quels cas ? Jusqu'à quel point ? Pour qui ?</li><li><strong>Le pour et le contre</strong> : chercher ce qui justifie la thèse du sujet, puis ce qui la limite.</li><li><strong>Les notions voisines</strong> : un sujet sur le roman fait penser au lecteur, au réalisme, à l'engagement, au plaisir.</li></ol><div class='def'><b>Argument et exemple</b>L'<strong>argument</strong> est une idée générale qui justifie une affirmation ; l'<strong>exemple</strong> est un fait précis (une œuvre, une scène, un personnage) qui illustre l'argument.</div>","retenir":"Remue-méninges, questions clés, pour et contre, notions voisines ; argument ≠ exemple."},{"t":"Choisir de bons exemples","verrou":true},{"t":"Classer les idées","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rechercher et organiser des idées pour construire une dissertation","situation":"En devoir à Sangmélima, le sujet est : « La lecture des œuvres littéraires est-elle encore utile à l'ère du numérique ? » Ta voisine a écrit au brouillon : « oui c'est utile », et rien d'autre.","tache":"Proposer des arguments avec exemples et les classer en plan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-imperialisme",{"c":"1re C","m":"histoire","rang":3,"titre":"Les fondements de l'impérialisme européen","duree":25,"accroche":"Pourquoi l'Europe a-t-elle voulu se partager l'Afrique à la fin du XIXᵉ siècle ?","intro":"Entre 1880 et 1914, les puissances européennes se lancent dans une course aux colonies : en une trentaine d'années, presque toute l'Afrique est conquise et partagée. Cette expansion, appelée impérialisme, a des causes économiques, politiques, démographiques, idéologiques et scientifiques, que les Européens de l'époque exposaient sans détour.","objectifs":["définir l'impérialisme","expliquer ses fondements économiques, politiques, démographiques et idéologiques","porter un regard critique sur les justifications de la colonisation"],"parties":[{"t":"Définition et fondements économiques","html":"<div class='def'><b>Définition</b>L'<strong>impérialisme</strong> est la volonté d'un État d'étendre sa domination politique, économique et culturelle sur d'autres territoires et peuples. La <strong>colonisation</strong> en est la forme la plus directe.</div><ul><li>Les industries européennes ont besoin de <strong>matières premières</strong> (caoutchouc, huile de palme, coton, cacao, minerais).</li><li>Elles cherchent des <strong>débouchés</strong> pour leurs produits manufacturés, protégés par le <strong>protectionnisme</strong> des pays rivaux.</li><li>Les banques veulent placer des <strong>capitaux</strong> dans des investissements rentables (chemins de fer, mines, plantations).</li></ul><div class='ex'><b>Jules Ferry (1885)</b>« La politique coloniale est fille de la politique industrielle. »</div>","retenir":"Impérialisme : domination ; fondements économiques : matières premières, débouchés, capitaux."},{"t":"Fondements politiques et démographiques","verrou":true},{"t":"Fondements idéologiques, religieux et scientifiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les fondements de l'impérialisme avec un regard critique","situation":"Lors d'une exposition au musée national de Yaoundé, un visiteur affirme devant une carte de l'Afrique en 1914 : « Les Européens sont venus pour nous civiliser, c'était une bonne chose. »","tache":"Lui répondre en exposant les vrais fondements de l'impérialisme et les limites de cet argument."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-dissertation",{"c":"1re C","m":"francais","rang":3,"titre":"Dissertation littéraire : analyser le sujet et formuler la problématique","duree":25,"accroche":"Le sujet contient déjà la moitié de la copie : encore faut-il savoir le lire.","intro":"La dissertation littéraire demande de discuter une opinion sur la littérature (le roman, la poésie, le théâtre, le rôle de l'écrivain) à partir de tes lectures. Les copies échouent rarement par manque d'idées : elles échouent parce que le sujet a été mal lu. Cette leçon apprend à le décortiquer.","objectifs":["identifier les éléments d'un sujet de dissertation","analyser les mots clés et la thèse proposée","formuler une problématique pertinente"],"parties":[{"t":"Les éléments d'un sujet","html":"<p>Un sujet de dissertation comprend en général :</p><ul><li>une <strong>citation</strong> ou une affirmation (souvent d'un écrivain ou d'un critique) ;</li><li>une <strong>consigne</strong> : « Commentez », « Discutez », « Partagez-vous ce point de vue ? », « Vous illustrerez votre réponse d'exemples précis ».</li></ul><div class='def'><b>Les types de consigne</b><strong>Explicative</strong> (« expliquez », « justifiez ») : on montre que la thèse est juste. <strong>Dialectique</strong> (« discutez », « partagez-vous… ») : on examine la thèse puis ses limites. <strong>Comparative</strong> : on confronte deux thèses.</div><div class='attention'><b>Attention</b>La consigne commande le plan : « discutez » appelle un plan dialectique, « expliquez » un plan analytique.</div>","retenir":"Citation + consigne ; c'est la consigne qui décide du type de plan."},{"t":"Analyser les mots clés","verrou":true},{"t":"Formuler la problématique","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C","famille":"Vie sociale et culturelle","agir":"Analyser un sujet de dissertation pour construire une réflexion pertinente","situation":"Le club de lecture de ton lycée à Limbé prépare un débat. Sujet affiché : « L'écrivain africain doit être un combattant. » Discutez cette affirmation en vous appuyant sur des exemples précis.","tache":"Analyser le sujet et formuler une problématique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-importance",{"c":"1re C","m":"philo","rang":4,"titre":"L'importance de la philosophie","duree":25,"accroche":"« Vivre sans philosopher, c'est avoir les yeux fermés. » (Descartes)","intro":"« À quoi sert la philosophie ? » La question revient souvent, surtout en série scientifique. Elle ne produit ni pont ni médicament. Pourtant, elle forme le jugement, libère des préjugés, éclaire nos choix et ceux de la société. Cette leçon examine son utilité pour l'individu et pour l'Afrique.","objectifs":["présenter les apports de la philosophie à l'individu","montrer son rôle dans la société et le développement","répondre aux critiques qui la jugent inutile"],"parties":[{"t":"Pour l'individu","html":"<div class='def'><b>Définition</b>L'<strong>importance</strong> de la philosophie désigne la valeur et les services qu'elle rend : former un esprit libre, capable de juger par lui-même et de bien conduire sa vie.</div><ul><li><strong>Libérer des préjugés</strong> : Descartes : « C'est proprement avoir les yeux fermés, sans tâcher jamais de les ouvrir, que de vivre sans philosopher » (<em>Principes</em>, préface).</li><li><strong>Apprendre à bien vivre</strong> : Épicure : il n'est jamais trop tôt ni trop tard pour philosopher, car il s'agit de la santé de l'âme (<em>Lettre à Ménécée</em>).</li><li><strong>Former l'esprit critique</strong> : raisonner, argumenter, repérer les sophismes.</li></ul>","retenir":"Pour l'individu : liberté de jugement, art de bien vivre, esprit critique."},{"t":"Pour la société et l'Afrique","verrou":true},{"t":"Répondre aux critiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Justifier l'utilité de la philosophie pour un futur scientifique","situation":"Le conseil de classe de 1re D d'un lycée de Kumba propose de supprimer les heures de philosophie pour ajouter des heures de SVT avant le probatoire.","tache":"Rédiger une dissertation courte sur l'utilité de la philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-science",{"c":"1re C","m":"philo","rang":5,"titre":"Philosophie et science : quels rapports ?","duree":25,"accroche":"« Science sans conscience n'est que ruine de l'âme. » (Rabelais)","intro":"Pendant des siècles, philosophie et science ne faisaient qu'un. Puis les sciences se sont séparées et ont conquis le savoir sur la nature. Faut-il en conclure que la philosophie est dépassée ? Ou les deux démarches restent-elles complémentaires ?","objectifs":["distinguer démarche scientifique et démarche philosophique","présenter l'histoire de leurs rapports","montrer leur complémentarité"],"parties":[{"t":"Deux démarches distinctes","html":"<div class='def'><b>Définitions</b>La <strong>science</strong> est une connaissance <strong>objective</strong>, <strong>méthodique</strong> et <strong>vérifiable</strong> des phénomènes, qui établit des lois par l'observation, l'hypothèse et l'expérimentation. La <strong>philosophie</strong> est une réflexion critique sur les <strong>fondements</strong>, le <strong>sens</strong> et les <strong>valeurs</strong>.</div><ul><li>La science répond à la question <strong>comment ?</strong> ; la philosophie à <strong>pourquoi ?</strong> et <strong>que vaut ?</strong></li><li>La science spécialise ; la philosophie cherche une vue d'ensemble.</li></ul>","retenir":"Science : comment, lois vérifiables ; philosophie : fondements, sens, valeurs."},{"t":"Une histoire de séparation","verrou":true},{"t":"Une complémentarité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Environnement, santé et bien-être","agir":"Articuler science et éthique pour protéger les personnes","situation":"Un laboratoire propose à des familles de Bertoua de tester gratuitement un nouveau médicament sur leurs enfants, sans leur expliquer les risques.","tache":"Rédiger une dissertation courte sur les rapports entre science et philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-conquetes-francaises",{"c":"1re C","m":"histoire","rang":5,"titre":"Les conquêtes françaises en Afrique","duree":25,"accroche":"De Dakar au lac Tchad : la France taille un empire à coups de colonnes militaires.","intro":"Entre 1830 et 1912, la France conquiert un immense domaine en Afrique du Nord, de l'Ouest, du Centre et à Madagascar. Elle se heurte partout à des résistances. Une de ses batailles décisives se déroule sur le sol actuel du Cameroun, à Kousséri.","objectifs":["situer les étapes et les zones des conquêtes françaises","décrire les méthodes de conquête","présenter les grandes résistances et l'organisation des colonies (AOF, AEF)"],"parties":[{"t":"Les étapes de la conquête","html":"<div class='def'><b>Définition</b>La <strong>conquête coloniale</strong> est la prise de contrôle militaire, politique et économique d'un territoire et de ses habitants par une puissance étrangère.</div><ul><li><strong>Afrique du Nord</strong> : Algérie (à partir de 1830), protectorats sur la Tunisie (1881) et le Maroc (1912).</li><li><strong>Afrique de l'Ouest</strong> : à partir du Sénégal (gouverneur Faidherbe, 1854-1865), pénétration vers le Niger ; Dahomey (1892-1894).</li><li><strong>Afrique centrale</strong> : Savorgnan de Brazza signe le traité avec le roi Makoko (1880) ; vers le Tchad.</li><li><strong>Madagascar</strong> : conquise en 1895-1896.</li></ul>","retenir":"Algérie 1830, Tunisie 1881, Maroc 1912 ; Sénégal-Niger ; Congo-Tchad ; Madagascar 1896."},{"t":"Les méthodes et les résistances","verrou":true},{"t":"L'organisation de l'empire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les conquêtes coloniales et en garder une mémoire juste","situation":"En visite à Kousséri, un groupe d'élèves de Maroua découvre une stèle commémorant la bataille de 1900, qui ne cite que les officiers français.","tache":"Rédiger un panneau complémentaire sur la bataille, Rabah et les populations."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-conquetes-anglaises",{"c":"1re C","m":"histoire","rang":6,"titre":"Les conquêtes anglaises en Afrique","duree":25,"accroche":"« Du Cap au Caire » : le rêve d'un empire britannique d'un bout à l'autre de l'Afrique.","intro":"Première puissance industrielle et maritime du XIXᵉ siècle, la Grande-Bretagne veut contrôler les routes vers l'Inde et les richesses de l'Afrique. Elle conquiert l'Égypte, le Soudan, l'Afrique australe, une partie de l'Afrique de l'Ouest et de l'Est, en se heurtant à de fortes résistances, et gouverne souvent par l'intermédiaire des chefs locaux.","objectifs":["situer les principales conquêtes britanniques","présenter les résistances africaines","expliquer l'indirect rule"],"parties":[{"t":"Les grandes zones de conquête","html":"<div class='def'><b>Définition</b>L'<strong>Empire britannique</strong> est l'ensemble des territoires dominés par la Grande-Bretagne ; en Afrique, il vise la maîtrise des routes vers l'Inde (canal de Suez, Le Cap) et des ressources (or, diamants, huile de palme).</div><ul><li><strong>Égypte</strong> : occupée en 1882 (bataille de Tell el-Kébir) pour contrôler le canal de Suez.</li><li><strong>Soudan</strong> : Kitchener écrase les mahdistes à <strong>Omdurman</strong> (1898).</li><li><strong>Afrique australe</strong> : colonie du Cap ; Cecil Rhodes et sa compagnie conquièrent les Rhodésies ; guerre contre les Boers (1899-1902).</li><li><strong>Afrique de l'Ouest</strong> : Nigeria (Lagos 1861, Royal Niger Company), Gold Coast (Ghana), Sierra Leone, Gambie.</li><li><strong>Afrique de l'Est</strong> : Kenya, Ouganda.</li></ul>","retenir":"Égypte (1882), Soudan (1898), Afrique australe (Rhodes, Boers), Nigeria, Gold Coast, Kenya."},{"t":"Les résistances","verrou":true},{"t":"L'administration : l'indirect rule","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les héritages coloniaux pour renforcer l'unité nationale","situation":"Lors d'un débat au lycée bilingue de Buea, un élève demande pourquoi les régions du Nord-Ouest et du Sud-Ouest ont un système scolaire et juridique différent.","tache":"Expliquer l'origine historique de cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-enonciation",{"c":"1re C","m":"francais","rang":7,"titre":"Communication : l'énonciation, marques explicites et implicites","duree":55,"accroche":"Qui parle, à qui, quand, où ? Et que dit-il sans le dire ?","intro":"Leçon de langue (rubrique Communication). On observe un message affiché dans un lycée, on y repère qui parle, à qui, où et quand, et ce qui est dit sans être écrit, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["identifier la situation d'énonciation","repérer les marques explicites (indices personnels, déictiques, modalisateurs)","dégager les marques implicites (présupposés, sous-entendus)"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (texte composé pour la leçon) :</p><blockquote>« Chers camarades, ici, dans notre lycée d'Ebolowa, nous avons encore trouvé des papiers sous les tables ce matin. Je vous demande, une dernière fois, de respecter la salle. Sans doute certains pensent-ils que d'autres nettoieront à leur place… Merci à ceux qui gardent la classe aussi propre que d'habitude ! — Le délégué. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui parle ? À qui ? Où ? Quand ? Relève les mots qui l'indiquent.</li><li>Ces mots auraient-ils le même sens écrits par quelqu'un d'autre, ailleurs, un autre jour ?</li><li>Relève les mots qui montrent l'opinion ou le sentiment de l'émetteur.</li><li>La dernière phrase est-elle un vrai remerciement ? Qu'entend-on derrière ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Émetteur : le délégué (« je », signature) ; récepteurs : les camarades (« vous », « Chers camarades ») ; lieu : « ici, dans notre lycée d'Ebolowa » ; moment : « ce matin ». 2. Non : « je », « vous », « ici », « ce matin » ne prennent leur sens que dans la situation : ce sont des <strong>déictiques</strong>. 3. « encore », « une dernière fois », « sans doute » : agacement et doute (<strong>modalisateurs</strong>). 4. Non : c'est de l'<strong>ironie</strong> ; le message implicite est que la classe est sale et que certains sont visés.</p></details><div class='def'><b>Ce que montre l'observation</b>L'<strong>énonciation</strong> est l'acte de produire un énoncé dans une situation donnée : qui parle, à qui, où, quand. Les <strong>marques explicites</strong> (pronoms personnels, déictiques de lieu et de temps, temps verbaux) la rendent visible ; les <strong>marques implicites</strong> (modalisateurs, ironie, sous-entendus) disent l'attitude de l'émetteur sans la déclarer.</div>","retenir":"Énonciation : qui, à qui, où, quand ; marques explicites (déictiques) et implicites (modalisateurs, ironie, sous-entendus)."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Analyser les marques de l'énonciation pour comprendre les intentions d'un message","situation":"Sur le tableau d'affichage de ton lycée à Ebolowa, un élève a écrit : « Merci à ceux qui gardent les toilettes aussi propres que d'habitude… Certains se reconnaîtront. »","tache":"Analyser la situation d'énonciation, les marques explicites et implicites et l'effet produit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-modals",{"c":"1re C","m":"anglais","rang":2,"titre":"Modals: permission, possibility, obligation, advice and deduction","duree":25,"accroche":"May I go out? You must be tired! You needn't come: small words, big differences.","intro":"Modal verbs (can, may, must, should…) add an attitude to the main verb: permission, ability, possibility, obligation, advice or deduction. They are tested in almost every Probatoire and Baccalauréat paper.","objectifs":["form sentences with modal verbs","choose the right modal for permission, possibility, obligation, absence of obligation and advice","use must and can't for deduction"],"parties":[{"t":"What is a modal verb?","html":"<div class='def'><b>Definition</b>A <strong>modal verb</strong> is an auxiliary placed before a <strong>bare infinitive</strong> (without « to ») to express the speaker's attitude. It never takes « -s » and makes its question and negative without « do »: <em>She can swim. Can she swim? She cannot (can't) swim.</em></div><ul><li><strong>Permission</strong>: <em>can</em>, <em>may</em> (more polite): <em>May I come in, sir?</em></li><li><strong>Possibility</strong>: <em>can</em> (general), <em>could</em>, <em>may</em>, <em>might</em> (less sure): <em>It might rain this afternoon.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>Never « He cans » or « She must to go ». Modal + bare infinitive: <em>She must go.</em></div>","retenir":"Modal + bare infinitive; no -s, no do."},{"t":"Obligation, no obligation, advice","verrou":true},{"t":"Deduction","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première C","famille":"Citoyenneté","agir":"Use modal verbs to give rules, advice and permission in real-life situations","situation":"Your school in Kribi is organising a clean-up campaign on the beach on Saturday. As class prefect, you write the rules for your classmates.","tache":"Write a notice using different modals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-purpose-result",{"c":"1re C","m":"anglais","rang":5,"titre":"Expressing purpose, result and preference; let's / let's not","duree":25,"accroche":"I study hard so that I can pass. It rained so much that the road was closed. I'd rather walk.","intro":"To argue, explain or plan, you must say why you do something (purpose), what happens as a consequence (result) and what you prefer. These structures are essential in essays, letters and dialogues.","objectifs":["express purpose with to, in order to, so as to, so that","express result with so … that, such … that, so, therefore","express preference with prefer, would rather, had better, and make suggestions with let's"],"parties":[{"t":"Purpose","html":"<div class='def'><b>Definition</b><strong>Purpose</strong> is the aim of an action: it answers the question « Why? / What for? ».</div><ul><li><strong>to / in order to / so as to + infinitive</strong> (same subject): <em>She saves money (in order) to buy a laptop.</em> Negative: <em>in order not to / so as not to</em>: <em>He left early so as not to miss the bus.</em></li><li><strong>so that + subject + can / could / will / would</strong> (different subjects possible): <em>The teacher speaks slowly so that everybody can understand.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>« Pour + infinitif » is <em>to</em>, never « for to »: <em>I came to see you</em>, not « for to see you ».</div>","retenir":"to / in order to / so as to + infinitive; so that + subject + can / could."},{"t":"Result","verrou":true},{"t":"Preference, advice and suggestion","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première C","famille":"Vie sociale et culturelle","agir":"Express purpose, result and preference to take decisions in a group","situation":"Your class in Bafoussam wants to raise money for the end-of-year trip. The class meeting must choose between selling snacks at break time and organising a cultural evening.","tache":"Write a dialogue using purpose, result, preference and let's."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-prepositions",{"c":"1re C","m":"anglais","rang":8,"titre":"Prepositions of place, time, manner and direction","duree":20,"accroche":"In Douala, on Monday, at 7 a.m., by taxi, towards the port: prepositions place everything.","intro":"Prepositions are short words, but they cause many mistakes, because they rarely translate word for word from French. This lesson organises them by meaning: place, time, manner and direction.","objectifs":["use prepositions of place and time correctly","use prepositions of direction and manner","avoid the most common French-speaker mistakes"],"parties":[{"t":"Place and time: at, on, in","html":"<div class='def'><b>Definition</b>A <strong>preposition</strong> is a word placed before a noun or pronoun to show its relation to another word: place, time, direction, manner. A <strong>prepositional phrase</strong> is the preposition + its noun: <em>under the table, in the morning</em>.</div><ul><li><strong>Place</strong>: <em>at</em> a point (at the bus stop, at school), <em>on</em> a surface or a street (on the wall, on Joss Street), <em>in</em> an enclosed space, town or country (in the classroom, in Garoua, in Cameroon).</li><li><strong>Time</strong>: <em>at</em> + clock time and festivals (at 7 o'clock, at Christmas), <em>on</em> + days and dates (on Monday, on 20th May), <em>in</em> + months, years, seasons, parts of the day (in May, in 1960, in the dry season, in the morning).</li></ul>","retenir":"at (point / hour), on (surface / day), in (inside / month, year)."},{"t":"Direction and movement","verrou":true},{"t":"Manner and fixed expressions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première C","famille":"Vie sociale et culturelle","agir":"Use prepositions to give precise directions and times","situation":"A pen friend from Ghana is coming to visit you in Buea. She will arrive at the Douala airport and must find your house alone.","tache":"Write an e-mail with precise directions using prepositions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-conditionals",{"c":"1re C","m":"anglais","rang":10,"titre":"Conditionals: types 1, 2 and 3","duree":25,"accroche":"If it rains, we'll stay. If I were rich, I'd build a school. If I had revised, I would have passed.","intro":"Conditional sentences link a condition (the if-clause) and its consequence. English has three main types, each with its own tenses. They are among the most frequent grammar questions at the Probatoire and the Baccalauréat.","objectifs":["form the three types of conditional sentences","choose the type according to the meaning (real, unreal present, unreal past)","use unless, provided that and as long as"],"parties":[{"t":"Type 1: real or possible","html":"<div class='def'><b>Definition</b>A <strong>conditional sentence</strong> has two clauses: the <strong>if-clause</strong> (condition) and the <strong>main clause</strong> (result). <strong>Type 1</strong> describes a <strong>real or likely</strong> situation in the present or future.</div><p class='formule'>If + simple present → will + bare infinitive</p><ul><li><em>If you study hard, you will pass.</em></li><li><em>If it rains, the match will be cancelled.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>No « will » in the if-clause: <em>If he comes</em>, not « If he will come ».</div>","retenir":"Type 1: if + present, will + infinitive (possible)."},{"t":"Type 2: unreal present","verrou":true},{"t":"Type 3 and other conjunctions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première C","famille":"Citoyenneté","agir":"Use conditionals to imagine solutions and express regrets","situation":"Your school's English club in Ngaoundéré organises an essay competition on the topic: « If I were the mayor of my town ».","tache":"Write a short essay using the three types of conditionals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-pharaonique",{"c":"1re C","m":"philo","rang":6,"titre":"La philosophie de la période pharaonique","duree":25,"accroche":"Deux mille ans avant Socrate, des sages d'Égypte enseignaient déjà la vérité et la justice.","intro":"On fait souvent commencer la philosophie en Grèce. Pourtant, l'Égypte pharaonique, civilisation africaine, a produit des enseignements de sagesse, une réflexion sur l'origine du monde et une morale fondée sur la Maât. Des historiens comme Cheikh Anta Diop et Théophile Obenga y voient la première philosophie africaine.","objectifs":["présenter les grands textes de sagesse de l'Égypte ancienne","expliquer la notion de Maât et la théologie de Memphis","évaluer la place de l'Égypte dans l'histoire de la philosophie"],"parties":[{"t":"Des sages et des enseignements","html":"<div class='def'><b>Définition</b>La <strong>philosophie de la période pharaonique</strong> désigne l'ensemble des réflexions sur le monde, l'homme et la conduite juste produites en Égypte ancienne (environ 2700 à 330 avant notre ère), sous forme de maximes, d'enseignements et de récits de création.</div><ul><li><strong>Imhotep</strong> (vers 2650 av. J.-C.), architecte de la pyramide à degrés de Saqqarah et médecin, vénéré comme un sage.</li><li>Les <strong>Maximes de Ptahhotep</strong> (vers 2400 av. J.-C.) : conseils d'un vizir à son fils sur la modestie, la parole juste, l'écoute.</li><li>Les enseignements de <strong>Kagemni</strong> et d'<strong>Amenemope</strong> : maîtrise de soi, honnêteté, respect du pauvre.</li></ul><div class='ex'><b>Une maxime</b>Ptahhotep : « Ne sois pas orgueilleux de ton savoir ; prends conseil de l'ignorant comme du savant. »</div>","retenir":"Imhotep, Ptahhotep, Kagemni, Amenemope : une sagesse pratique écrite."},{"t":"La Maât et la pensée de l'origine","verrou":true},{"t":"L'Égypte et la philosophie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Situer l'Égypte pharaonique dans l'histoire de la pensée","situation":"Au club d'histoire de ton lycée à Bertoua, un camarade affirme : « Les Égyptiens construisaient des pyramides, mais ils ne pensaient pas : la philosophie, ce sont les Grecs. »","tache":"Rédiger une dissertation courte sur l'existence d'une philosophie égyptienne."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-presocratiques",{"c":"1re C","m":"philo","rang":7,"titre":"Les présocratiques : Héraclite et Parménide","duree":25,"accroche":"Tout change, dit l'un ; rien ne change, répond l'autre.","intro":"Avant Socrate, des penseurs grecs cherchent le principe de toute chose. Deux d'entre eux s'opposent sur la question la plus simple et la plus vertigineuse : le monde est-il fait de changement ou de permanence ? Héraclite et Parménide fondent deux grandes manières de penser le réel.","objectifs":["situer les présocratiques","exposer la pensée du devenir d'Héraclite","exposer la pensée de l'être de Parménide et en mesurer la portée"],"parties":[{"t":"Les présocratiques","html":"<div class='def'><b>Définition</b>On appelle <strong>présocratiques</strong> les penseurs grecs antérieurs (ou contemporains) à Socrate, aux VIᵉ-Vᵉ siècles av. J.-C., qui cherchent l'<strong>arkhè</strong>, le principe premier de la nature (physis).</div><ul><li>Les Milésiens : Thalès (l'eau), Anaximène (l'air).</li><li>Pythagore : le nombre.</li><li><strong>Héraclite d'Éphèse</strong> et <strong>Parménide d'Élée</strong> : le devenir et l'être.</li></ul><p>Leurs œuvres ne nous sont parvenues que par <strong>fragments</strong> cités par d'autres auteurs.</p>","retenir":"Présocratiques : la recherche de l'arkhè ; œuvres en fragments."},{"t":"Héraclite : tout change","verrou":true},{"t":"Parménide : l'être est","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Réfléchir au changement et à la permanence","situation":"Ton grand-père de Foumban répète : « Les jeunes d'aujourd'hui ne sont plus comme avant. » Ta petite sœur lui répond : « Mais toi, tu es toujours le même grand-père ! »","tache":"Rédiger une dissertation courte sur la question : tout change-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-socrate-platon",{"c":"1re C","m":"philo","rang":8,"titre":"Socrate et Platon","duree":25,"accroche":"Un homme qui ne savait rien, et son élève qui voulut tout comprendre.","intro":"Socrate n'a rien écrit ; nous le connaissons surtout par son élève Platon. Le premier a fait de la philosophie un art de questionner et de vivre ; le second en a fait un système qui distingue le monde sensible et le monde des Idées. Leur pensée reste au cœur des sujets de philosophie.","objectifs":["présenter la vie et la méthode de Socrate","exposer la théorie des Idées et l'allégorie de la caverne","montrer l'actualité de leur pensée"],"parties":[{"t":"Socrate, le questionneur","html":"<div class='def'><b>Repères</b><strong>Socrate</strong> (470-399 av. J.-C.), Athénien, interroge ses concitoyens sur l'agora. Accusé d'impiété et de corrompre la jeunesse, il est <strong>condamné à boire la ciguë</strong> en 399 av. J.-C. et refuse de fuir pour respecter les lois.</div><ul><li><strong>Ironie</strong> et <strong>maïeutique</strong> : feindre l'ignorance, puis faire « accoucher » les esprits.</li><li>« Connais-toi toi-même » ; « Ce que je sais, c'est que je ne sais rien. »</li><li>« Nul n'est méchant volontairement » : le mal vient de l'ignorance du bien.</li></ul>","retenir":"Socrate : ironie, maïeutique, connaissance de soi ; condamné en 399 av. J.-C."},{"t":"Platon et la théorie des Idées","verrou":true},{"t":"Politique et actualité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Examiner les apparences avant de les croire","situation":"Ton cousin à Limbe passe ses nuits sur les réseaux sociaux et croit tout ce qu'il y voit : « Si c'est en vidéo, c'est vrai. »","tache":"Rédiger une dissertation courte sur les apparences avec Socrate et Platon."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-reactions-africaines",{"c":"1re C","m":"histoire","rang":8,"titre":"Les réactions africaines face aux agressions européennes : résistances et collaborations","duree":25,"accroche":"Résister ou s'allier : deux réponses africaines à une même conquête.","intro":"Face à la conquête européenne, les sociétés africaines n'ont pas réagi d'une seule façon. Beaucoup ont résisté par les armes ou autrement ; d'autres ont choisi de collaborer, par calcul, par contrainte ou pour se protéger de voisins rivaux. Comprendre ces choix évite de juger le passé avec simplisme.","objectifs":["présenter les formes de résistance","expliquer les raisons et les formes de la collaboration","illustrer ces réactions par des exemples africains et camerounais"],"parties":[{"t":"Les résistances","html":"<div class='def'><b>Définitions</b>La <strong>résistance</strong> est l'opposition à la conquête et à la domination coloniales. La <strong>collaboration</strong> est le choix de coopérer avec le colonisateur.</div><ul><li><strong>Résistance armée</strong> : Samory Touré (capturé en 1898), Béhanzin au Dahomey (1894), Menelik II à Adoua (1896), Rabah (Kousséri, 1900), les Zoulous (Isandhlwana, 1879).</li><li><strong>Résistances passives</strong> : fuite, refus de l'impôt et du travail forcé.</li><li><strong>Résistances religieuses</strong> : mouvements prophétiques.</li><li>Au Cameroun : les Bakweri de Kuva Likenye, le soulèvement des Bulu (1899-1901), Rudolf Duala Manga Bell et Martin-Paul Samba, exécutés en 1914.</li></ul>","retenir":"Résistances armées (Samory, Béhanzin, Menelik, Rabah), passives, religieuses ; au Cameroun : Bakweri, Bulu, Duala Manga Bell, Samba."},{"t":"Les collaborations","verrou":true},{"t":"Des choix complexes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les réactions africaines à la conquête sans simplisme","situation":"Lors d'un exposé à Foumban, un élève accuse le roi Njoya d'avoir « trahi l'Afrique » en s'alliant aux Allemands ; un autre répond qu'il a sauvé son royaume.","tache":"Expliquer la complexité des réactions africaines et donner un point de vue argumenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-exploitation-colonies",{"c":"1re C","m":"histoire","rang":9,"titre":"L'exploitation économique des colonies","duree":25,"accroche":"Cacao, caoutchouc, coton : produire pour la métropole, à n'importe quel prix.","intro":"Une fois la conquête achevée, les puissances coloniales organisent l'exploitation économique de l'Afrique au profit de la métropole. Les colonies doivent fournir des matières premières à bas prix et acheter des produits manufacturés. Ce système repose sur la contrainte : impôt, cultures obligatoires, travail forcé.","objectifs":["décrire l'économie de traite","présenter les méthodes de l'exploitation (impôt, travail forcé, sociétés concessionnaires)","mesurer les conséquences pour les Africains et pour l'économie actuelle"],"parties":[{"t":"L'économie de traite","html":"<div class='def'><b>Définition</b>L'<strong>économie de traite</strong> est le système dans lequel la colonie produit des matières premières agricoles ou minières pour l'exportation et achète des produits manufacturés à la métropole, par l'intermédiaire de maisons de commerce.</div><ul><li><strong>Cultures d'exportation</strong> : cacao, café, arachide, coton, huile de palme, caoutchouc, banane.</li><li><strong>Produits miniers</strong> : cuivre du Katanga (Congo belge), or de Gold Coast.</li><li><strong>Infrastructures</strong> orientées vers les ports : chemins de fer et routes de l'intérieur vers la côte (au Cameroun, lignes Douala-Nkongsamba et Douala-Yaoundé).</li></ul>","retenir":"Exporter des matières premières, importer des produits manufacturés ; routes et rails vers les ports."},{"t":"Les méthodes : la contrainte","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine coloniale de problèmes économiques et fonciers actuels","situation":"Les terres de la Cameroon Development Corporation (CDC), autour de Buea et Tiko, sont d'anciennes plantations allemandes. Des descendants de familles bakweri en réclament une partie.","tache":"Expliquer l'origine du problème et proposer un règlement pacifique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-plan-detaille",{"c":"1re C","m":"francais","rang":9,"titre":"Élaborer le plan détaillé d'une dissertation","duree":25,"accroche":"Un plan détaillé, c'est la copie déjà écrite… en squelette.","intro":"Après l'analyse du sujet et la recherche des idées, il faut organiser : choisir un type de plan, ordonner les arguments, placer les exemples. Le plan détaillé permet de rédiger ensuite sans se perdre, et c'est lui que le correcteur reconnaît dans une copie claire.","objectifs":["choisir le type de plan adapté au sujet","construire un plan détaillé hiérarchisé (I, A, 1)","rédiger les transitions"],"parties":[{"t":"Choisir le type de plan","html":"<div class='def'><b>Définition</b>Le <strong>plan détaillé</strong> est l'organisation hiérarchisée des idées d'une dissertation : grandes parties, sous-parties, arguments et exemples, avant la rédaction.</div><ul><li><strong>Dialectique</strong> (thèse, antithèse, synthèse) : pour « discutez », « partagez-vous… ? ».</li><li><strong>Analytique</strong> (causes, manifestations, conséquences, ou problème, causes, solutions) : pour « expliquez », « montrez ».</li><li><strong>Thématique</strong> : les différents aspects d'une notion.</li></ul><div class='attention'><b>Attention</b>Le plan doit répondre à la problématique : chaque partie est une étape de la réponse, pas un « tiroir » de connaissances.</div>","retenir":"Dialectique, analytique, thématique : la consigne et la problématique décident."},{"t":"Construire et hiérarchiser","verrou":true},{"t":"Les transitions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Organiser ses idées en un plan détaillé de dissertation","situation":"En devoir à Kribi, le sujet est : « Le théâtre est un miroir de la société. Discutez cette affirmation. » Ton camarade a trouvé des idées mais les a écrites dans le désordre.","tache":"Proposer un plan détaillé complet avec transitions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-denotation-connotation",{"c":"1re C","m":"francais","rang":8,"titre":"Sémantique : le sens des mots, dénotation et connotation","duree":55,"accroche":"« Lion » : un animal… ou une équipe de football et tout un pays fier.","intro":"Leçon de langue (rubrique Sémantique et lexicologie). On observe des noms de produits et un court texte, on distingue le sens premier des mots et ce qu'ils évoquent, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["distinguer dénotation et connotation","identifier les connotations mélioratives et péjoratives","analyser l'effet des connotations dans un texte"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (textes composés pour la leçon) :</p><blockquote>1. Trois noms proposés pour une eau minérale : « Source des Lions », « Eau du Puits », « Rosée du Mont Cameroun ».<br>2. « Le soir tombait sur Douala. La ville, fourmilière épuisée, laissait monter vers le ciel rouge la plainte de ses moteurs. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Cherche le sens de « lion », « puits » et « rosée » dans le dictionnaire.</li><li>Quelles idées, quelles impressions chacun de ces mots fait-il naître dans le nom d'une eau ?</li><li>Dans le texte 2, que désigne « fourmilière » au sens propre ? Qu'évoque-t-il ici ?</li><li>« ciel rouge », « plainte » : quel sentiment ces mots suggèrent-ils ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Lion : grand félin ; puits : trou creusé pour atteindre l'eau ; rosée : gouttes d'eau déposées le matin. 2. Lion : force, fierté nationale (les Lions indomptables) ; puits : eau ordinaire, parfois douteuse ; rosée : pureté, fraîcheur, nature de montagne. 3. Au sens propre, l'habitat des fourmis ; ici, la ville grouillante de gens affairés, épuisés. 4. La tristesse, la souffrance (« plainte »), et peut-être la violence ou la fin du jour (« rouge »).</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>dénotation</strong> est le sens premier, objectif et stable d'un mot, celui du dictionnaire. La <strong>connotation</strong> est l'ensemble des sens seconds, des valeurs et des impressions qu'un mot suggère selon le contexte, la culture ou l'individu.</div>","retenir":"Dénotation : sens du dictionnaire ; connotation : sens seconds, impressions, valeurs."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie économique","agir":"Analyser les connotations pour comprendre et choisir un message","situation":"Une entreprise de Douala lance une eau minérale et hésite entre trois noms : « Source des Lions », « Eau du Puits » et « Rosée du Mont Cameroun ».","tache":"Analyser les connotations et recommander un nom."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-reading-disputes",{"c":"1re C","m":"anglais","rang":7,"titre":"Reading comprehension: settling community disputes","duree":25,"accroche":"Read, understand, explain in your own words: the keys to Section C.","intro":"In the Probatoire and the Baccalauréat, the reading comprehension section tests your ability to understand a text, find information, explain words and statements in your own words, and give your opinion. This lesson trains these skills on a text about settling disputes in a Cameroonian community.","objectifs":["use reading strategies: skimming, scanning, guessing meaning from context","answer comprehension questions in your own words","use the vocabulary of conflict and mediation"],"parties":[{"t":"Reading strategies","html":"<div class='def'><b>Definitions</b><strong>Skimming</strong>: reading quickly to get the general idea. <strong>Scanning</strong>: looking for a specific piece of information (a name, a date). <strong>Inferring</strong>: guessing the meaning of a word or idea from the context.</div><ol><li>Read the questions first, then the text.</li><li>Skim the text for the main idea (title, first and last sentences).</li><li>Scan for the answers; underline the lines.</li><li>Answer in <strong>your own words</strong> unless you are asked to quote.</li></ol>","retenir":"Skim for the main idea, scan for details, infer from context, answer in your own words."},{"t":"The text","verrou":true},{"t":"Vocabulary of disputes","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re C","famille":"Citoyenneté","agir":"Read and understand texts on conflict resolution and propose peaceful solutions","situation":"In your quarter in Bamenda, two neighbours have been quarrelling for weeks about a fence. The quarter head asks students to suggest a way to settle the dispute.","tache":"Write a letter proposing a mediation meeting and a fair solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-logique",{"c":"1re C","m":"philo","rang":10,"titre":"La logique : définition et importance","duree":25,"accroche":"Bien penser, ce n'est pas seulement avoir des idées : c'est les enchaîner correctement.","intro":"Nous raisonnons sans cesse : « s'il pleut, le match sera annulé ; il pleut, donc… ». Mais nos raisonnements sont parfois faux sans que nous le voyions. La logique étudie les règles qui rendent un raisonnement valide. Née avec Aristote, elle est aujourd'hui au cœur des mathématiques et de l'informatique.","objectifs":["définir la logique et ses principes","distinguer validité et vérité","montrer l'importance de la logique dans la pensée, les sciences et la vie sociale"],"parties":[{"t":"Définition et principes","html":"<div class='def'><b>Définition</b>La <strong>logique</strong> (du grec <em>logos</em>, raison, discours) est la science des <strong>règles de la pensée correcte</strong> : elle étudie les conditions auxquelles un raisonnement est <strong>valide</strong>, c'est-à-dire auxquelles la conclusion découle nécessairement des prémisses.</div><ul><li><strong>Aristote</strong> (IVᵉ s. av. J.-C.) la fonde dans l'<em>Organon</em> (« l'instrument » de la pensée).</li><li><strong>Principes</strong> : <strong>identité</strong> (A est A) ; <strong>non-contradiction</strong> (une chose ne peut être à la fois A et non-A sous le même rapport) ; <strong>tiers exclu</strong> (une proposition est vraie ou fausse, sans troisième possibilité).</li></ul>","retenir":"Logique : règles de la pensée correcte ; Aristote ; identité, non-contradiction, tiers exclu."},{"t":"Le raisonnement : validité et vérité","verrou":true},{"t":"L'importance de la logique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Citoyenneté","agir":"Utiliser la logique pour démasquer les raisonnements trompeurs","situation":"Un message circule à Ngaoundéré : « Tous ceux qui ont réussi sont allés à l'étranger. Mon cousin est allé à l'étranger. Donc il a réussi. Partez tous ! »","tache":"Rédiger une dissertation courte sur la logique et l'erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-chine-traites",{"c":"1re C","m":"histoire","rang":10,"titre":"La Chine, des traités inégaux à l'éveil du nationalisme","duree":25,"accroche":"L'opium, des canonnières et des traités : un empire millénaire humilié.","intro":"Au XIXᵉ siècle, la Chine des Qing, longtemps puissante, est contrainte par les puissances européennes puis par le Japon à signer des « traités inégaux ». Ces humiliations provoquent des révoltes, puis l'éveil d'un nationalisme chinois qui renverse l'empire en 1911.","objectifs":["expliquer les guerres de l'opium et les traités inégaux","présenter les réactions chinoises (Taiping, Boxers)","décrire la naissance du nationalisme et de la République"],"parties":[{"t":"Les guerres de l'opium et les traités inégaux","html":"<div class='def'><b>Définition</b>Un <strong>traité inégal</strong> est un accord imposé par la force, qui accorde des avantages à une seule partie : ouverture de ports, cession de territoires, privilèges pour les étrangers.</div><ul><li>Les Britanniques vendent illégalement de l'<strong>opium</strong> venu d'Inde ; la Chine l'interdit et détruit des stocks (1839).</li><li><strong>Première guerre de l'opium</strong> (1839-1842) : <strong>traité de Nankin</strong> (1842) : Hong Kong cédée au Royaume-Uni, ports ouverts.</li><li><strong>Seconde guerre de l'opium</strong> (1856-1860) : sac du palais d'Été à Pékin (1860) ; nouveaux ports et privilèges.</li><li>Défaite face au <strong>Japon</strong> (1894-1895) : perte de Taïwan.</li></ul>","retenir":"Opium ; Nankin (1842), Hong Kong ; palais d'Été (1860) ; défaite face au Japon (1895)."},{"t":"Les réactions chinoises","html":"<ul><li><strong>Révolte des Taiping</strong> (1850-1864) : immense soulèvement contre la dynastie Qing ; des millions de morts.</li><li>Tentatives de modernisation, limitées par la cour impériale.</li><li><strong>Révolte des Boxers</strong> (1900) : société secrète qui attaque les étrangers et les missions ; écrasée par une coalition de huit puissances.</li></ul><div class='attention'><b>Le « dépeçage »</b>À la fin du siècle, les puissances se partagent la Chine en zones d'influence, sans la coloniser entièrement.</div>","retenir":"Taiping (1850-1864), Boxers (1900) ; zones d'influence étrangères.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["opium","Guerres de l'opium (1839-1842 ; 1856-1860)."],["Traité de Nankin","Traité de Nankin (1842) : Hong Kong ; traités inégaux."],["Défaite face au Japon","Défaite face au Japon (1895) ; zones d'influence."],["Taiping","Révoltes : Taiping (1850-1864), Boxers (1900)."],["Sun Yat-sen","Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."]]}},{"t":"L'éveil du nationalisme","html":"<ul><li><strong>Sun Yat-sen</strong> fonde un mouvement républicain ; ses « trois principes du peuple » : nationalisme, démocratie, bien-être du peuple.</li><li><strong>Révolution de 1911</strong> : l'empire s'effondre ; la <strong>République</strong> est proclamée le <strong>1er janvier 1912</strong> ; le parti nationaliste (Kuomintang) est créé.</li><li><strong>Mouvement du 4 mai 1919</strong> : les étudiants protestent contre le traité de Versailles, qui donne au Japon des droits sur le Shandong.</li><li>Le <strong>Parti communiste chinois</strong> est fondé en <strong>1921</strong>.</li></ul><div class='ex'><b>Comparaison</b>Comme en Afrique, l'humiliation coloniale a nourri un nationalisme moderne ; il conduira, en Chine, à la victoire communiste de 1949.</div>","retenir":"Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux formes de réaction des nationalistes chinois face à la domination étrangère, de la fin du XIXe siècle à 1921. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« Le traité de Nankin (1842) cède Taïwan au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec la Russie. La révolte des Taiping a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1949. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : humiliée par les traités inégaux, la Chine voit naître au tournant du XXe siècle un nationalisme moderne. Éléments : la révolte des Boxers (1900), soulèvement contre les étrangers, écrasé par une coalition de huit puissances ; la révolution de 1911 menée par Sun Yat-sen, qui renverse l'empire et proclame la République le 1er janvier 1912 ; on peut citer le mouvement du 4 mai 1919 contre le traité de Versailles. Explications : la xénophobie populaire puis un programme politique moderne (Trois principes du peuple). Bilan : le nationalisme chinois passe de la révolte à la construction d'un État moderne.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) Taïwan → Hong Kong ; 2) avec la Russie → avec le Japon ; 3) la révolte des Taiping en 1900 → la révolte des Boxers (les Taiping : 1850-1864) ; 4) 1949 → 1912. Texte corrigé : « Le traité de Nankin (1842) cède Hong Kong au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec le Japon. La révolte des Boxers a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1912. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Défense de la souveraineté nationale</strong></p><p><strong>Document 1 : Le traité de Shimonoseki</strong></p><blockquote>« … Signé à l'issue de la guerre sino-japonaise de 1895, ce traité exigeait l'indépendance de la Corée, qui fut annexée par le Japon en 1910. Le traité reconnaissait aussi l'autorité du Japon sur l'île de Formose et les îles Pescadores. »</blockquote><p><em>Source : fr.wikipedia.org (document du sujet officiel de Probatoire, histoire, session 2023).</em></p><p><strong>Document 2 : Les Trois principes du peuple de Sun Yat-sen</strong></p><blockquote>Le programme de Sun Yat-sen repose sur le nationalisme (libérer la Chine de la domination étrangère), la démocratie (gouvernement par le peuple) et le bien-être du peuple (meilleure répartition de la terre et des richesses).</blockquote><p><em>Source : Réalisation VÉRITAS (livret HGECM 2026-2027), synthèse.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique, à partir du document 1, en quoi le traité de Shimonoseki illustre la domination subie par la Chine à la fin du XIXe siècle. (3 pts)</li><li>Présente, à partir du document 2 et de tes connaissances, le projet des nationalistes chinois. (3 pts)</li><li>Montre ce que l'exemple chinois enseigne aux pays africains sur la défense de leur souveraineté. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : vaincue par le Japon, la Chine doit renoncer à la Corée et céder Formose (Taïwan) et les Pescadores : comme les traités de Nankin et de Tianjin, c'est un traité imposé par la force qui démembre le pays. Tâche 2 : Sun Yat-sen veut libérer la Chine des étrangers, établir la démocratie et améliorer la vie du peuple ; la révolution de 1911 renverse l'empire et la République est proclamée en 1912 ; le mouvement du 4 mai 1919 prolonge ce nationalisme. Tâche 3 : l'unité nationale, un projet politique clair et le développement économique sont les conditions de la souveraineté ; les divisions favorisent la domination étrangère.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : ouverture sur le monde et esprit critique."}],"revision":["Guerres de l'<strong>opium</strong> (1839-1842 ; 1856-1860).","<strong>Traité de Nankin</strong> (1842) : Hong Kong ; traités <strong>inégaux</strong>.","Défaite face au Japon (1895) ; zones d'influence.","Révoltes : <strong>Taiping</strong> (1850-1864), <strong>Boxers</strong> (1900).","<strong>Sun Yat-sen</strong> ; République (1912) ; 4 mai 1919 ; PCC (1921)."],"exo":"<p>Explique pourquoi on parle de traités « inégaux ». <em>(Réponse : Ils sont imposés par la force après des défaites militaires et n'accordent des avantages (ports, territoires, privilèges) qu'aux puissances étrangères.)</em></p>","quiz":[{"q":"La première guerre de l'opium oppose la Chine :","r":["au Royaume-Uni","au Japon","à la France seule","aux États-Unis"],"b":0,"e":"1839-1842."},{"q":"Un traité inégal est :","r":["un accord équilibré","un accord imposé par la force et favorable à une seule partie","un traité de paix africain","une constitution"],"b":1,"e":"Ports ouverts, territoires cédés."},{"q":"La révolte des Boxers a lieu en :","r":["1842","1864","1900","1919"],"b":2,"e":"Écrasée par huit puissances."},{"q":"La République de Chine est proclamée en :","r":["1842","1895","1949","1912"],"b":3,"e":"Le 1er janvier 1912."},{"q":"Les « trois principes du peuple » sont de :","r":["Sun Yat-sen","Mao Zedong","Deng Xiaoping","l'empereur"],"b":0,"e":"Nationalisme, démocratie, bien-être."},{"q":"Après la guerre de 1894-1895, la Chine perd :","r":["Hong Kong","Taïwan","Pékin","Macao"],"b":1,"e":"Au profit du Japon."},{"q":"Le mouvement du 4 mai 1919 proteste contre :","r":["l'opium","les Taiping","le traité de Versailles","la République"],"b":2,"e":"Droits donnés au Japon sur le Shandong."},{"q":"Le Parti communiste chinois est fondé en :","r":["1900","1912","1949","1921"],"b":3,"e":"Il prendra le pouvoir en 1949."},{"q":"La révolte des Taiping dure de :","r":["1850 à 1864","1900 à 1901","1911 à 1912","1839 à 1842"],"b":0,"e":"Des millions de morts."},{"q":"Le palais d'Été est saccagé en :","r":["1842","1860","1900","1911"],"b":1,"e":"Seconde guerre de l'opium."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les dominations étrangères et les nationalismes","situation":"Dans un débat à ton lycée de Kumba, un camarade s'étonne : « La Chine aujourd'hui puissante a-t-elle aussi été dominée comme l'Afrique ? »","tache":"Expliquer la domination subie par la Chine et la comparer à l'Afrique."},"gratuit":true});
VRT_L("1re-c-histoire-inde-indochine",{"c":"1re C","m":"histoire","rang":11,"titre":"L'impérialisme européen en Inde et en Indochine","duree":25,"accroche":"Le joyau de la couronne britannique et la perle de l'empire français.","intro":"En Asie, deux empires coloniaux se construisent au XIXᵉ siècle : l'Inde britannique, « joyau de la couronne », et l'Indochine française. Comme en Afrique, la conquête est suivie d'une exploitation économique et d'une domination politique qui provoquent révoltes et nationalismes.","objectifs":["retracer la conquête de l'Inde par les Britanniques","retracer la formation de l'Indochine française","décrire l'exploitation et les premières résistances"],"parties":[{"t":"L'Inde britannique","html":"<div class='def'><b>Définition</b>Le <strong>Raj britannique</strong> désigne la domination directe de la Couronne britannique sur l'Inde, de 1858 à 1947.</div><ul><li>La <strong>Compagnie anglaise des Indes orientales</strong> s'impose après la bataille de <strong>Plassey</strong> (1757).</li><li>La <strong>révolte des Cipayes</strong> (1857), soldats indiens de la Compagnie, est durement réprimée.</li><li>En <strong>1858</strong>, la Couronne prend le contrôle ; en <strong>1877</strong>, la reine Victoria devient impératrice des Indes.</li><li>Exploitation : coton brut exporté, textiles anglais importés qui ruinent l'artisanat indien ; thé, jute, opium ; chemins de fer vers les ports.</li><li>Le <strong>Congrès national indien</strong> est fondé en <strong>1885</strong>.</li></ul>","retenir":"Plassey (1757), Cipayes (1857), Raj (1858), Victoria impératrice (1877), Congrès (1885)."},{"t":"L'Indochine française","verrou":true},{"t":"Résistances et nationalismes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les colonisations d'Asie et d'Afrique","situation":"Pour un exposé en classe à Bafoussam, ton groupe doit montrer que « la colonisation a suivi les mêmes logiques en Asie et en Afrique ».","tache":"Rédiger le plan détaillé de l'exposé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-texte-descriptif",{"c":"1re C","m":"francais","rang":13,"titre":"Stylistique : le texte descriptif","duree":55,"accroche":"Faire voir avec des mots : l'art du texte descriptif.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe la description d'un marché, on découvre comment elle est organisée et à qui appartient le regard, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les caractéristiques du texte descriptif","repérer l'organisation et le point de vue de la description","dégager les fonctions d'une description"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (description composée pour la leçon) :</p><blockquote>« Au premier plan, les bayam-sellam ont étalé leurs régimes de plantain, jaunes et lourds. Plus loin, sous des parasols délavés, des tas de tomates rouges brillent au soleil. À droite, un vendeur de poisson fumé chasse les mouches d'un geste las. Au fond, la gare routière gronde de klaxons. Une odeur de friture et de terre mouillée flotte sur le tout. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Que décrit le texte ? D'où le regard semble-t-il porté ?</li><li>Relève les indicateurs de lieu : quel ordre suit la description ?</li><li>Relève les adjectifs et les mots qui renvoient aux cinq sens.</li><li>À quel temps sont les verbes ? Pourquoi ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Un marché ; d'un observateur placé à l'entrée, qui regarde du proche au lointain. 2. Au premier plan, plus loin, à droite, au fond : <strong>organisation spatiale</strong> du proche au lointain. 3. Adjectifs : jaunes, lourds, délavés, rouges, fumé, las ; sens : vue (couleurs), ouïe (klaxons), odorat (odeur de friture), toucher (lourds). 4. Présent (ou imparfait dans un récit au passé) : la description arrête le temps, c'est une <strong>pause</strong>.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte descriptif</strong> fait voir un lieu, un objet ou une personne : il suit un <strong>ordre</strong> (spatial, du général au particulier…), adopte un <strong>point de vue</strong> et accumule <strong>expansions</strong> et notations sensorielles.</div>","retenir":"Ordre, point de vue, expansions du nom, cinq sens, présent ou imparfait."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Produire une description organisée et évocatrice","situation":"L'office du tourisme de Kribi organise un concours : « Décrivez les chutes de la Lobé à un visiteur qui ne les a jamais vues. »","tache":"Rédiger une description riche et préciser sa fonction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-introduction-dissertation",{"c":"1re C","m":"francais","rang":17,"titre":"Dissertation : rédiger l'introduction","duree":20,"accroche":"Une introduction réussie, et le correcteur lit la suite avec confiance.","intro":"L'introduction de la dissertation montre au correcteur que le sujet a été compris et que la réflexion est organisée. Elle comprend quatre temps : l'amorce, la présentation du sujet, la problématique et l'annonce du plan. Elle se rédige au brouillon, une fois le plan établi.","objectifs":["connaître les quatre temps de l'introduction","rédiger une amorce pertinente","formuler la problématique et annoncer le plan avec aisance"],"parties":[{"t":"Les quatre temps","html":"<div class='def'><b>Définition</b>L'<strong>introduction</strong> de la dissertation est un paragraphe qui conduit vers le sujet (<strong>amorce</strong>), le <strong>présente</strong> (citation ou reformulation), pose la <strong>problématique</strong> et <strong>annonce le plan</strong>.</div><ol><li><strong>Amorce</strong> : une idée générale en lien direct avec le sujet, un fait d'histoire littéraire, une citation.</li><li><strong>Présentation du sujet</strong> : citation exacte entre guillemets, avec son auteur.</li><li><strong>Problématique</strong> : la question centrale.</li><li><strong>Annonce du plan</strong>.</li></ol>","retenir":"Amorce, sujet, problématique, annonce du plan."},{"t":"Réussir l'amorce et l'annonce","verrou":true},{"t":"Un modèle","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rédiger l'introduction d'une dissertation","situation":"Pour la préparation au Bac, ton professeur à Yaoundé propose : « La lecture des romans est une perte de temps pour un élève de série scientifique. » Discutez.","tache":"Rédiger une introduction complète en quatre temps."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-community-celebrations",{"c":"1re C","m":"anglais","rang":3,"titre":"Vocabulary: interacting with others at community celebrations","duree":20,"accroche":"Could you…? Would you like…? Thank you for having us! Polite English for every celebration.","intro":"National Day, Youth Day, the Ngondo, the Nguon, a wedding or a funeral: community celebrations bring together classmates, neighbours, elders and school authorities. Each situation needs the right words to greet, invite, ask permission, thank and congratulate. This vocabulary is useful for the speaking, dialogue and letter-writing tasks of the exam.","objectifs":["use polite expressions to greet, invite, ask and thank","adapt your register to classmates, neighbours, adults and school authorities","use the vocabulary of community celebrations"],"parties":[{"t":"Celebrations and their vocabulary","html":"<div class='def'><b>Definition</b>A <strong>community celebration</strong> is an event in which members of a community gather to mark an occasion: a <strong>national holiday</strong> (National Day on 20th May, Youth Day on 11th February), a <strong>cultural festival</strong> (the Ngondo of the Sawa, the Nguon of the Bamoun, the Lela of Bali Nyonga), a <strong>wedding</strong>, a <strong>graduation</strong> or a <strong>funeral</strong>.</div><ul><li>Words: <strong>a parade</strong>, <strong>a march-past</strong>, <strong>a rehearsal</strong>, <strong>a guest</strong>, <strong>a host</strong>, <strong>a dignitary</strong>, <strong>a feast</strong>, <strong>traditional dances</strong>, <strong>attire</strong> (clothing for an occasion).</li><li>Verbs: <strong>to celebrate</strong>, <strong>to attend</strong>, <strong>to host</strong>, <strong>to rehearse</strong>, <strong>to march</strong>, <strong>to congratulate</strong>.</li></ul>","retenir":"parade, march-past, rehearsal, guest, host, feast, attire; to attend, to host, to congratulate."},{"t":"Polite expressions and register","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re C","famille":"Vie sociale et culturelle","agir":"Interact politely with others during community celebrations","situation":"Your class in Dschang is organising a cultural evening for Youth Day (11th February). You must invite the principal, the parents and the neighbours.","tache":"Write a formal letter of invitation asking permission to use the school hall."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-jugement",{"c":"1re C","m":"philo","rang":12,"titre":"Le jugement en logique","duree":25,"accroche":"« Tous », « aucun », « quelques » : trois petits mots qui changent la vérité d'une phrase.","intro":"Après le concept vient le jugement : penser, c'est affirmer ou nier quelque chose de quelque chose. « Le paludisme est une maladie » est un jugement. La logique classique les classe selon la quantité et la qualité, et étudie leurs rapports : c'est la base du raisonnement.","objectifs":["définir le jugement et la proposition","classer les jugements selon la quantité et la qualité","distinguer jugement de fait et jugement de valeur"],"parties":[{"t":"Définition et structure","html":"<div class='def'><b>Définition</b>Le <strong>jugement</strong> est l'acte de l'esprit qui <strong>affirme ou nie</strong> un rapport entre deux concepts. Exprimé par des mots, il s'appelle une <strong>proposition</strong>. Il comprend un <strong>sujet</strong> (ce dont on parle), un <strong>prédicat</strong> ou attribut (ce qu'on en dit) et une <strong>copule</strong> (le verbe « être » qui les relie).</div><div class='ex'><b>Exemple</b>« L'homme (sujet) est (copule) mortel (prédicat). »</div><ul><li>Seul le jugement peut être <strong>vrai</strong> ou <strong>faux</strong> : un concept isolé (« arbre ») n'est ni vrai ni faux.</li></ul>","retenir":"Jugement : affirmer ou nier ; proposition ; sujet, copule, prédicat ; seul lieu du vrai et du faux."},{"t":"Quantité et qualité : A, E, I, O","verrou":true},{"t":"Autres classements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Citoyenneté","agir":"Juger avec rigueur et refuser les généralisations abusives","situation":"Après un vol au marché de Bamenda, un commerçant crie : « Les jeunes de ce quartier sont tous des voleurs ! » Un attroupement se forme autour d'un adolescent.","tache":"Rédiger une dissertation courte sur les risques du jugement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-premiere-guerre",{"c":"1re C","m":"histoire","rang":12,"titre":"La Première Guerre mondiale (1914-1918)","duree":25,"accroche":"Une guerre européenne devenue mondiale, jusqu'au Cameroun.","intro":"De 1914 à 1918, la Première Guerre mondiale oppose deux alliances et fait près de 10 millions de morts militaires. Guerre de mouvement puis guerre des tranchées, elle mobilise les économies, les sociétés et les colonies. Au Cameroun allemand, elle se termine par la défaite allemande de 1916.","objectifs":["expliquer les causes de la guerre","décrire les grandes phases du conflit","mesurer son caractère total et mondial"],"parties":[{"t":"Les causes","html":"<div class='def'><b>Définition</b>Une <strong>guerre mondiale</strong> est un conflit qui implique des États de plusieurs continents et mobilise toutes leurs ressources ; on parle de <strong>guerre totale</strong> quand toute la société est mobilisée.</div><ul><li><strong>Causes profondes</strong> : rivalités <strong>coloniales</strong> et <strong>économiques</strong> (Royaume-Uni, Allemagne) ; <strong>nationalismes</strong> (France et l'Alsace-Lorraine, Balkans) ; course aux armements ; <strong>systèmes d'alliances</strong> : Triple-Entente (France, Royaume-Uni, Russie) contre Triple-Alliance (Allemagne, Autriche-Hongrie, Italie).</li><li><strong>Cause immédiate</strong> : l'assassinat de l'archiduc <strong>François-Ferdinand</strong> à <strong>Sarajevo</strong> le <strong>28 juin 1914</strong> ; le jeu des alliances déclenche la guerre en août.</li></ul>","retenir":"Rivalités coloniales et économiques, nationalismes, alliances ; Sarajevo (28 juin 1914)."},{"t":"Les phases de la guerre","verrou":true},{"t":"Une guerre totale et mondiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Montrer les effets de la Première Guerre mondiale sur l'Afrique et le Cameroun","situation":"Ton grand-père, à Yaoundé, affirme : « La guerre de 14-18 était une affaire de Blancs, elle n'a rien changé chez nous. »","tache":"Lui répondre en douze lignes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-texte-argumentatif",{"c":"1re C","m":"francais","rang":16,"titre":"Stylistique : le texte argumentatif","duree":55,"accroche":"Convaincre, persuader, réfuter : le texte qui veut faire changer d'avis.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe une lettre ouverte au maire, on découvre la thèse, les arguments et les procédés pour convaincre et persuader, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les éléments du texte argumentatif","distinguer convaincre et persuader","repérer les marques de l'argumentation"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (lettre composée pour la leçon) :</p><blockquote>« Monsieur le Maire, notre quartier a besoin d'un terrain de sport. D'abord, nos jeunes n'ont aucun lieu pour se dépenser ; ils traînent donc dans la rue. Ensuite, le sport éduque : il apprend la discipline et le respect. Certes, le budget communal est limité ; pourtant, un simple terrain coûte moins cher qu'une seule semaine de délinquance. Monsieur le Maire, pensez à nos enfants : voulez-vous qu'ils grandissent dans la rue ? »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Quelle opinion l'auteur défend-il ? Où est-elle exprimée ?</li><li>Relève les arguments et les mots qui les organisent.</li><li>Quelle objection l'auteur prévoit-il ? Comment y répond-il ?</li><li>Dans la dernière phrase, l'auteur s'adresse-t-il à la raison ou aux sentiments du maire ?</li></ol><details><summary>Voir l'analyse</summary><p>1. La <strong>thèse</strong> : le quartier a besoin d'un terrain de sport (première phrase). 2. Deux <strong>arguments</strong> : l'absence de lieu (avec la conséquence « donc »), la valeur éducative du sport ; <strong>connecteurs</strong> : d'abord, ensuite. 3. <strong>Concession</strong> : « Certes, le budget est limité » ; <strong>réfutation</strong> : « pourtant… » (comparaison de coûts). 4. Aux sentiments : apostrophe, impératif, question rhétorique : il <strong>persuade</strong> après avoir <strong>convaincu</strong>.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte argumentatif</strong> défend une <strong>thèse</strong> par des <strong>arguments</strong> organisés par des connecteurs ; il peut <strong>convaincre</strong> (raison) et <strong>persuader</strong> (sentiments).</div>","retenir":"Thèse, arguments, exemples, connecteurs, concession, convaincre et persuader."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Défendre une opinion par une argumentation organisée","situation":"Le conseil d'établissement de ton lycée à Maroua envisage d'interdire totalement le téléphone portable dans l'enceinte de l'école. Le journal du lycée ouvre ses colonnes aux élèves.","tache":"Rédiger un texte argumentatif pour le journal du lycée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-fonctions-langage",{"c":"1re C","m":"francais","rang":22,"titre":"Communication : les fonctions du langage","duree":55,"accroche":"« Allô ? », « Viens ! », « Ah ! » : chaque phrase a une fonction.","intro":"Leçon de langue (rubrique Communication). On observe des énoncés de la vie quotidienne, on cherche sur quel élément de la communication chacun est centré, puis on formule la règle des six fonctions de Jakobson et on s'entraîne au format de l'épreuve.","objectifs":["rappeler les six éléments de la communication","identifier les six fonctions du langage","repérer la fonction dominante d'un énoncé"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (énoncés composés pour la leçon) :</p><blockquote>1. « Le Mungo prend sa source dans la région du Sud-Ouest. »<br>2. « Ah ! que je suis heureuse de te revoir ! »<br>3. « Ferme la porte, s'il te plaît. »<br>4. « Allô ? Tu m'entends ? Allô ? »<br>5. « “Bayam-sellam” veut dire revendeuse au marché. »<br>6. « Le soleil se couche, la savane s'enflamme, et le soir doucement s'endort sur nos cases. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Pour chaque énoncé, dis qui parle, à qui, et de quoi.</li><li>Sur quel élément l'énoncé insiste-t-il : l'information, le locuteur, le destinataire, le contact, le code ou le message lui-même ?</li><li>Quels indices (pronoms, ponctuation, mode du verbe) le montrent ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Centré sur le <strong>référent</strong> (l'information) : fonction <strong>référentielle</strong> (phrase déclarative, 3e personne). 2. Centré sur l'<strong>émetteur</strong> : fonction <strong>expressive</strong> (interjection, exclamation, « je »). 3. Centré sur le <strong>récepteur</strong> : fonction <strong>conative</strong> (impératif, 2e personne). 4. Centré sur le <strong>canal</strong> : fonction <strong>phatique</strong> (vérifier le contact). 5. Centré sur le <strong>code</strong> : fonction <strong>métalinguistique</strong> (on explique un mot). 6. Centré sur le <strong>message</strong> : fonction <strong>poétique</strong> (rythme, images, sonorités).</p></details><div class='def'><b>Ce que montre l'observation</b>Selon l'élément de la communication sur lequel il insiste, un énoncé remplit une <strong>fonction</strong> différente : on en distingue six (R. Jakobson).</div>","retenir":"Six éléments de la communication, six fonctions."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie économique","agir":"Utiliser les fonctions du langage pour communiquer efficacement","situation":"La coopérative des producteurs de miel d'Oku veut une affiche pour vendre son miel blanc à Bamenda et à Yaoundé.","tache":"Rédiger l'affiche en mobilisant au moins quatre fonctions du langage."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-paragraphe-dissertation",{"c":"1re C","m":"francais","rang":20,"titre":"Dissertation : rédiger un paragraphe argumentatif","duree":20,"accroche":"Un bon paragraphe, c'est une idée, une explication, un exemple analysé.","intro":"Le développement de la dissertation est fait de paragraphes. Chacun défend un seul argument. Le correcteur attend une structure nette : l'argument, son explication, un exemple précis tiré des œuvres, l'analyse de cet exemple, et une phrase de bilan. C'est la méthode « AEI ».","objectifs":["connaître la structure d'un paragraphe argumentatif","choisir et analyser un exemple littéraire","relier les paragraphes par des transitions"],"parties":[{"t":"La structure du paragraphe","html":"<div class='def'><b>Définition</b>Le <strong>paragraphe argumentatif</strong> est l'unité du développement : il défend <strong>un seul argument</strong>, selon l'ordre <strong>A</strong>rgument, <strong>E</strong>xplication, <strong>I</strong>llustration (exemple analysé), et se termine par une phrase de bilan.</div><ul><li><strong>Alinéa</strong> au début, retour à la ligne à la fin.</li><li>Longueur : 10 à 15 lignes environ.</li><li>Un paragraphe = une idée ; deux idées = deux paragraphes.</li></ul>","retenir":"Un argument par paragraphe ; Argument, Explication, Illustration ; phrase de bilan ; alinéa."},{"t":"Choisir et analyser l'exemple","verrou":true},{"t":"Les transitions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rédiger un paragraphe argumentatif structuré","situation":"Sujet proposé au devoir à Bertoua : « La poésie n'est qu'un jeu sur les mots. » Discutez. Un camarade a écrit : « La poésie dit aussi des choses importantes. Par exemple dans un poème de Senghor. »","tache":"Réécrire le passage selon la méthode AEI avec un exemple analysé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-buying-selling",{"c":"1re C","m":"anglais","rang":16,"titre":"Vocabulary: buying and selling at the market","duree":20,"accroche":"How much is it? Can you reduce the price? Here is your change!","intro":"Markets and small stores are part of daily life: we buy foodstuff, clothes, phone credit; we compare prices, bargain and pay. Knowing the vocabulary of buying and selling helps in real life and in the exam, where dialogues at the market and shopping situations are frequent.","objectifs":["use the vocabulary of buying and selling","ask for prices and bargain politely","understand measures, money and payment expressions"],"parties":[{"t":"Words of the market","html":"<div class='def'><b>Definition</b><strong>Buying and selling</strong> is the exchange of goods for money. The <strong>seller</strong> (vendor, trader, shopkeeper) offers <strong>goods</strong>; the <strong>buyer</strong> (customer, client) pays the <strong>price</strong>.</div><ul><li>Places: <strong>a market</strong>, <strong>a stall</strong>, <strong>a store / shop</strong>, <strong>a supermarket</strong>, <strong>a kiosk</strong>.</li><li>Quantities: <strong>a heap</strong> (un tas), <strong>a bunch</strong> (of plantains, un régime), <strong>a bag</strong>, <strong>a kilo</strong>, <strong>a litre</strong>, <strong>a dozen</strong>, <strong>a tin</strong>, <strong>a loaf</strong> (of bread).</li><li>Money: <strong>cash</strong>, <strong>change</strong> (la monnaie rendue), <strong>a receipt</strong>, <strong>mobile money</strong>, <strong>a discount</strong>, <strong>cheap</strong> / <strong>expensive</strong>, <strong>a bargain</strong> (une bonne affaire).</li><li>Extra: <strong>a dash</strong> (Cameroonian English: a small extra gift from the seller).</li></ul>","retenir":"seller, buyer, customer, stall, heap, bunch, change, receipt, discount, cheap, expensive, bargain, dash."},{"t":"Useful expressions","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re C","famille":"Vie économique","agir":"Buy and sell politely and safely at the market","situation":"Your English club in Buea is preparing a short play for the school's cultural week: a scene at the market between a customer, a seller and a pickpocket who is caught.","tache":"Write a dialogue at the market using the vocabulary of buying and selling."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-philo-raisonnement",{"c":"1re C","m":"philo","rang":13,"titre":"Le raisonnement : déduction, induction, analogie","duree":25,"accroche":"Du général au particulier, ou du particulier au général ?","intro":"Raisonner, c'est enchaîner des jugements pour en tirer un nouveau, la conclusion. Le mathématicien déduit, le physicien induit, le médecin raisonne par analogie. Chaque type de raisonnement a sa force et ses limites, et la logique permet d'en mesurer la valeur.","objectifs":["définir le raisonnement","distinguer déduction, induction et analogie","évaluer la valeur de chacun"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>raisonnement</strong> est l'opération de l'esprit qui consiste à tirer une proposition nouvelle, la <strong>conclusion</strong>, d'une ou plusieurs propositions admises, les <strong>prémisses</strong>. Après le concept et le jugement, c'est la troisième opération de l'esprit en logique classique.</div><ul><li>Le lien entre prémisses et conclusion s'appelle l'<strong>inférence</strong>.</li><li>Un raisonnement peut être <strong>nécessaire</strong> (la conclusion découle forcément) ou seulement <strong>probable</strong>.</li></ul>","retenir":"Raisonnement : des prémisses à la conclusion ; inférence ; nécessaire ou probable."},{"t":"Déduction et induction","verrou":true},{"t":"Autres raisonnements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Raisonner avec rigueur à partir de l'expérience","situation":"À Ebolowa, un élève observe que ses trois derniers devoirs faits la nuit ont eu de mauvaises notes. Il conclut : « Travailler la nuit fait toujours échouer. » Son camarade réplique : « Moi, je travaille la nuit et je réussis. »","tache":"Rédiger une dissertation courte sur l'expérience et la vérité générale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-crise-1929",{"c":"1re C","m":"histoire","rang":15,"titre":"La crise économique de 1929","duree":25,"accroche":"Un jeudi d'octobre à New York, et le cacao du Cameroun ne vaut plus rien.","intro":"Le 24 octobre 1929, la Bourse de New York s'effondre. La crise boursière devient une crise bancaire, industrielle, agricole et sociale, puis s'étend au monde entier, colonies comprises. Elle provoque un chômage massif et favorise la montée des régimes totalitaires.","objectifs":["expliquer les causes de la crise de 1929","décrire son extension et ses manifestations","mesurer ses conséquences, en particulier en Afrique et au Cameroun"],"parties":[{"t":"Les causes et le krach","html":"<div class='def'><b>Définition</b>Une <strong>crise économique</strong> est une rupture brutale de la croissance, marquée par la baisse de la production et des prix, les faillites et le chômage. Le <strong>krach</strong> est l'effondrement brutal des cours de la Bourse.</div><ul><li>Dans les années 1920, les États-Unis connaissent une forte croissance (« prospérité ») mais aussi une <strong>surproduction</strong> agricole et industrielle et une <strong>spéculation</strong> boursière, souvent à crédit.</li><li>Le <strong>jeudi 24 octobre 1929</strong> (« jeudi noir »), les cours s'effondrent à <strong>Wall Street</strong> ; la panique continue les jours suivants.</li></ul>","retenir":"Surproduction, spéculation à crédit ; krach de Wall Street, jeudi noir (24 octobre 1929)."},{"t":"Une crise générale et mondiale","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Comprendre la dépendance des économies africaines aux crises mondiales","situation":"En 2020, pendant la pandémie, un commerçant de Douala se plaint : « Quand l'économie mondiale tousse, c'est nous qui tombons malades. » Ton camarade affirme que cela n'est jamais arrivé avant.","tache":"Expliquer, à partir de 1929, comment une crise extérieure touche l'Afrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-conclusion-dissertation",{"c":"1re C","m":"francais","rang":23,"titre":"Dissertation : rédiger la conclusion","duree":20,"accroche":"La dernière impression compte : une conclusion nette laisse le correcteur convaincu.","intro":"La conclusion de la dissertation est le dernier paragraphe que lit le correcteur. Elle fait le bilan du développement, répond clairement à la problématique et ouvre la réflexion. Courte et dense, elle ne doit ni répéter mot pour mot l'introduction ni apporter d'arguments nouveaux.","objectifs":["connaître la structure de la conclusion","formuler une réponse nette à la problématique","proposer une ouverture pertinente"],"parties":[{"t":"Structure de la conclusion","html":"<div class='def'><b>Définition</b>La <strong>conclusion</strong> de la dissertation est le paragraphe final qui fait le <strong>bilan</strong> du développement, apporte une <strong>réponse</strong> à la problématique et propose une <strong>ouverture</strong>.</div><ol><li><strong>Bilan</strong> : reprendre en une phrase chacune les étapes du développement.</li><li><strong>Réponse</strong> : prendre position clairement, en nuançant si nécessaire.</li><li><strong>Ouverture</strong> : élargir à une question voisine.</li></ol>","retenir":"Bilan, réponse, ouverture."},{"t":"Réussir la conclusion","verrou":true},{"t":"Un modèle","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Conclure une dissertation avec netteté","situation":"Ton groupe de travail à Garoua a traité le sujet : « Le théâtre doit-il seulement divertir ? » Plan : I. Le théâtre divertit (rire, spectacle). II. Il instruit et corrige les mœurs (Molière, Oyônô Mbia). III. Il divertit pour mieux instruire.","tache":"Rédiger la conclusion avec bilan, réponse et ouverture."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-figures-construction",{"c":"1re C","m":"francais","rang":31,"titre":"Stylistique : les figures de construction","duree":55,"accroche":"L'ordre des mots aussi a un sens : parallélisme, ellipse, asyndète, polysyndète.","intro":"Leçon de langue (rubrique Stylistique et rhétorique). On observe des phrases d'un discours de fin d'année, on découvre en les manipulant les figures qui jouent sur la construction de la phrase, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les principales figures de construction","en interpréter l'effet","les employer dans ses propres écrits"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (discours composé pour la leçon) :</p><blockquote>1. « Nous avons travaillé, nous avons douté, nous avons réussi. »<br>2. « Et les parents, et les maîtres, et les élèves ont donné le meilleur d'eux-mêmes. »<br>3. « Le travail paie ; la paresse, jamais. »<br>4. « Ce diplôme, nous l'avons mérité. »<br>5. « Riches de savoir, pauvres d'argent, nous partons. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Phrase 1 : que remarques-tu sur les liens entre les propositions et sur leur forme ?</li><li>Phrase 2 : supprime les « et » : quel effet perd-on ?</li><li>Phrase 3 : quel mot manque dans la seconde partie ? Rétablis-le.</li><li>Phrase 4 : écris la phrase dans l'ordre habituel. Qu'est-ce qui est mis en relief ?</li><li>Phrase 5 : comment les deux groupes sont-ils construits ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Les propositions sont <strong>juxtaposées</strong>, sans mot de liaison (<strong>asyndète</strong>), et construites pareil (<strong>parallélisme</strong>), avec une <strong>gradation</strong> jusqu'à « réussi ». 2. La répétition de « et » (<strong>polysyndète</strong>) insiste sur chaque groupe et sur l'union. 3. « paie » est sous-entendu : <strong>ellipse</strong>. 4. « Nous avons mérité ce diplôme » : le COD est détaché en tête et repris par « l' » : <strong>dislocation</strong> (mise en relief). 5. Même construction (adjectif + de + nom) avec des mots opposés : <strong>parallélisme</strong> qui souligne une <strong>antithèse</strong> (riches / pauvres).</p></details><div class='def'><b>Ce que montre l'observation</b>Les <strong>figures de construction</strong> jouent sur l'ordre des mots, leur répétition ou leur suppression : elles donnent du rythme, insistent et mettent en relief.</div>","retenir":"Asyndète, polysyndète, ellipse, parallélisme, dislocation, gradation."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Citoyenneté","agir":"Utiliser les figures de construction pour convaincre","situation":"Le gouvernement des élèves de ton lycée à Bafang lance une campagne contre la tricherie aux examens. On te demande le discours d'ouverture.","tache":"Rédiger un discours mobilisant quatre figures de construction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-quantifiers",{"c":"1re C","m":"anglais","rang":18,"titre":"Grammar: determiners and quantifiers","duree":20,"accroche":"A few or a little? Much or many? Each or every?","intro":"Determiners and quantifiers tell us how much or how many of something there is. They are used every day (shopping, planning, describing) and are frequently tested in Section A of the exam. The key is to know whether the noun is countable or uncountable.","objectifs":["distinguish countable and uncountable nouns","use some, any, no, none, much, many, few, little correctly","use all, both, each, every and most"],"parties":[{"t":"Countable and uncountable nouns","html":"<div class='def'><b>Definition</b><strong>Determiners</strong> are words placed before a noun to specify it (a, the, this, my…). <strong>Quantifiers</strong> are determiners that express <strong>quantity</strong>: some, any, much, many, few, little, all, both, each, every, most, no, none. Their use depends on whether the noun is <strong>countable</strong> (books, oranges) or <strong>uncountable</strong> (water, rice, information, advice).</div><ul><li><strong>many / few / a few</strong> + plural countable: many students, a few oranges.</li><li><strong>much / little / a little</strong> + uncountable: much money, a little sugar.</li><li><strong>How many</strong> students? <strong>How much</strong> rice?</li></ul><div class='attention'><b>Watch out</b><em>information, advice, furniture, luggage, news</em> are uncountable in English: « much information », not « many informations ».</div>","retenir":"many / few + countable ; much / little + uncountable ; information, advice, news: uncountable."},{"t":"Some, any, no, none ; few and a few","verrou":true},{"t":"All, both, each, every, most","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re C","famille":"Citoyenneté","agir":"Express quantities precisely to organise a community activity","situation":"Your class in Bafoussam is organising a clean-up day at the market. You must write the notice that lists what is available and what is missing.","tache":"Write a notice listing what is available and what is missing."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-reglement-premiere-guerre",{"c":"1re C","m":"histoire","rang":14,"titre":"Le règlement de la Première Guerre mondiale","duree":25,"accroche":"Versailles, la SDN, et le Cameroun partagé.","intro":"Après l'armistice du 11 novembre 1918, les vainqueurs réunis à Paris redessinent la carte du monde. Les traités de paix punissent l'Allemagne et démembrent les empires vaincus ; la Société des Nations est créée pour garantir la paix. Les colonies allemandes, dont le Cameroun, sont confiées aux vainqueurs sous forme de mandats.","objectifs":["présenter la conférence de la paix et les principes de Wilson","décrire les principaux traités, dont celui de Versailles","expliquer le système des mandats et le partage du Cameroun"],"parties":[{"t":"La conférence de la paix","html":"<div class='def'><b>Définition</b>Le <strong>règlement de la guerre</strong> désigne l'ensemble des traités et décisions qui fixent les conditions de la paix après 1918 ; un <strong>mandat</strong> est un territoire confié par la SDN à une puissance chargée de l'administrer au nom de la communauté internationale.</div><ul><li>La <strong>conférence de la paix</strong> s'ouvre à Paris en janvier 1919, sans les vaincus ; elle est dominée par les « Quatre » : Wilson (États-Unis), Clemenceau (France), Lloyd George (Royaume-Uni), Orlando (Italie).</li><li>Les <strong>Quatorze Points</strong> du président <strong>Wilson</strong> (8 janvier 1918) : droit des peuples à disposer d'eux-mêmes, liberté des mers, création d'une société des nations.</li></ul>","retenir":"Conférence de Paris (1919), les Quatre, Quatorze Points de Wilson ; mandat."},{"t":"Les traités","verrou":true},{"t":"Les mandats et le Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les origines historiques du bilinguisme camerounais","situation":"Un élève de Buea demande : « Pourquoi le Cameroun a-t-il deux langues officielles héritées de deux colonisateurs différents ? »","tache":"Expliquer le règlement de la Première Guerre mondiale et ses conséquences."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-histoire-cameroun-interets-europeens",{"c":"1re C","m":"histoire","rang":21,"titre":"Le Cameroun au centre des intérêts européens (XVe-XIXe siècle)","duree":25,"accroche":"Des crevettes de l'estuaire au traité de 1884 : quatre siècles de convoitises.","intro":"Bien avant la colonisation, la côte camerounaise attire les Européens : navigateurs portugais, négriers, commerçants, missionnaires. Au XIXᵉ siècle, Britanniques, Allemands et Français se disputent l'influence sur l'estuaire du Wouri. En 1884, l'Allemagne l'emporte par le traité germano-douala.","objectifs":["retracer les premiers contacts entre Européens et Camerounais","présenter les intérêts commerciaux, religieux et politiques au XIXᵉ siècle","expliquer comment l'Allemagne s'empare du Cameroun en 1884"],"parties":[{"t":"Des premiers contacts à la traite","html":"<div class='def'><b>Définition</b>Les <strong>intérêts européens</strong> désignent les motivations économiques, religieuses, scientifiques et politiques qui poussent les puissances européennes à s'implanter sur la côte camerounaise.</div><ul><li>Vers <strong>1472</strong>, le navigateur portugais <strong>Fernando Póo</strong> atteint l'estuaire du Wouri ; les crevettes abondantes lui font nommer le fleuve <strong>Rio dos Camarões</strong> (rivière des crevettes), d'où le nom « Cameroun ».</li><li>Du XVIᵉ au XIXᵉ siècle, la côte participe à la <strong>traite atlantique</strong> : les chefs côtiers (Douala, Bimbia) servent d'intermédiaires.</li><li>Après l'abolition de la traite par le Royaume-Uni (1807), le <strong>commerce dit « légitime »</strong> se développe : huile de palme, ivoire, caoutchouc contre tissus, alcool, armes.</li></ul>","retenir":"Fernando Póo (vers 1472), Rio dos Camarões ; traite atlantique ; commerce « légitime » après 1807."},{"t":"Britanniques, Allemands, Français au XIXᵉ siècle","verrou":true},{"t":"Le traité germano-douala de 1884","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comprendre comment le Cameroun est devenu une colonie","situation":"Au musée maritime de Douala, ton petit frère voit une copie du traité de 1884 et demande : « Pourquoi les rois douala ont-ils signé avec les Allemands ? »","tache":"Expliquer le contexte et le contenu du traité, puis porter un jugement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-formation-mots",{"c":"1re C","m":"francais","rang":34,"titre":"Lexicologie : la formation des mots","duree":55,"accroche":"Ndolè, taxi-moto, BEPC, courriel : comment naissent les mots ?","intro":"Leçon de langue (rubrique Sémantique et lexicologie). On observe des mots entendus au marché et à la radio, on les décompose pour découvrir comment se forment les mots du français, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les procédés de formation des mots","distinguer néologie de forme et néologie de sens","reconnaître les emprunts et leurs usages"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>« Au marché Mokolo, une revendeuse de plantain discute avec un moto-taximan. À la radio, on parle de la déforestation, de l'informatisation des mairies et du covoiturage. Mon petit frère, lui, réclame un portable et un ordi. Le prof d'anglais dit que le <i>week-end</i> est trop court. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Décompose « revendeuse », « déforestation », « informatisation » : quel élément porte le sens de base ? Quels éléments s'y ajoutent ?</li><li>Comment sont formés « moto-taximan » et « covoiturage » ?</li><li>Que remarques-tu sur « ordi » et « prof » ?</li><li>D'où vient « week-end » ?</li><li>« Portable » est-il un nom ou un adjectif ? Comment est-il devenu ce qu'il est ici ?</li></ol><details><summary>Voir l'analyse</summary><p>1. re- + vend + -euse ; dé- + forest + -ation ; informat(ique) + -is(er) + -ation : un <strong>radical</strong> auquel s'ajoutent des <strong>préfixes</strong> (avant) et des <strong>suffixes</strong> (après) : c'est la <strong>dérivation</strong>. 2. « moto-taximan » réunit des mots existants (moto + taxi + -man) : <strong>composition</strong> ; « covoiturage » (co- + voiture + -age) mêle préfixe et suffixe. 3. Ce sont des mots raccourcis : <strong>troncation</strong> (ordinateur, professeur). 4. De l'anglais : c'est un <strong>emprunt</strong>. 5. L'adjectif « portable » est employé comme nom : <strong>conversion</strong> (changement de classe grammaticale).</p></details><div class='def'><b>Ce que montre l'observation</b>Les mots nouveaux se forment par <strong>dérivation</strong>, <strong>composition</strong>, <strong>troncation</strong>, <strong>conversion</strong> ou <strong>emprunt</strong> à une autre langue.</div>","retenir":"Dérivation, composition, troncation, conversion, emprunt."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C","famille":"Vie sociale et culturelle","agir":"Analyser la formation des mots et maîtriser les registres","situation":"Le club de journalisme de ton lycée prépare un petit lexique des mots inventés ou empruntés que les jeunes de Douala utilisent, pour une exposition sur « La vie des mots ».","tache":"Présenter six mots en usage au Cameroun et leur procédé de formation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-francais-structures-phrase",{"c":"1re C","m":"francais","rang":19,"titre":"Morphosyntaxe : juxtaposition, coordination, subordination","duree":55,"accroche":"Une proposition, deux, ou une principale et ses subordonnées ?","intro":"Leçon de langue (rubrique Morphosyntaxe). On observe un même fait divers raconté de plusieurs manières, on découvre en manipulant les phrases comment s'unissent les propositions, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["distinguer phrase simple, composée et complexe","identifier juxtaposition, coordination et subordination","repérer la nature des propositions subordonnées"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>1. « Le car est tombé en panne. Les passagers ont attendu. »<br>2. « Le car est tombé en panne ; les passagers ont attendu. »<br>3. « Le car est tombé en panne, donc les passagers ont attendu. »<br>4. « Comme le car était tombé en panne, les passagers ont attendu. »<br>5. « Les passagers, qui étaient fatigués, ont attendu que le car soit réparé. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Compte les verbes conjugués de chaque phrase : combien de propositions ?</li><li>Comment les propositions sont-elles reliées dans les phrases 2, 3 et 4 ?</li><li>Dans la phrase 4, supprime « Les passagers ont attendu » : la proposition restante peut-elle exister seule ? Et dans la phrase 3, si l'on supprime la première ?</li><li>Dans la phrase 5, quels mots introduisent les propositions dépendantes ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Phrase 1 : deux phrases simples ; phrases 2 à 4 : deux propositions ; phrase 5 : trois. 2. Phrase 2 : par un signe de ponctuation (<strong>juxtaposition</strong>) ; phrase 3 : par « donc » (<strong>coordination</strong>) ; phrase 4 : par « comme » (<strong>subordination</strong>). 3. « Comme le car était tombé en panne » ne peut pas exister seule : elle <strong>dépend</strong> de la principale ; dans la phrase 3, chaque proposition reste autonome. 4. « qui » (pronom relatif) et « que » (conjonction de subordination).</p></details><div class='def'><b>Ce que montre l'observation</b>Une phrase <strong>complexe</strong> réunit plusieurs propositions par <strong>juxtaposition</strong>, <strong>coordination</strong> (propositions autonomes) ou <strong>subordination</strong> (une proposition dépend d'une principale).</div>","retenir":"Juxtaposition et coordination : autonomie ; subordination : dépendance."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Varier la structure des phrases pour mieux raconter","situation":"Le récit d'un camarade de Ngaoundéré n'est fait que de phrases simples : « Le car partit. Il pleuvait. La route était glissante. Le chauffeur roulait vite. Un pneu éclata. Les passagers crièrent. Personne ne fut blessé. »","tache":"Réécrire le récit avec des phrases composées et complexes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-anglais-polite-requests",{"c":"1re C","m":"anglais","rang":15,"titre":"Grammar: polite requests and suggestions","duree":20,"accroche":"Could you…? Would you mind…? Let me… Why don't we…? Politeness is grammar too.","intro":"In English, the way we ask for something or make a suggestion is as important as the request itself. A command like « Give me the book! » sounds rude; « Could you give me the book, please? » is polite. Requests and suggestions are frequent in dialogues and in Section A of the exam.","objectifs":["make polite requests with can, could, would, would you mind","make suggestions with let's, shall we, why don't we, how about","offer help with let me and shall I"],"parties":[{"t":"Polite requests","html":"<div class='def'><b>Definition</b>A <strong>polite request</strong> is a way of asking someone to do something, or asking for permission, without giving an order. A <strong>suggestion</strong> is a proposal of an idea or action.</div><ul><li><strong>Can you</strong> + bare infinitive (informal): <em>Can you pass the salt?</em></li><li><strong>Could you</strong> + bare infinitive (more polite): <em>Could you open the window, please?</em></li><li><strong>Would you</strong> + bare infinitive: <em>Would you help me, please?</em></li><li><strong>Would you mind</strong> + verb-<strong>ing</strong>: <em>Would you mind closing the door?</em> Answer « No, not at all » means you agree!</li><li>Permission: <strong>May I / Could I</strong> + bare infinitive: <em>May I come in?</em> ; <strong>Would you mind if I</strong> + past: <em>Would you mind if I sat here?</em></li></ul>","retenir":"Can / could / would you + bare infinitive ; would you mind + -ing ; may I / could I ; would you mind if I + past."},{"t":"Offers and suggestions","verrou":true},{"t":"Answering","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re C","famille":"Vie sociale et culturelle","agir":"Make polite requests and suggestions in school life","situation":"Your class in Kumba wants to organise a revision weekend at school before the exams. You need the principal's permission and the help of some teachers and parents.","tache":"Write a formal letter requesting permission and making suggestions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r01",{"duree":20,"titre":"L'IA dans les métiers et les filières professionnelles","accroche":"L'IA transforme le travail.","intro":"L'intelligence artificielle s'invite dans presque tous les métiers. Connaître ses usages professionnels aide à choisir sa filière et à se préparer.","objectifs":["citer des usages professionnels de l'IA","identifier les compétences nouvelles","mesurer les effets de l'IA sur l'emploi"],"parties":[{"t":"L'IA au travail","html":"<div class='def'><b>Définition</b>Une <strong>application professionnelle de l'IA</strong> est l'usage d'un système d'intelligence artificielle pour accomplir ou faciliter une tâche de travail : analyser, rédiger, diagnostiquer, prévoir, automatiser.</div><ul><li><strong>santé</strong> : aide au diagnostic sur images ;</li><li><strong>droit et administration</strong> : recherche et résumé de textes ;</li><li><strong>agriculture</strong> : prévision des récoltes, détection des maladies ;</li><li><strong>banque</strong> : détection des fraudes, analyse du risque de crédit ;</li><li><strong>communication</strong> : rédaction, traduction, création d'images.</li></ul>"},{"t":"Effets sur l'emploi","html":"<p>L'IA automatise des tâches répétitives, transforme des métiers et en crée de nouveaux (analyste de données, ingénieur en IA, spécialiste de l'éthique des données). Les compétences clés deviennent : esprit critique, maîtrise des outils numériques, créativité, communication.</p>","retenir":"Automatiser, transformer, créer des métiers.","labo":{"type":"trier","invite":"Choisis un secteur.","items":[["Santé","aide au diagnostic sur images."],["Banque","détection des fraudes et du risque."],["Agriculture","prévision des récoltes."],["Communication","rédaction et traduction assistées."]]}},{"t":"Se préparer","html":"<p>Quelle que soit la filière, l'élève a intérêt à maîtriser les outils, à apprendre à vérifier les résultats d'une IA et à développer les compétences humaines que la machine remplace mal : relation, jugement, sens éthique.</p><div class='attention'><b>Attention</b>l'IA ne supprime pas la responsabilité du professionnel : c'est lui qui répond de la décision.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans un cabinet médical, l'IA peut servir à :</p><ol type='a'><li>signer les ordonnances à la place du médecin</li><li>remplacer définitivement tous les infirmiers</li><li>décider seule des traitements sans aucun contrôle</li><li>analyser des radiographies</li></ol><details><summary>Voir la réponse</summary><p><strong>analyser des radiographies</strong>. Elle aide au diagnostic ; le médecin décide.</p></details><p><strong>Exercice.</strong></p><p>Cite un nouveau métier lié à l'IA.</p><details><summary>Voir la réponse</summary><p>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique."}],"revision":["Usages : santé, droit, agriculture, banque, communication.","Effets : automatisation, transformation, nouveaux métiers.","Compétences : esprit critique, outils, créativité, éthique."],"exo":"<p>Cite un nouveau métier lié à l'IA. <em>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</em></p>","quiz":[{"q":"Dans un cabinet médical, l'IA peut servir à :","r":["signer les ordonnances à la place du médecin","remplacer définitivement tous les infirmiers","décider seule des traitements sans aucun contrôle","analyser des radiographies"],"b":3,"e":"Elle aide au diagnostic ; le médecin décide."},{"q":"L'automatisation par l'IA touche surtout :","r":["les tâches répétitives","les décisions éthiques les plus délicates","les métiers qui demandent de l'empathie","les relations humaines entre collègues"],"b":0,"e":"Saisie, tri, classement, réponses standard."},{"q":"Un métier né avec l'IA est :","r":["porteur d'eau dans les quartiers anciens","ingénieur en données","conducteur de calèche dans les grandes villes","allumeur de réverbères à huile"],"b":1,"e":"Collecte, préparation et analyse des données."},{"q":"Dans le domaine juridique, l'IA peut :","r":["rendre seule les jugements à la place du juge et des avocats","voter les lois à la place des parlementaires","rechercher rapidement des textes et des décisions","arrêter les suspects dans la rue sans policier"],"b":2,"e":"Elle facilite la recherche documentaire."},{"q":"Une compétence essentielle face à l'IA est :","r":["la capacité à tout recopier sans lire","la mémorisation des mots de passe d'autrui","l'utilisation exclusive du papier et du crayon","l'esprit critique"],"b":3,"e":"Il faut juger la qualité des réponses."},{"q":"En agriculture, des drones avec IA permettent :","r":["de surveiller l'état des cultures","de remplacer totalement la pluie et le soleil","de supprimer le besoin de semences de qualité","de récolter sans aucune intervention humaine"],"b":0,"e":"Ils repèrent maladies et manque d'eau."},{"q":"Dans la banque, l'IA sert notamment à :","r":["imprimer elle-même la monnaie nationale","évaluer les risques de crédit","fixer seule le taux directeur de la BEAC","fermer les agences les jours de marché"],"b":1,"e":"Elle analyse l'historique des clients."},{"q":"En communication, l'IA générative aide à :","r":["garantir que toutes les publicités sont vraies et honnêtes","remplacer la loi sur la protection des données","produire des premières versions de textes et de visuels","interdire la publication de toute fausse information"],"b":2,"e":"Le professionnel relit et corrige."},{"q":"L'IA transforme un métier quand :","r":["elle supprime toutes les compétences humaines nécessaires","elle interdit l'usage de l'ordinateur au bureau","elle rend le diplôme inutile pour tous les postes","elle modifie la manière d'exécuter les tâches"],"b":3,"e":"Le métier évolue sans disparaître."},{"q":"Pour se préparer aux métiers de demain, il faut :","r":["apprendre à utiliser les outils d'IA avec éthique","éviter tout contact avec les outils numériques modernes","attendre que l'IA choisisse sa filière à sa place","abandonner les mathématiques et le français à l'école"],"b":0,"e":"Outils, créativité et éthique se complètent."}],"c":"1re C","m":"info","rang":1,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ta cousine, comptable dans une PME de Douala, craint que « l'IA lui prenne son travail » depuis qu'un logiciel saisit automatiquement les factures.","tache":"Montre-lui comment son métier se transforme plutôt qu'il ne disparaît, et propose deux compétences à développer."},"gratuit":true});
VRT_L("1re-c-info-r02",{"duree":20,"titre":"Réalisation d'un projet scolaire assisté par l'IA","accroche":"Travailler avec l'IA, pas la laisser travailler.","intro":"L'IA peut aider à mener un projet scolaire, à condition de garder la maîtrise de chaque étape et de vérifier ce qu'elle produit.","objectifs":["planifier un projet scolaire","utiliser l'IA à chaque étape de façon pertinente","vérifier et déclarer l'usage de l'IA"],"parties":[{"t":"Le projet et l'IA","html":"<div class='def'><b>Définition</b>Un <strong>projet assisté par l'IA</strong> est un travail mené par l'élève dans lequel l'IA intervient comme outil d'aide (idées, plan, explications, relecture), sous son contrôle.</div>"},{"t":"Les étapes","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":2,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ton groupe de quatre élèves doit réaliser en trois semaines un dossier sur le traitement des déchets plastiques à Yaoundé ; un membre propose de « tout demander à l'IA la veille ».","tache":"Propose un plan de travail en cinq étapes où l'IA intervient de façon pertinente, en précisant à chaque étape ce qui reste à la charge du groupe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r03",{"duree":20,"titre":"Cadre juridique et protection des données face à l'IA","accroche":"Nos données nourrissent l'IA.","intro":"Les systèmes d'IA utilisent d'énormes quantités de données, dont des données personnelles. La loi encadre leur collecte et leur usage.","objectifs":["définir une donnée personnelle","connaître le cadre juridique camerounais et international","protéger ses données face aux outils d'IA"],"parties":[{"t":"Données personnelles","html":"<div class='def'><b>Définition</b>Une <strong>donnée personnelle</strong> est toute information qui permet d'identifier une personne directement ou indirectement : nom, numéro de téléphone, photo, voix, adresse, localisation, numéro de compte.</div><p>Certaines sont dites <strong>sensibles</strong> : santé, religion, opinions politiques, données biométriques.</p>"},{"t":"Le cadre juridique","verrou":true},{"t":"Se protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":3,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Pour « faire rire la classe », un élève veut fournir à une application d'IA la photo et des enregistrements vocaux de son professeur afin de produire une fausse vidéo.","tache":"Identifie les données personnelles en jeu, les règles violées et les risques pour l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r04",{"duree":20,"titre":"Biais algorithmiques et équité de l'IA","accroche":"Une IA peut être injuste.","intro":"Une IA apprend à partir de données produites par des humains. Si ces données sont déséquilibrées, ses décisions peuvent être injustes envers certains groupes.","objectifs":["définir un biais algorithmique","en identifier les causes","proposer des moyens de réduire les biais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biais algorithmique</strong> est une erreur systématique d'une IA qui la conduit à traiter de façon injuste ou défavorable certaines personnes ou certains groupes.</div><p>Exemples : reconnaissance faciale moins précise sur les peaux foncées parce que les données d'entraînement contenaient surtout des visages clairs ; outil de recrutement qui défavorise les femmes parce qu'il a appris sur des recrutements passés.</p>"},{"t":"Les causes","verrou":true},{"t":"Vers une IA équitable","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":4,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Une banque teste une IA d'octroi de crédit : sur 1 000 dossiers, elle accepte 62 % des demandes d'hommes et 31 % des demandes de femmes au profil financier comparable.","tache":"Montre qu'il s'agit d'un biais, explique sa cause probable et propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r05",{"duree":20,"titre":"Écriture des algorithmes simples","accroche":"Rappels de base de l'algorithmique.","intro":"Cette leçon révise la structure d'un algorithme, les types de données et les instructions de base avant d'aborder les itérations.","objectifs":["écrire un algorithme complet","utiliser les types et opérateurs","exécuter une trace"],"parties":[{"t":"Rappels","html":"<div class='def'><b>Définition</b>Un <strong>algorithme</strong> est une suite finie et ordonnée d'instructions non ambiguës qui résout un problème. Il comporte un en-tête, une partie déclarative (constantes, variables typées) et un corps (Début ... Fin).</div><p>Types : entier, réel, caractère, chaîne, booléen. Opérateurs : +, −, *, /, div (division entière), mod (reste), comparaisons, ET, OU, NON.</p>"},{"t":"Exemple","verrou":true},{"t":"La trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":5,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un commerçant veut convertir une durée donnée en secondes en heures, minutes et secondes (par exemple 7 384 s).","tache":"Écris l'algorithme utilisant div et mod, puis fais sa trace pour 7 384 s."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r06",{"duree":20,"titre":"Les structures itératives","accroche":"Répéter efficacement.","intro":"Les boucles permettent de répéter un traitement sans réécrire les instructions. On distingue Pour, Tant que et Répéter ... Jusqu'à.","objectifs":["écrire les trois boucles","choisir la boucle adaptée","éviter les boucles infinies"],"parties":[{"t":"Les trois boucles","html":"<div class='def'><b>Définition</b>Une <strong>structure itérative</strong> (boucle) répète un bloc d'instructions un certain nombre de fois ou tant qu'une condition est remplie.</div><pre>Pour i ← 1 à n Faire ... FinPour\nTant que condition Faire ... FinTantque\nRépéter ... Jusqu'à condition</pre>"},{"t":"Choisir","verrou":true},{"t":"Exemple : somme de 1 à n","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":6,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une épargnante place 100 000 F sur un compte à 5 % d'intérêts par an (intérêts composés) et veut savoir au bout de combien d'années elle aura au moins 150 000 F.","tache":"Écris l'algorithme avec une boucle Tant que et donne le résultat attendu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r07",{"duree":20,"titre":"Les structures de données","accroche":"Ranger plusieurs valeurs sous un même nom.","intro":"Pour traiter les notes de 40 élèves, déclarer 40 variables serait absurde. On utilise des structures de données comme les tableaux et les enregistrements.","objectifs":["définir une structure de données","déclarer un tableau","déclarer un enregistrement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>structure de données</strong> est une manière d'organiser plusieurs données en mémoire pour les manipuler facilement. Un <strong>tableau</strong> regroupe un nombre fixe d'éléments de même type, repérés par un <strong>indice</strong>.</div>"},{"t":"Les tableaux","verrou":true},{"t":"Les enregistrements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":7,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"La bibliothèque du lycée veut gérer 500 livres, chacun ayant un titre, un auteur, une année et un état (disponible ou emprunté).","tache":"Propose une structure de données adaptée en déclarant le type et la variable nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r08",{"duree":20,"titre":"Opérations sur les tableaux","accroche":"Remplir, parcourir, calculer.","intro":"Les tableaux se manipulent presque toujours avec des boucles : saisie, affichage, somme, recherche du maximum, comptage.","objectifs":["remplir et afficher un tableau","calculer somme et moyenne","rechercher le maximum et compter des éléments"],"parties":[{"t":"Remplir et afficher","html":"<div class='def'><b>Définition</b><strong>Parcourir un tableau</strong>, c'est accéder successivement à chacun de ses éléments, généralement avec une boucle Pour de l'indice de début à l'indice de fin.</div><pre>Pour i ← 1 à n Faire\n   Lire(T[i])\nFinPour</pre>"},{"t":"Somme, moyenne, maximum","verrou":true},{"t":"Compter et décaler","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":8,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Les températures maximales de Garoua pendant 7 jours sont relevées dans un tableau : 38, 41, 40, 43, 39, 42, 37.","tache":"Écris l'algorithme qui calcule la moyenne, la température maximale et le nombre de jours à plus de 40 °C, puis donne les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r09",{"duree":20,"titre":"Exécution d'un algorithme utilisant les tableaux","accroche":"Suivre pas à pas un traitement de tableau.","intro":"Pour vérifier un algorithme sur un tableau, on fait une trace qui suit l'indice et le contenu des cases.","objectifs":["construire une trace avec un tableau","détecter une erreur par la trace","exécuter un algorithme d'inversion"],"parties":[{"t":"La trace d'un tableau","html":"<div class='def'><b>Définition</b><strong>Exécuter un algorithme à la main</strong>, c'est simuler son fonctionnement en notant, à chaque étape, la valeur des variables et le contenu du tableau.</div>"},{"t":"Exemple : inverser un tableau","verrou":true},{"t":"Détecter les erreurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":9,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un camarade a écrit : Pour i ← 1 à 4 Faire T[i] ← T[i + 1] FinPour, pour décaler vers la gauche le tableau T = [4 ; 6 ; 8 ; 10 ; 12].","tache":"Fais la trace de cet algorithme et donne le contenu final de T, puis explique ce qu'il fait."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r10",{"duree":20,"titre":"Fonctions et procédures","accroche":"Découper un problème en sous-problèmes.","intro":"Un long algorithme devient lisible quand on le découpe en sous-algorithmes réutilisables : les fonctions et les procédures.","objectifs":["distinguer fonction et procédure","déclarer et appeler un sous-algorithme","expliquer l'intérêt de la modularité"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>sous-algorithme</strong> est un bloc d'instructions nommé, appelé depuis l'algorithme principal. Une <strong>fonction</strong> renvoie une valeur ; une <strong>procédure</strong> exécute une action sans renvoyer de valeur.</div>"},{"t":"Syntaxe","verrou":true},{"t":"Intérêts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":10,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un programme de gestion de notes doit calculer plusieurs fois la moyenne de trois notes avec coefficients et afficher une appréciation (« Bien » à partir de 14, « Passable » de 10 à 14, « Insuffisant » sinon).","tache":"Écris une fonction de moyenne et une procédure d'appréciation, puis montre comment les appeler."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r11",{"duree":20,"titre":"Modes de passage des paramètres","accroche":"Par valeur ou par adresse.","intro":"Quand on appelle un sous-algorithme, ses paramètres peuvent recevoir une copie de la valeur ou désigner directement la variable d'origine.","objectifs":["distinguer paramètres formels et effectifs","distinguer passage par valeur et par référence","choisir le mode adapté"],"parties":[{"t":"Paramètres","html":"<div class='def'><b>Définition</b>Les <strong>paramètres formels</strong> sont ceux écrits dans la déclaration du sous-algorithme ; les <strong>paramètres effectifs</strong> sont les valeurs ou variables fournies lors de l'appel.</div>"},{"t":"Les deux modes","verrou":true},{"t":"Choisir","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":11,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une procédure Augmenter(p : entier) contient p ← p + 500. Dans l'algorithme principal, prix ← 2000 puis Augmenter(prix) ; Écrire(prix).","tache":"Indique la valeur affichée et explique-la, puis corrige la procédure pour que le prix soit réellement augmenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r12",{"duree":20,"titre":"Exécution d'un algorithme intégrant fonctions et procédures","accroche":"Suivre les appels.","intro":"Exécuter à la main un algorithme qui appelle des sous-algorithmes demande de suivre le passage des paramètres et le retour des valeurs.","objectifs":["tracer un appel de fonction","suivre les variables locales","vérifier le passage des paramètres"],"parties":[{"t":"La pile d'appels","html":"<div class='def'><b>Définition</b>Lors d'un <strong>appel</strong>, l'exécution passe au sous-algorithme avec ses paramètres ; à la fin, elle revient à l'instruction qui suit l'appel, avec la valeur renvoyée pour une fonction.</div>"},{"t":"Exemple","verrou":true},{"t":"Méthode de trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":12,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Fonction F(n : entier) : entier ; Début : Si n mod 2 = 0 Alors Retourner n div 2 Sinon Retourner 3 * n + 1 FinSi ; FinFonction. L'algorithme principal part de x ← 6 et applique x ← F(x) jusqu'à obtenir 1, en comptant les étapes.","tache":"Fais la trace complète et donne le nombre d'étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r13",{"duree":20,"titre":"Installation d'un compilateur","accroche":"Préparer son poste pour programmer en C.","intro":"Pour programmer en C, il faut un compilateur qui traduit le code source en programme exécutable, souvent intégré à un environnement de développement.","objectifs":["définir compilateur et environnement de développement","installer un compilateur C","compiler un premier programme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>compilateur</strong> traduit un programme écrit dans un langage de haut niveau (C) en langage machine exécutable. Un <strong>environnement de développement intégré</strong> (EDI) réunit un éditeur, un compilateur et un débogueur (Code::Blocks, Dev-C++, Visual Studio Code avec GCC).</div>"},{"t":"Installer","html":"<ol><li>Télécharger un EDI depuis son site officiel, de préférence avec le compilateur inclus (par exemple Code::Blocks avec MinGW/GCC).</li><li>Lancer l'installation et accepter les options par défaut.</li><li>Vérifier que l'EDI détecte le compilateur dans ses réglages.</li><li>Créer un projet « Console application » en C.</li></ol>","retenir":"Éditeur + compilateur + débogueur = EDI.","labo":{"type":"etapes","items":[["Télécharger","EDI avec compilateur."],["Installer","options par défaut."],["Vérifier","compilateur détecté."],["Créer","un projet console."],["Compiler et exécuter","Build and run."]]}},{"t":"Premier programme","html":"<pre>#include &lt;stdio.h&gt;\nint main(void)\n{\n   printf(\"Bonjour le Cameroun !\\n\");\n   return 0;\n}</pre><p>Compiler puis exécuter (« Build and run ») : la console affiche le message. Les étapes de la compilation : prétraitement, compilation, édition des liens.</p><div class='attention'><b>Attention</b>un message d'erreur de compilation indique la ligne : on lit le premier message en priorité.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Un compilateur transforme :</p><ol type='a'><li>le code source en programme exécutable</li><li>un programme exécutable en image affichable</li><li>un texte en fichier audio</li><li>un tableur en base de données</li></ol><details><summary>Voir la réponse</summary><p><strong>le code source en programme exécutable</strong>. Langage C → exécutable.</p></details><p><strong>Exercice.</strong></p><p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ?</p><details><summary>Voir la réponse</summary><p>(Réponse : stdio.h.)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Compilateur : source → exécutable.","EDI : éditeur, compilateur, débogueur (Code::Blocks, GCC).","Premier programme : include, main, printf, return 0."],"exo":"<p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ? <em>(Réponse : stdio.h.)</em></p>","quiz":[{"q":"Un compilateur transforme :","r":["le code source en programme exécutable","un programme exécutable en image affichable","un texte en fichier audio","un tableur en base de données"],"b":0,"e":"Langage C → exécutable."},{"q":"Code::Blocks est :","r":["un système d'exploitation libre pour les serveurs","un environnement de développement intégré","un tableur en ligne","un antivirus gratuit"],"b":1,"e":"EDI : éditeur, compilateur, débogueur."},{"q":"GCC est :","r":["un navigateur web","un logiciel de dessin","un compilateur C","un traitement de texte"],"b":2,"e":"GNU Compiler Collection."},{"q":"Un EDI regroupe notamment :","r":["un clavier, une souris et un écran","un tableur, un traitement de texte et un antivirus","une imprimante, un scanner et un modem","un éditeur, un compilateur et un débogueur"],"b":3,"e":"Integrated Development Environment."},{"q":"Tout programme C commence son exécution par la fonction :","r":["main","printf","scanf","include"],"b":0,"e":"C'est le point d'entrée."},{"q":"return 0; à la fin de main signifie :","r":["que le programme a rencontré une erreur","que le programme s'est bien terminé","que le programme recommence au début","que l'affichage est effacé"],"b":1,"e":"Code de retour 0 = succès."},{"q":"Le fichier source d'un programme C porte l'extension :","r":[".exe",".html",".c",".docx"],"b":2,"e":"Par exemple bonjour.c."},{"q":"Le débogueur sert à :","r":["traduire automatiquement le programme en langue anglaise","imprimer le code source en couleur","installer automatiquement le compilateur","exécuter pas à pas pour trouver les erreurs"],"b":3,"e":"Points d'arrêt, inspection des variables."},{"q":"Dev-C++ est :","r":["un EDI pour le langage C","un tableur pour les programmeurs","un réseau social","un système de fichiers"],"b":0,"e":"Comme Code::Blocks."},{"q":"Une erreur de compilation est signalée :","r":["uniquement après l'exécution","avec la ligne concernée","par un son de l'ordinateur","jamais par le compilateur"],"b":1,"e":"On corrige puis on recompile."}],"c":"1re C","m":"info","rang":13,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Dans la salle informatique, Code::Blocks affiche « Can't find compiler executable » quand un élève clique sur « Build ».","tache":"Explique la cause de ce message et la démarche pour corriger le problème."},"gratuit":true});
VRT_L("1re-c-info-r14",{"duree":20,"titre":"Bibliothèques et fonctions d'entrée/sortie en C","accroche":"Lire et afficher en langage C.","intro":"Le langage C s'appuie sur des bibliothèques standard. Les fonctions printf et scanf de stdio.h permettent d'afficher et de lire des données.","objectifs":["inclure une bibliothèque","afficher avec printf","lire avec scanf"],"parties":[{"t":"Bibliothèques","html":"<div class='def'><b>Définition</b>Une <strong>bibliothèque</strong> est un ensemble de fonctions déjà écrites, que l'on rend disponibles par une directive <code>#include</code>. Exemples : stdio.h (entrées-sorties), math.h (fonctions mathématiques), string.h (chaînes).</div>"},{"t":"Afficher et lire","verrou":true},{"t":"Déclarations et types","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":14,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève veut écrire un programme C qui lit le prix unitaire d'un cahier et la quantité, puis affiche le montant à payer ; son programme se compile mais plante dès la saisie.","tache":"Écris un programme correct et indique l'erreur la plus probable de l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r15",{"duree":20,"titre":"Structures itératives en C","accroche":"Les boucles for, while et do while.","intro":"Les boucles de l'algorithmique se traduisent directement en C par for, while et do ... while.","objectifs":["traduire une boucle Pour en for","traduire Tant que et Répéter","écrire un programme avec boucle"],"parties":[{"t":"Correspondances","html":"<div class='def'><b>Définition</b>En C, une <strong>boucle</strong> s'écrit avec <code>for</code> (Pour), <code>while</code> (Tant que) ou <code>do ... while</code> (Répéter ... Jusqu'à, avec la condition inversée).</div>"},{"t":"Syntaxe","verrou":true},{"t":"Opérateurs utiles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":15,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un programme doit afficher la table de multiplication d'un nombre lu au clavier (de 1 à 10) et redemander le nombre tant qu'il n'est pas compris entre 1 et 12.","tache":"Écris le programme C en utilisant do ... while et for."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r16",{"duree":20,"titre":"Tableaux et fichiers multimédias dans une page web","accroche":"Structurer et enrichir une page HTML.","intro":"Le langage HTML décrit le contenu d'une page web à l'aide de balises. On peut y insérer des tableaux, des images, du son et de la vidéo.","objectifs":["créer un tableau HTML","insérer image, audio et vidéo","respecter la structure d'une page"],"parties":[{"t":"Les tableaux","html":"<div class='def'><b>Définition</b>Le <strong>HTML</strong> (HyperText Markup Language) est le langage de description des pages web ; il utilise des <strong>balises</strong> comme &lt;p&gt; ... &lt;/p&gt;. Un tableau se construit avec &lt;table&gt;, des lignes &lt;tr&gt;, des cellules d'en-tête &lt;th&gt; et des cellules &lt;td&gt;.</div><pre>&lt;table&gt;\n  &lt;tr&gt;&lt;th&gt;Région&lt;/th&gt;&lt;th&gt;Chef-lieu&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;Littoral&lt;/td&gt;&lt;td&gt;Douala&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</pre>"},{"t":"Les médias","verrou":true},{"t":"Fusion de cellules","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":16,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Pour le site du club de tourisme, tu dois créer une page présentant trois sites touristiques (nom, région, photo) et une courte vidéo de présentation stockée dans le dossier videos.","tache":"Décris le code HTML de la page : tableau avec images et insertion de la vidéo."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r17",{"duree":20,"titre":"Création des formulaires","accroche":"Recueillir des informations sur le web.","intro":"Un formulaire HTML permet à l'utilisateur de saisir des informations : inscription, contact, commande.","objectifs":["créer un formulaire","utiliser les principaux champs","rendre un formulaire clair et accessible"],"parties":[{"t":"Le formulaire","html":"<div class='def'><b>Définition</b>Un <strong>formulaire</strong> est une zone de page web, délimitée par &lt;form&gt;, qui contient des champs de saisie et un bouton d'envoi transmettant les données à un programme (attribut action).</div>"},{"t":"Les champs","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":17,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le lycée veut un formulaire d'inscription au tournoi de football : nom, classe (liste), poste (gardien, défenseur, milieu, attaquant : un seul choix), téléphone, et acceptation du règlement.","tache":"Indique pour chaque information le champ HTML adapté et ses attributs essentiels."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r18",{"duree":20,"titre":"Mise en forme d'une page web avec le CSS","accroche":"Séparer le fond et la forme.","intro":"Le HTML décrit le contenu ; le CSS (Cascading Style Sheets) décrit sa présentation : couleurs, polices, marges, disposition.","objectifs":["définir le CSS","écrire des règles CSS","lier une feuille de style à une page"],"parties":[{"t":"Le CSS","html":"<div class='def'><b>Définition</b>Le <strong>CSS</strong> est le langage qui décrit la présentation des pages HTML. Une <strong>règle</strong> se compose d'un sélecteur et de déclarations propriété : valeur.</div><pre>h1 { color: #142554; text-align: center; }\np { font-family: Arial, sans-serif; font-size: 16px; }\n.important { background-color: #FFC93C; }\n#menu { margin: 0; padding: 10px; }</pre>"},{"t":"Les sélecteurs","verrou":true},{"t":"Intégrer le CSS","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":18,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club compte six pages dont chacune contient ses propres attributs de couleur ; le président veut changer la couleur de tous les titres en une seule opération.","tache":"Explique pourquoi une feuille de style externe résout le problème et écris la règle et la ligne de liaison nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r19",{"duree":20,"titre":"Organisation des dossiers d'un site web","accroche":"Une arborescence claire pour un site qui fonctionne.","intro":"Un site web est un ensemble de fichiers liés entre eux. Une bonne organisation des dossiers évite les liens cassés et facilite la mise en ligne.","objectifs":["organiser l'arborescence d'un site","écrire des chemins relatifs","créer des liens entre pages"],"parties":[{"t":"L'arborescence","html":"<div class='def'><b>Définition</b>L'<strong>arborescence d'un site</strong> est l'organisation de ses fichiers en dossiers : la page d'accueil index.html à la racine, et des dossiers par type de ressource.</div><pre>monsite/\n   index.html\n   contact.html\n   css/style.css\n   images/logo.png\n   js/script.js\n   pages/activites.html</pre>"},{"t":"Les chemins relatifs","verrou":true},{"t":"Règles de nommage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":19,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club fonctionne sur l'ordinateur de Paul, mais après copie sur une clé et ouverture sur un autre poste, aucune image ne s'affiche ; ses balises contiennent src=\"C:\\Users\\Paul\\Desktop\\Photo Club.JPG\".","tache":"Explique la cause du problème et propose une organisation et un chemin corrects."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r20",{"duree":20,"titre":"Introduction au JavaScript","accroche":"Rendre une page web interactive.","intro":"HTML structure, CSS présente, JavaScript fait agir : il réagit aux clics, calcule, modifie la page sans la recharger.","objectifs":["situer JavaScript par rapport à HTML et CSS","insérer un script dans une page","utiliser alert, console.log et document"],"parties":[{"t":"Rôle de JavaScript","html":"<div class='def'><b>Définition</b><strong>JavaScript</strong> est un langage de programmation interprété par le navigateur, qui permet de rendre une page web interactive : réagir aux actions de l'utilisateur, effectuer des calculs, modifier le contenu de la page.</div>"},{"t":"Insérer un script","verrou":true},{"t":"Agir sur la page","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":20,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Sur la page d'accueil du club, un paragraphe d'identifiant « date » doit afficher automatiquement la date du jour, et un message de bienvenue doit apparaître dans la console.","tache":"Écris le script et indique où le placer."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r21",{"duree":20,"titre":"Variables et instructions d'entrée/sortie en JavaScript","accroche":"Lire et afficher en JavaScript.","intro":"Comme en algorithmique, un programme JavaScript manipule des variables et échange des informations avec l'utilisateur.","objectifs":["déclarer des variables","lire une donnée","afficher un résultat"],"parties":[{"t":"Variables","html":"<div class='def'><b>Définition</b>En JavaScript, une <strong>variable</strong> se déclare avec <code>let</code> (valeur modifiable) ou <code>const</code> (valeur fixe). Les types sont dynamiques : nombre, chaîne, booléen, tableau, objet.</div><pre>let nom = \"Awa\";\nconst TVA = 0.1925;\nlet age = 16;</pre>"},{"t":"Entrées et sorties","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":21,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève écrit : let a = prompt(\"a ?\"); let b = prompt(\"b ?\"); alert(a + b); il saisit 15 et 10 et obtient 1510.","tache":"Explique le résultat et corrige le programme."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r22",{"duree":20,"titre":"Opérations de base en JavaScript","accroche":"Calculer et comparer.","intro":"JavaScript dispose d'opérateurs arithmétiques, de comparaison et logiques, ainsi que de l'objet Math pour les calculs.","objectifs":["utiliser les opérateurs arithmétiques","utiliser les comparaisons et opérateurs logiques","utiliser l'objet Math"],"parties":[{"t":"Opérateurs","html":"<div class='def'><b>Définition</b>Un <strong>opérateur</strong> est un symbole qui réalise une opération sur des valeurs : +, −, *, / (division), % (reste), ** (puissance).</div><pre>let r = 17 % 5;   // 2\nlet p = 2 ** 10;  // 1024\nlet q = Math.floor(17 / 5); // 3</pre>"},{"t":"Comparaisons et logique","verrou":true},{"t":"L'objet Math","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":22,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une boutique en ligne applique une remise de 15 % si le montant dépasse 20 000 F et si le client est membre.","tache":"Écris l'instruction JavaScript qui calcule le montant à payer à partir de montant et membre (booléen), arrondi au franc."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r23",{"duree":20,"titre":"Traduction des algorithmes en JavaScript","accroche":"De l'algorithme au programme.","intro":"Les structures de l'algorithmique se traduisent presque mot pour mot en JavaScript.","objectifs":["traduire les structures alternatives","traduire les boucles","traduire les tableaux"],"parties":[{"t":"Table de correspondance","html":"<div class='def'><b>Définition</b><strong>Traduire un algorithme</strong>, c'est réécrire chacune de ses instructions dans la syntaxe d'un langage de programmation, sans changer sa logique.</div><ul><li>x ← 5 → <code>x = 5;</code></li><li>Si ... Alors ... Sinon → <code>if (...) { } else { }</code></li><li>Pour i ← 1 à n → <code>for (let i = 1; i &lt;= n; i++) { }</code></li><li>Tant que → <code>while (...) { }</code></li><li>Tableau[1..n] → <code>let t = [];</code> (indices à partir de 0)</li></ul>"},{"t":"Exemple","verrou":true},{"t":"Les fonctions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":23,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"L'algorithme suivant compte les élèves admis : nb ← 0 ; Pour i ← 1 à n : Si T[i] ≥ 10 Alors nb ← nb + 1 ; Écrire(nb).","tache":"Traduis-le en une fonction JavaScript qui reçoit un tableau de notes, puis donne le résultat pour [9, 14, 10, 7, 16]."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r24",{"duree":20,"titre":"Fonctions et évènements en JavaScript","accroche":"Réagir aux actions de l'utilisateur.","intro":"Une page devient interactive quand des fonctions s'exécutent en réponse à des évènements : clic, saisie, chargement.","objectifs":["écrire une fonction JavaScript","associer une fonction à un évènement","modifier la page en réponse"],"parties":[{"t":"Évènements","html":"<div class='def'><b>Définition</b>Un <strong>évènement</strong> est une action détectée par le navigateur : clic (click), saisie (input), survol (mouseover), chargement de la page (load), envoi d'un formulaire (submit). Un <strong>gestionnaire d'évènement</strong> est la fonction exécutée quand il se produit.</div>"},{"t":"Associer une fonction","verrou":true},{"t":"Lire un champ","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":24,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une page doit calculer l'indice de masse corporelle (IMC = poids ÷ taille²) quand on clique sur « Calculer », à partir de deux champs d'identifiants poids et taille.","tache":"Écris la fonction et l'association à l'évènement, avec un affichage arrondi à une décimale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r25",{"duree":20,"titre":"Programmation d'un convertisseur","accroche":"Un projet complet en HTML, CSS et JavaScript.","intro":"Ce projet réunit les acquis : une page avec un formulaire, une présentation soignée et un script qui convertit des valeurs.","objectifs":["concevoir l'interface d'un convertisseur","programmer la conversion","tester et améliorer l'application"],"parties":[{"t":"Le projet","html":"<div class='def'><b>Définition</b>Un <strong>convertisseur</strong> est une application qui transforme une valeur d'une unité dans une autre : francs CFA en euros, degrés Celsius en Fahrenheit, kilomètres en miles.</div><p>Rappel : 1 euro = 655,957 F CFA (parité fixe).</p>"},{"t":"Le code","verrou":true},{"t":"Tester","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":25,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un vendeur de pièces détachées de Douala reçoit des prix en euros de ses fournisseurs et veut une page qui convertit un montant en euros en F CFA, en ajoutant 10 % de frais de transport.","tache":"Écris la fonction de conversion et donne le résultat pour 250 €."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r26",{"duree":20,"titre":"Besoins matériels pour l'installation d'un système d'exploitation","accroche":"Vérifier avant d'installer.","intro":"Avant d'installer un système d'exploitation, on vérifie que l'ordinateur dispose des ressources minimales demandées.","objectifs":["définir un système d'exploitation","lire une configuration minimale","vérifier la compatibilité d'un ordinateur"],"parties":[{"t":"Le système d'exploitation","html":"<div class='def'><b>Définition</b>Le <strong>système d'exploitation</strong> (SE) est le logiciel de base qui gère le matériel (processeur, mémoire, disques, périphériques) et permet l'exécution des applications. Exemples : Windows, Linux (Ubuntu), macOS, Android.</div>"},{"t":"La configuration requise","verrou":true},{"t":"Vérifier un poste","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":26,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un système demande au minimum un processeur 64 bits, 4 Go de RAM et 64 Go d'espace disque. Le vieil ordinateur du secrétariat possède un processeur 64 bits, 2 Go de RAM et 120 Go de disque dont 70 Go libres.","tache":"Indique si l'installation est possible et propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r27",{"duree":20,"titre":"Installation d'un système d'exploitation","accroche":"Les étapes d'une installation propre.","intro":"Installer un système d'exploitation suit une démarche précise, de la sauvegarde des données à la configuration du premier compte.","objectifs":["préparer une installation","suivre les étapes d'installation","partitionner un disque"],"parties":[{"t":"Préparer","html":"<div class='def'><b>Définition</b>L'<strong>installation d'un système d'exploitation</strong> consiste à copier ses fichiers sur le disque, à préparer ce disque et à configurer les réglages de base pour que l'ordinateur démarre sur ce système.</div><ol><li>Sauvegarder les données personnelles.</li><li>Créer un support d'installation (clé USB démarrable) depuis l'image officielle.</li><li>Régler l'ordre de démarrage dans le BIOS/UEFI pour démarrer sur la clé.</li></ol>"},{"t":"Installer","verrou":true},{"t":"Partitions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":27,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Le technicien de ton lycée doit réinstaller le système d'un ordinateur infecté contenant les bulletins de l'année non sauvegardés.","tache":"Décris dans l'ordre les étapes à suivre, en insistant sur celle qui protège les bulletins."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r28",{"duree":20,"titre":"Configuration d'un système d'exploitation","accroche":"Adapter le système à l'utilisateur.","intro":"Après l'installation, on configure le système : comptes, pilotes, réseau, mises à jour, sécurité et personnalisation.","objectifs":["créer et gérer des comptes utilisateurs","installer des pilotes","régler mises à jour, réseau et sécurité"],"parties":[{"t":"Les comptes","html":"<div class='def'><b>Définition</b><strong>Configurer un système d'exploitation</strong>, c'est régler ses paramètres pour l'adapter au matériel et aux utilisateurs : comptes, pilotes, réseau, sécurité, apparence.</div><p>Un compte <strong>administrateur</strong> peut installer des logiciels et modifier les réglages ; un compte <strong>standard</strong> a des droits limités. Pour un poste partagé (salle informatique), les élèves utilisent des comptes standards.</p>"},{"t":"Pilotes et périphériques","verrou":true},{"t":"Réseau, mises à jour, sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":28,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Après installation, l'imprimante du secrétariat n'imprime que des caractères incompréhensibles et la résolution de l'écran est très faible ; tous les employés utilisent le compte administrateur.","tache":"Identifie les causes de ces problèmes et propose une configuration correcte."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r29",{"duree":20,"titre":"Introduction à l'invite de commandes","accroche":"Commander l'ordinateur au clavier.","intro":"L'invite de commandes permet de piloter l'ordinateur en tapant des instructions. Elle est rapide et indispensable aux techniciens.","objectifs":["définir l'invite de commandes","ouvrir l'interpréteur","se repérer dans l'arborescence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>invite de commandes</strong> (interface en ligne de commande) est une interface textuelle dans laquelle l'utilisateur tape des commandes interprétées par le système : cmd ou PowerShell sous Windows, le terminal (bash) sous Linux.</div>"},{"t":"Se repérer","html":"<p>L'invite affiche le dossier courant, par exemple <code>C:\\Users\\Eleve&gt;</code>. Commandes de base sous Windows :</p><ul><li><code>cd dossier</code> : entrer dans un dossier ; <code>cd ..</code> : remonter ;</li><li><code>dir</code> : lister le contenu (ls sous Linux) ;</li><li><code>cls</code> : effacer l'écran (clear sous Linux) ;</li><li><code>cd \\</code> : revenir à la racine du lecteur (C:\\) ;</li><li><code>help</code> : aide.</li></ul><p>Pour ouvrir l'invite : touches Windows + R, taper <code>cmd</code>, puis Entrée (ou rechercher « Invite de commandes » dans le menu Démarrer).</p>","retenir":"cd, dir, cls, help.","labo":{"type":"trier","invite":"Choisis une commande.","items":[["cd","changer de dossier."],["cd ..","remonter au dossier parent."],["dir","lister le contenu du dossier."],["cls","effacer l'écran."]]}},{"t":"Intérêt","html":"<p>Exécuter des tâches rapides ou répétitives, diagnostiquer le réseau, gérer un ordinateur à distance, écrire des scripts d'automatisation.</p><div class='attention'><b>Attention</b>certaines commandes suppriment des fichiers sans passer par la corbeille : on vérifie avant d'appuyer sur Entrée.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'invite de commandes est :</p><ol type='a'><li>un logiciel de dessin vectoriel</li><li>une interface textuelle</li><li>un navigateur web</li><li>un tableur</li></ol><details><summary>Voir la réponse</summary><p><strong>une interface textuelle</strong>. On tape des commandes au clavier.</p></details><p><strong>Exercice.</strong></p><p>Quelle commande permet de remonter d'un dossier ?</p><details><summary>Voir la réponse</summary><p>(Réponse : cd ..)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Invite : interface textuelle (cmd, PowerShell, bash).","cd, cd .., dir, cls, help.","Rapidité, diagnostic, scripts."],"exo":"<p>Quelle commande permet de remonter d'un dossier ? <em>(Réponse : cd ..)</em></p>","quiz":[{"q":"L'invite de commandes est :","r":["un logiciel de dessin vectoriel","une interface textuelle","un navigateur web","un tableur"],"b":1,"e":"On tape des commandes au clavier."},{"q":"Sous Windows, l'invite de commandes s'ouvre avec :","r":["paint","calc","cmd","notepad"],"b":2,"e":"Windows + R, puis cmd."},{"q":"La commande cd sert à :","r":["créer un nouveau dossier vide","copier un fichier","effacer l'écran","changer de dossier"],"b":3,"e":"Change directory."},{"q":"cd .. permet de :","r":["remonter au dossier parent","entrer dans le dernier dossier","supprimer le dossier courant","copier le dossier"],"b":0,"e":"Un niveau plus haut."},{"q":"cd \\ permet de :","r":["remonter d'un seul dossier dans l'arborescence","revenir à la racine du lecteur","ouvrir le bureau","fermer l'invite"],"b":1,"e":"Par exemple C:\\."},{"q":"La commande dir sert à :","r":["supprimer le dossier courant","renommer un fichier","lister le contenu du dossier","tester le réseau"],"b":2,"e":"Équivalent de ls sous Linux."},{"q":"La commande cls sert à :","r":["fermer l'ordinateur","copier un fichier","lister les fichiers","effacer l'écran"],"b":3,"e":"De l'anglais clear screen."},{"q":"Sous Linux, l'équivalent de dir est :","r":["ls","cd","rm","cp"],"b":0,"e":"De l'anglais list (lister)."},{"q":"L'invite C:\\Users\\Eleve&gt; indique :","r":["le nom de l'imprimante","le dossier courant","l'adresse IP","la date du jour"],"b":1,"e":"On se trouve dans Eleve."},{"q":"Un intérêt de l'invite de commandes est :","r":["d'afficher de belles images en haute définition","de retoucher des photos","d'automatiser des tâches répétitives","de jouer à des jeux vidéo"],"b":2,"e":"Par des scripts."}],"c":"1re C","m":"info","rang":29,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"L'invite affiche C:\\Users\\Eleve> et tu dois afficher le contenu du dossier C:\\Users\\Eleve\\Documents\\Projets.","tache":"Écris la suite de commandes à taper et explique chacune."},"gratuit":true});
VRT_L("1re-c-info-r30",{"duree":20,"titre":"Utilisation de l'invite de commandes","accroche":"Gérer fichiers et réseau en ligne de commande.","intro":"Au-delà de la navigation, l'invite de commandes permet de créer, copier, renommer et supprimer des fichiers, et de diagnostiquer le réseau.","objectifs":["gérer des fichiers et dossiers","utiliser des commandes réseau","écrire un petit script"],"parties":[{"t":"Fichiers et dossiers","html":"<div class='def'><b>Définition</b>Une <strong>commande</strong> est une instruction tapée dans l'invite, composée d'un nom et éventuellement de paramètres (arguments) qui précisent sur quoi elle agit.</div><ul><li><code>mkdir Projet</code> : créer un dossier ;</li><li><code>copy a.txt b.txt</code> : copier ;</li><li><code>ren ancien.txt nouveau.txt</code> : renommer un fichier ou un dossier (<code>ren Mathematiques Informatique</code>) ;</li><li><code>del fichier.txt</code> : supprimer un fichier ;</li><li><code>rmdir Projet</code> : supprimer un dossier vide.</li></ul>"},{"t":"Commandes réseau","verrou":true},{"t":"Les scripts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":30,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un poste de la salle informatique n'accède plus à internet. Le technicien veut savoir si la carte réseau a une adresse IP et si un serveur extérieur répond.","tache":"Indique les commandes à utiliser, dans l'ordre, et ce que chacune permet de conclure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r31",{"duree":20,"titre":"Concepts fondamentaux de la sécurité informatique","accroche":"Confidentialité, intégrité, disponibilité.","intro":"La sécurité informatique protège les informations et les systèmes contre les menaces. Elle repose sur quelques objectifs fondamentaux.","objectifs":["définir la sécurité informatique","citer les objectifs de sécurité","distinguer menace, vulnérabilité et risque"],"parties":[{"t":"Les objectifs","html":"<div class='def'><b>Définition</b>La <strong>sécurité informatique</strong> est l'ensemble des moyens techniques, organisationnels et humains qui protègent les systèmes d'information et leurs données.</div><ul><li><strong>confidentialité</strong> : seules les personnes autorisées accèdent à l'information ;</li><li><strong>intégrité</strong> : l'information n'est pas modifiée sans autorisation ;</li><li><strong>disponibilité</strong> : l'information est accessible quand on en a besoin ;</li><li><strong>authentification</strong> : on vérifie l'identité de l'utilisateur ;</li><li><strong>non-répudiation</strong> : on ne peut nier une action effectuée.</li></ul>"},{"t":"Menace, vulnérabilité, risque","verrou":true},{"t":"Le facteur humain","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":31,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Dans un cybercafé, le mot de passe administrateur est écrit sur un papier collé à l'écran, l'antivirus n'est pas à jour et une panne électrique a rendu le serveur inaccessible deux jours.","tache":"Pour chaque fait, identifie la vulnérabilité ou l'objectif de sécurité touché et propose une mesure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r32",{"duree":20,"titre":"Introduction à la cybercriminalité et à la cybersécurité","accroche":"Connaître les attaques pour s'en protéger.","intro":"Les cybercriminels utilisent de nombreuses techniques pour voler des données ou de l'argent. La cybersécurité organise la défense.","objectifs":["définir cybercriminalité et cybersécurité","décrire les principales attaques","connaître les acteurs de la cybersécurité au Cameroun"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>cybercriminalité</strong> regroupe les infractions commises au moyen ou contre des systèmes informatiques ; la <strong>cybersécurité</strong> est l'ensemble des mesures qui protègent le cyberespace contre ces attaques.</div>"},{"t":"Les principales attaques","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":32,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Ta tante reçoit un SMS : « Vous avez gagné 500 000 F. Envoyez 5 000 F de frais et votre code secret au numéro ci-dessous pour recevoir votre gain. »","tache":"Identifie le type d'attaque, deux indices qui la trahissent et la conduite à tenir."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r33",{"duree":20,"titre":"Techniques de protection des données","accroche":"Sauvegarder, chiffrer, contrôler l'accès.","intro":"Protéger les données passe par des techniques complémentaires : mots de passe solides, sauvegardes, chiffrement, antivirus et mises à jour.","objectifs":["créer un mot de passe robuste","mettre en place une stratégie de sauvegarde","expliquer le chiffrement"],"parties":[{"t":"Contrôler l'accès","html":"<div class='def'><b>Définition</b>La <strong>protection des données</strong> est l'ensemble des mesures qui empêchent leur perte, leur vol ou leur modification non autorisée.</div><p>Un mot de passe robuste compte au moins 12 caractères, mêle majuscules, minuscules, chiffres et symboles, et n'est utilisé que pour un seul compte. L'<strong>authentification à deux facteurs</strong> ajoute un code reçu par SMS ou une application.</p>"},{"t":"Sauvegarder","verrou":true},{"t":"Chiffrer et protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":33,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un cybercafé de Bamenda conserve toutes les fiches de ses clients sur un seul ordinateur, protégé par le mot de passe « cyber2020 », sans aucune sauvegarde.","tache":"Identifie trois risques et propose un plan de protection en trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r34",{"duree":20,"titre":"Notions sur les images numériques","accroche":"Pixels, définition et couleurs.","intro":"Une image numérique est une grille de points colorés. Sa qualité dépend du nombre de points et de la manière de coder les couleurs.","objectifs":["définir pixel, définition et résolution","expliquer le codage RVB","comparer les formats d'images"],"parties":[{"t":"Pixels et définition","html":"<div class='def'><b>Définition</b>Un <strong>pixel</strong> est le plus petit point d'une image matricielle. La <strong>définition</strong> est le nombre de pixels (largeur × hauteur, par exemple 1920 × 1080) ; la <strong>résolution</strong> est le nombre de pixels par unité de longueur (pixels par pouce, ppp).</div>"},{"t":"Le codage des couleurs","verrou":true},{"t":"Les formats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":34,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le journal du lycée veut publier un logo avec un fond transparent et des photos d'un match ; un élève propose de tout enregistrer en BMP « pour la qualité ».","tache":"Conseille le format adapté à chaque image et explique pourquoi le BMP n'est pas un bon choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r35",{"duree":20,"titre":"Calcul de la résolution et de la taille des fichiers multimédias","accroche":"Combien pèse une image, un son, une vidéo ?","intro":"La taille d'un fichier multimédia non compressé se calcule à partir de ses caractéristiques. Ces calculs aident à choisir supports et formats.","objectifs":["calculer la taille d'une image","calculer la taille d'un son","estimer la taille d'une vidéo"],"parties":[{"t":"Taille d'une image","html":"<div class='def'><b>Définition</b>La <strong>taille d'un fichier</strong> est la quantité de mémoire qu'il occupe, exprimée en octets et ses multiples.</div><p><strong>Taille (octets) = largeur × hauteur × profondeur de couleur (en octets)</strong>. Exemple : 1920 × 1080 × 3 = 6 220 800 octets ≈ 5,9 Mo. Dimension imprimée : pixels ÷ résolution (ppp) ; 3000 pixels à 300 ppp donnent 10 pouces, soit 25,4 cm.</p>"},{"t":"Taille d'un son","verrou":true},{"t":"Taille d'une vidéo","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":35,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le club radio du lycée enregistre une émission de 5 minutes en qualité CD (44 100 Hz, 16 bits, stéréo) et veut l'envoyer par une messagerie limitée à 16 Mo par fichier.","tache":"Calcule la taille du fichier non compressé et conclus, puis propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r36",{"duree":20,"titre":"Notion d'entreprise","accroche":"L'organisation qui produit.","intro":"Pour comprendre les systèmes d'information, il faut d'abord comprendre l'entreprise : ses activités, sa structure et ses flux.","objectifs":["définir l'entreprise","décrire ses fonctions","identifier les flux d'informations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>entreprise</strong> est une organisation qui combine des moyens humains, matériels et financiers pour produire des biens ou des services destinés à être vendus.</div><p>Elle peut être classée selon sa taille (TPE, PME, grande entreprise), son statut (publique, privée, mixte) ou son secteur.</p>"},{"t":"Fonctions et structure","verrou":true},{"t":"Les flux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":36,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une PME de transformation de manioc à Ebolowa reçoit des commandes par téléphone, les note sur des papiers volants, et oublie souvent des livraisons ; les factures sont faites à la main.","tache":"Identifie les flux en jeu et les problèmes d'information, puis propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r37",{"duree":20,"titre":"Introduction aux systèmes d'information (1)","accroche":"L'information, ressource de l'organisation.","intro":"Toute organisation produit, stocke et utilise des informations. Le système d'information organise ces activités.","objectifs":["définir le système d'information","décrire ses fonctions","distinguer SI et système informatique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>système d'information</strong> (SI) est l'ensemble organisé de ressources (personnes, données, procédures, matériels, logiciels) qui permet de collecter, mémoriser, traiter et diffuser l'information utile à une organisation.</div>"},{"t":"Les quatre fonctions","verrou":true},{"t":"SI et système informatique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":37,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, les notes sont saisies par les enseignants dans un logiciel, la moyenne est calculée automatiquement, et les bulletins sont imprimés puis remis aux parents.","tache":"Associe chaque étape à une fonction du SI et cite deux ressources humaines et deux ressources techniques de ce système."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r38",{"duree":20,"titre":"Introduction aux systèmes d'information (2)","accroche":"Composants, acteurs et niveaux de décision.","intro":"Ce second volet étudie les composants du SI, ses utilisateurs et le rôle de l'information dans la prise de décision.","objectifs":["décrire les composants du SI","identifier les niveaux de décision","connaître les qualités d'une information utile"],"parties":[{"t":"Les composants","html":"<div class='def'><b>Définition</b>Les <strong>composants d'un SI</strong> sont les ressources humaines (utilisateurs, informaticiens), les ressources matérielles (ordinateurs, réseaux), les ressources logicielles (applications, bases de données), les données et les procédures (règles de fonctionnement).</div>"},{"t":"Les niveaux de décision","verrou":true},{"t":"Une information utile","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":38,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le directeur d'une chaîne de trois pharmacies reçoit les chiffres de ventes avec un mois de retard et découvre trop tard des ruptures de stock de médicaments contre le paludisme.","tache":"Identifie les défauts de l'information reçue et propose une amélioration du SI."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r39",{"duree":20,"titre":"Notion de base de données","accroche":"Stocker des données organisées et partagées.","intro":"Les fichiers séparés entraînent doublons et incohérences. La base de données regroupe les informations de façon structurée et partagée.","objectifs":["définir une base de données","citer les avantages par rapport aux fichiers","donner des exemples d'utilisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>base de données</strong> est un ensemble structuré de données enregistrées sur un support, organisées pour être facilement consultées, mises à jour et partagées par plusieurs utilisateurs.</div>"},{"t":"Avantages","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":39,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, l'adresse d'un élève figure dans trois fichiers différents (scolarité, cantine, infirmerie) ; après son déménagement, seul le fichier de scolarité a été corrigé.","tache":"Explique le problème et montre comment une base de données le résout."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r40",{"duree":20,"titre":"Notion de table","accroche":"Lignes, colonnes et clés.","intro":"Dans une base de données relationnelle, les informations sont rangées dans des tables liées entre elles par des clés.","objectifs":["définir table, enregistrement et champ","identifier une clé primaire","relier deux tables par une clé étrangère"],"parties":[{"t":"Table, champ, enregistrement","html":"<div class='def'><b>Définition</b>Une <strong>table</strong> est un ensemble de données organisé en colonnes et en lignes. Une colonne est un <strong>champ</strong> (attribut) avec un type ; une ligne est un <strong>enregistrement</strong> (n-uplet).</div><p>Exemple : table ELEVE (matricule, nom, prenom, date_naissance, classe).</p>"},{"t":"La clé primaire","verrou":true},{"t":"La clé étrangère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":40,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une bibliothèque veut enregistrer ses livres et ses emprunts : chaque emprunt concerne un livre et un élève, à une date donnée.","tache":"Propose trois tables avec leurs champs, en soulignant les clés primaires et en indiquant les clés étrangères."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r41",{"duree":20,"titre":"Notion de SGBD","accroche":"Le logiciel qui gère la base.","intro":"Une base de données est gérée par un logiciel spécialisé, le SGBD, qui permet de la créer, de l'interroger et de la protéger.","objectifs":["définir un SGBD","citer ses fonctions","donner des exemples de SGBD"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>système de gestion de base de données</strong> (SGBD) est un logiciel qui permet de créer, de stocker, de consulter, de modifier et de protéger les données d'une base, tout en gérant les accès de plusieurs utilisateurs.</div>"},{"t":"Les fonctions","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":41,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une petite pharmacie gère ses stocks dans un tableur ; deux employés modifient le fichier en même temps et écrasent mutuellement leurs saisies, et n'importe qui peut supprimer des lignes.","tache":"Montre comment un SGBD résoudrait ces deux problèmes et propose un SGBD adapté."},"verrou":true,"nq":10,"labo":true});
